-- khatma_sql_23 — ختمة التدبر: محتوى الجزء الثاني (المواضيع ٢٠ – ٣٥، سورة البقرة ١٤٢ – ٢٥٢)
-- مختصر من «أيسر التفاسير» للشيخ أبي بكر جابر الجزائري رحمه الله، و«الخاطرة» من فريق العمل.
-- يُشغَّل بعد khatma_sql_19 وkhatma_sql_24. المواضيع تُضاف مخفية (pub=false) للمراجعة من المالك فقط. إعادة تشغيله آمنة: رقم المراجعة يزيد فقط لو تغيّر المحتوى.
-- =====================================================================

-- 20. سورة البقرة ١٤٢ – ١٥٢ · تحويل القبلة إلى الكعبة
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (20, 2, 142, 152, 'سورة البقرة ١٤٢ – ١٥٢', 'تحويل القبلة إلى الكعبة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 20) = $j$[{"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "۞سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٤٢﴾ وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ ﴿١٤٣﴾", "w": [["السفهاء", "خفاف العقول الذين لا يحسنون التصرف، وهم هنا اليهود والمنافقون والمشركون."], ["ما ولّاهم", "ما الذي صرفهم عن استقبال بيت المقدس إلى استقبال الكعبة."], ["القبلة", "الجهة التي يستقبلها المصلي ويجعلها قبالته."], ["وسطاً", "الوسط خيار الشيء وأعدله، والمراد أن أمة محمد ﷺ خير الأمم وأعدلها."], ["ينقلب على عقبيه", "يرجع إلى الكفر بعد الإيمان."], ["لكبيرة", "شاقة على النفس لا تُحتمل إلا بجهد، لأنها تحويل من قبلة مألوفة إلى قبلة جديدة."], ["إيمانكم", "صلاتكم التي صليتموها إلى بيت المقدس قبل التحول إلى الكعبة."], ["رؤوف رحيم", "يدفع الضرر عنكم ويفيض الإحسان عليكم."]], "m": "أخبر الله رسوله والمؤمنين بما سيقوله السفهاء قبل أن يقولوه، ليخفّ وقع الطعن عليهم؛ فمفاجأة المكروه شديدة، فإذا عُلم سلفاً هان أمره. وسيقولون: ما الذي صرف المسلمين عن قبلتهم؟ وعلّمهم الله جوابهم: «لله المشرق والمغرب» فلا اعتراض عليه، يوجّه عباده حيث شاء ويهدي من يشاء إلى صراط مستقيم. ثم بيّن أنه جعل هذه الأمة وسطاً، أي خياراً عدولاً، ليشهدوا على الأمم يوم القيامة إذا أنكرت أن رسلها بلّغتها، ويشهد عليهم رسولهم. وأخبر أن تحويل القبلة اختبار يتميّز به من يتبع الرسول ممن يرجع إلى الكفر، وأنه شاق إلا على من هداهم الله. وطمأن الذين صلوا إلى بيت المقدس نحو سبعة عشر شهراً بأن أجر صلاتهم محفوظ، فلا يضيعه الله، وفي هذا رأفته ورحمته بعباده.", "h": ["جواز النسخ في الإسلام، ومنه نسخ الصلاة إلى بيت المقدس بالصلاة إلى الكعبة.", "الأراجيف وتهويل الأمور من شأن الكفار مع المسلمين، فعلى المؤمنين أن يثبتوا حتى يظهر الباطل وتنتهي الفتنة.", "أفضلية أمة الإسلام على سائر الأمم، لكونها أمة الوسط، والوسطية شعارها.", "الابتلاء سنة جارية في المؤمن.", "من صلى إلى غير القبلة وهو لا يعلم، بعد أن اجتهد في معرفتها، صحت صلاته وله أجرها، ولا إعادة عليه."], "k": "حين يتغيّر شيء مألوف في حياتي بأمر الله، هل أستقبله بالرضا والتسليم كما استقبله أصحاب النبي ﷺ؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ ﴿١٤٤﴾ وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿١٤٥﴾ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ ﴿١٤٦﴾ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿١٤٧﴾", "w": [["تقلّب وجهك", "تردد نظرك إلى السماء مرة بعد مرة انتظاراً لنزول الوحي."], ["فلنولينّك", "فلنحوّلنّك."], ["شطر المسجد الحرام", "جهة المسجد الحرام. واستقبال الجهة يحصل به استقبال الكعبة."], ["أنه الحق من ربهم", "أن تحويل القبلة منصوص عليه في كتبهم السابقة."], ["يعرفونه", "الضمير للرسول ﷺ، أي يعلمون أنه نبي الله ورسوله لما في كتبهم من صفاته الواضحة."], ["الممترين", "الشاكين، والامتراء: الشك وعدم التصديق."]], "m": "يخبر الله رسوله أنه كان يراه يقلّب وجهه في السماء ينتظر وحياً يأمره باستقبال الكعبة بدل بيت المقدس؛ رغبةً في مخالفة اليهود وحباً لقبلة أبيه إبراهيم، فهي أول القبلات وأفضلها. فأمره بتوجيه وجهه شطر المسجد الحرام، وأمر المؤمنين أن يستقبلوه حيثما كانوا. وروي أنه كان يصلي الظهر في مسجد بني سلمة، فصلى ركعتين إلى بيت المقدس وركعتين إلى الكعبة، ولذلك سُمّي مسجد القبلتين. وأخبر أن علماء أهل الكتاب يعرفون أن تحويل القبلة حق من الله، وأن ما أثاروه حوله من تشويش لن يخفى على الله. ولو جاءهم النبي ﷺ بكل آية ما تبعوا قبلته، فلا النصارى يصلّون إلى بيت المقدس قبلة اليهود، ولا اليهود يصلّون إلى المشرق قبلة النصارى. وحذّر رسوله من اتباع أهوائهم بعد ما جاءه من العلم. وبيّن أنهم يعرفونه كما يعرفون أبناءهم، ولكن فريقاً منهم يكتمون الحق وهم يعلمون، وأن ما هو عليه حق من ربه فلا يكون من الشاكين.", "h": ["وجوب استقبال القبلة في الصلاة، وفي أي مكان كان المصلي.", "كفر كثير من أهل الكتاب كان عن علم، إيثاراً للدنيا على الآخرة.", "حرمة موافقة أهل الكتاب على بدعة من بدعهم الدينية مهما كانت.", "علماء أهل الكتاب في زمن النبي ﷺ كانوا يعرفون أنه النبي المبشَّر به، وأعرضوا عن الإيمان به وعن متابعته إيثاراً للدنيا."], "k": "هل أعرف الحق أحياناً ثم يمنعني عن اتباعه حرصي على مكسب دنيوي أو خوفي من كلام الناس؟"}, {"lbl": "الآيات ١٤٨ – ١٥٢", "q": "وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٤٨﴾ وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿١٤٩﴾ وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٥٠﴾ كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ ﴿١٥١﴾ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ﴿١٥٢﴾", "w": [["ولكل وجهة هو موليها", "لكل أهل ملة، كالإسلام واليهودية والنصرانية، قبلة يتجهون إليها في صلاتهم."], ["فاستبقوا الخيرات", "سارعوا إلى الطاعات والأعمال الصالحة."], ["حجة", "الدليل القوي الذي يغلب به صاحبه خصمه."], ["ولأتم نعمتي", "نعم الله كثيرة وأعظمها نعمة الإسلام، وتمامها بمواصلة التشريع إلى كماله في حجة الوداع بعرفات، حيث نزل قوله تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾."], ["يزكيكم", "يطهركم من الذنوب والأخلاق السيئة."], ["الحكمة", "السنة النبوية."], ["الشكر", "إظهار النعمة بصرفها فيما من أجله وهبها الله."], ["الكفر", "جحد النعمة وإخفاؤها وصرفها في غير ما يحب الله."]], "m": "بعد أن قرّر الله أن أهل الكتاب لن يتبعوا قبلة النبي ﷺ ولو جاءهم بكل آية، وأن بعضهم لا يتبع قبلة بعض، أخبر أن لكل أمة قبلة تتجه إليها. فأمر المسلمين أن يتركوا أهل الملل الضالة وأن يسابقوا في الخيرات شكراً على نعمة الهداية إلى قبلة أبيهم إبراهيم، فإن الله يجمعهم يوم القيامة ويجازيهم بأعمالهم. ثم أمر رسوله أن يولّي وجهه شطر المسجد الحرام حيث كان، في الحضر أو في السفر، وأن تحويله إلى الكعبة حق ثابت من ربه. وأمر الجميع بالثبات على ذلك حتى لا يكون لأعدائهم حجة، إذ يقول اليهود: ينكرون ديننا ويستقبلون قبلتنا، ويقول المشركون: يدّعون ملة إبراهيم ويخالفون قبلته. أما الظالمون المكابرون فلا سبيل إلى إقناعهم، فلا تخشوهم واخشوني. وكل ذلك ليتم الله نعمته عليهم بالهداية إلى أحسن الشرائع، كما أنعم عليهم بإرسال رسول منهم يتلو عليهم آياته ويطهّرهم ويعلّمهم الكتاب والحكمة وما لم يكونوا يعلمون. وختم بالأمر بذكره وشكره وعدم كفران نعمته.", "h": ["وجوب شكر الله على نعمه الظاهرة والباطنة.", "وجوب تعلم العلم الضروري ليتمكن العبد من عبادة الله عبادة تزكّي نفسه.", "وجوب ذكر الله بالتهليل والتكبير والتسبيح، وشكره بطاعته.", "حرمة نسيان ذكر الله وكفران نعمه بترك شكرها."], "k": "ما النعمة التي أنعم الله بها عليّ ولم أشكرها بعدُ بعمل صالح؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 20;
insert into public.tdb_cards(topic, i, body) select 20, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٤٢ – ١٤٣", "q": "۞سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٤٢﴾ وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ ﴿١٤٣﴾", "w": [["السفهاء", "خفاف العقول الذين لا يحسنون التصرف، وهم هنا اليهود والمنافقون والمشركون."], ["ما ولّاهم", "ما الذي صرفهم عن استقبال بيت المقدس إلى استقبال الكعبة."], ["القبلة", "الجهة التي يستقبلها المصلي ويجعلها قبالته."], ["وسطاً", "الوسط خيار الشيء وأعدله، والمراد أن أمة محمد ﷺ خير الأمم وأعدلها."], ["ينقلب على عقبيه", "يرجع إلى الكفر بعد الإيمان."], ["لكبيرة", "شاقة على النفس لا تُحتمل إلا بجهد، لأنها تحويل من قبلة مألوفة إلى قبلة جديدة."], ["إيمانكم", "صلاتكم التي صليتموها إلى بيت المقدس قبل التحول إلى الكعبة."], ["رؤوف رحيم", "يدفع الضرر عنكم ويفيض الإحسان عليكم."]], "m": "أخبر الله رسوله والمؤمنين بما سيقوله السفهاء قبل أن يقولوه، ليخفّ وقع الطعن عليهم؛ فمفاجأة المكروه شديدة، فإذا عُلم سلفاً هان أمره. وسيقولون: ما الذي صرف المسلمين عن قبلتهم؟ وعلّمهم الله جوابهم: «لله المشرق والمغرب» فلا اعتراض عليه، يوجّه عباده حيث شاء ويهدي من يشاء إلى صراط مستقيم. ثم بيّن أنه جعل هذه الأمة وسطاً، أي خياراً عدولاً، ليشهدوا على الأمم يوم القيامة إذا أنكرت أن رسلها بلّغتها، ويشهد عليهم رسولهم. وأخبر أن تحويل القبلة اختبار يتميّز به من يتبع الرسول ممن يرجع إلى الكفر، وأنه شاق إلا على من هداهم الله. وطمأن الذين صلوا إلى بيت المقدس نحو سبعة عشر شهراً بأن أجر صلاتهم محفوظ، فلا يضيعه الله، وفي هذا رأفته ورحمته بعباده.", "h": ["جواز النسخ في الإسلام، ومنه نسخ الصلاة إلى بيت المقدس بالصلاة إلى الكعبة.", "الأراجيف وتهويل الأمور من شأن الكفار مع المسلمين، فعلى المؤمنين أن يثبتوا حتى يظهر الباطل وتنتهي الفتنة.", "أفضلية أمة الإسلام على سائر الأمم، لكونها أمة الوسط، والوسطية شعارها.", "الابتلاء سنة جارية في المؤمن.", "من صلى إلى غير القبلة وهو لا يعلم، بعد أن اجتهد في معرفتها، صحت صلاته وله أجرها، ولا إعادة عليه."], "k": "حين يتغيّر شيء مألوف في حياتي بأمر الله، هل أستقبله بالرضا والتسليم كما استقبله أصحاب النبي ﷺ؟"}, {"lbl": "الآيات ١٤٤ – ١٤٧", "q": "قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ ﴿١٤٤﴾ وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ ﴿١٤٥﴾ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ ﴿١٤٦﴾ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ ﴿١٤٧﴾", "w": [["تقلّب وجهك", "تردد نظرك إلى السماء مرة بعد مرة انتظاراً لنزول الوحي."], ["فلنولينّك", "فلنحوّلنّك."], ["شطر المسجد الحرام", "جهة المسجد الحرام. واستقبال الجهة يحصل به استقبال الكعبة."], ["أنه الحق من ربهم", "أن تحويل القبلة منصوص عليه في كتبهم السابقة."], ["يعرفونه", "الضمير للرسول ﷺ، أي يعلمون أنه نبي الله ورسوله لما في كتبهم من صفاته الواضحة."], ["الممترين", "الشاكين، والامتراء: الشك وعدم التصديق."]], "m": "يخبر الله رسوله أنه كان يراه يقلّب وجهه في السماء ينتظر وحياً يأمره باستقبال الكعبة بدل بيت المقدس؛ رغبةً في مخالفة اليهود وحباً لقبلة أبيه إبراهيم، فهي أول القبلات وأفضلها. فأمره بتوجيه وجهه شطر المسجد الحرام، وأمر المؤمنين أن يستقبلوه حيثما كانوا. وروي أنه كان يصلي الظهر في مسجد بني سلمة، فصلى ركعتين إلى بيت المقدس وركعتين إلى الكعبة، ولذلك سُمّي مسجد القبلتين. وأخبر أن علماء أهل الكتاب يعرفون أن تحويل القبلة حق من الله، وأن ما أثاروه حوله من تشويش لن يخفى على الله. ولو جاءهم النبي ﷺ بكل آية ما تبعوا قبلته، فلا النصارى يصلّون إلى بيت المقدس قبلة اليهود، ولا اليهود يصلّون إلى المشرق قبلة النصارى. وحذّر رسوله من اتباع أهوائهم بعد ما جاءه من العلم. وبيّن أنهم يعرفونه كما يعرفون أبناءهم، ولكن فريقاً منهم يكتمون الحق وهم يعلمون، وأن ما هو عليه حق من ربه فلا يكون من الشاكين.", "h": ["وجوب استقبال القبلة في الصلاة، وفي أي مكان كان المصلي.", "كفر كثير من أهل الكتاب كان عن علم، إيثاراً للدنيا على الآخرة.", "حرمة موافقة أهل الكتاب على بدعة من بدعهم الدينية مهما كانت.", "علماء أهل الكتاب في زمن النبي ﷺ كانوا يعرفون أنه النبي المبشَّر به، وأعرضوا عن الإيمان به وعن متابعته إيثاراً للدنيا."], "k": "هل أعرف الحق أحياناً ثم يمنعني عن اتباعه حرصي على مكسب دنيوي أو خوفي من كلام الناس؟"}, {"lbl": "الآيات ١٤٨ – ١٥٢", "q": "وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٤٨﴾ وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ﴿١٤٩﴾ وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ ﴿١٥٠﴾ كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ ﴿١٥١﴾ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ﴿١٥٢﴾", "w": [["ولكل وجهة هو موليها", "لكل أهل ملة، كالإسلام واليهودية والنصرانية، قبلة يتجهون إليها في صلاتهم."], ["فاستبقوا الخيرات", "سارعوا إلى الطاعات والأعمال الصالحة."], ["حجة", "الدليل القوي الذي يغلب به صاحبه خصمه."], ["ولأتم نعمتي", "نعم الله كثيرة وأعظمها نعمة الإسلام، وتمامها بمواصلة التشريع إلى كماله في حجة الوداع بعرفات، حيث نزل قوله تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾."], ["يزكيكم", "يطهركم من الذنوب والأخلاق السيئة."], ["الحكمة", "السنة النبوية."], ["الشكر", "إظهار النعمة بصرفها فيما من أجله وهبها الله."], ["الكفر", "جحد النعمة وإخفاؤها وصرفها في غير ما يحب الله."]], "m": "بعد أن قرّر الله أن أهل الكتاب لن يتبعوا قبلة النبي ﷺ ولو جاءهم بكل آية، وأن بعضهم لا يتبع قبلة بعض، أخبر أن لكل أمة قبلة تتجه إليها. فأمر المسلمين أن يتركوا أهل الملل الضالة وأن يسابقوا في الخيرات شكراً على نعمة الهداية إلى قبلة أبيهم إبراهيم، فإن الله يجمعهم يوم القيامة ويجازيهم بأعمالهم. ثم أمر رسوله أن يولّي وجهه شطر المسجد الحرام حيث كان، في الحضر أو في السفر، وأن تحويله إلى الكعبة حق ثابت من ربه. وأمر الجميع بالثبات على ذلك حتى لا يكون لأعدائهم حجة، إذ يقول اليهود: ينكرون ديننا ويستقبلون قبلتنا، ويقول المشركون: يدّعون ملة إبراهيم ويخالفون قبلته. أما الظالمون المكابرون فلا سبيل إلى إقناعهم، فلا تخشوهم واخشوني. وكل ذلك ليتم الله نعمته عليهم بالهداية إلى أحسن الشرائع، كما أنعم عليهم بإرسال رسول منهم يتلو عليهم آياته ويطهّرهم ويعلّمهم الكتاب والحكمة وما لم يكونوا يعلمون. وختم بالأمر بذكره وشكره وعدم كفران نعمته.", "h": ["وجوب شكر الله على نعمه الظاهرة والباطنة.", "وجوب تعلم العلم الضروري ليتمكن العبد من عبادة الله عبادة تزكّي نفسه.", "وجوب ذكر الله بالتهليل والتكبير والتسبيح، وشكره بطاعته.", "حرمة نسيان ذكر الله وكفران نعمه بترك شكرها."], "k": "ما النعمة التي أنعم الله بها عليّ ولم أشكرها بعدُ بعمل صالح؟"}]$j$::jsonb) with ordinality x(e, i);

-- 21. سورة البقرة ١٥٣ – ١٥٨ · الصبر عند الابتلاء وشعائر الله
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (21, 2, 153, 158, 'سورة البقرة ١٥٣ – ١٥٨', 'الصبر عند الابتلاء وشعائر الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 21) = $j$[{"lbl": "الآيات ١٥٣ – ١٥٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ ﴿١٥٣﴾ وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ ﴿١٥٤﴾ وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ ﴿١٥٥﴾ ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ ﴿١٥٦﴾ أُوْلَـٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ ﴿١٥٧﴾", "w": [["الاستعانة", "طلب العون والقدرة على القول أو العمل."], ["الصبر", "حمل النفس على المكروه وتوطينها على احتمال المكاره."], ["لا تشعرون", "لا تُدركون هذه الحياة بحواسكم."], ["الابتلاء", "الاختبار والامتحان ليظهر ما عليه الممتحَن من قوة أو ضعف."], ["المصيبة", "ما يصيب العبد من ضرر في نفسه أو أهله أو ماله."], ["صلوات", "المراد بها هنا مغفرة الله، وقد عُطفت عليها الرحمة."], ["المهتدون", "إلى طريق السعادة والكمال بإيمانهم وصبرهم على ابتلاء الله لهم."]], "m": "نادى الله المؤمنين وأرشدهم إلى ما يعينهم على الثبات على قبلتهم وعلى ذكره وشكره وترك نسيانه وكفره، فقال: استعينوا بالصبر والصلاة، وأعلمهم أنه مع الصابرين يمدّهم بعونه وقوته. ونهاهم أن يقولوا لمن قُتل في سبيله إنه ميت، فهو حيّ في البرزخ يُرزق في الجنة، كما قال النبي ﷺ: «أرواح الشهداء في حواصل طير خضر تسرح في الجنة حيث شاءت». وهي حياة لا نحسّ بها لمفارقتها حياة هذه الدار. ثم أقسم أنه سيبتلي المؤمنين بشيء من الخوف من أعدائهم، والجوع، ونقص الأموال كموت الماشية، ونقص الأنفس كموت الرجال، ونقص الثمرات بالآفات؛ ليظهر من يصبر على إيمانه وطاعة ربه ممن لا يصبر. وأمر رسوله أن يبشّر الصابرين، وهم الذين يقولون عند المصيبة: إنا لله وإنا إليه راجعون، أي نحن ملكه وعبيده يتصرف فينا كما شاء، وإليه مرجعنا بالموت، فلا جزع ولكن تسليم لقضائه. وأولئك عليهم مغفرة من ربهم ورحمة، وهم المهتدون.", "h": ["فضل الصبر والأمر به، والاستعانة بالصبر والصلاة على المصائب والتكاليف؛ وكان النبي ﷺ إذا حزبه أمر فزع إلى الصلاة.", "فضل الشهداء على غيرهم بحياتهم عند ربهم حياةً أكمل في الجنة.", "قد يُبتلى المؤمن بالمصائب في نفسه وأهله وماله ليصبر فترتفع درجته عند ربه.", "فضل الاسترجاع عند المصيبة، وهو قول: إنا لله وإنا إليه راجعون."], "k": "ما آخر مصيبة أصابتني؟ وهل قلت «إنا لله وإنا إليه راجعون» وأنا أستحضر معناها حقاً؟"}, {"lbl": "الآية ١٥٨", "q": "۞إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ ﴿١٥٨﴾", "w": [["الصفا والمروة", "جبلان صغيران قرب البيت الحرام، أحدهما في جهته الجنوبية الشرقية والآخر في الشمالية، وبينهما نحو سبعمئة وخمسين ذراعاً."], ["شعائر الله", "أعلام دينه، جمع شعيرة وهي العلامة على عبادة الله؛ فالسعي بينهما علامة على طاعته."], ["الحج", "زيارة بيت الله لأداء عبادات معينة تسمى مناسك."], ["العمرة", "زيارة بيت الله للطواف به والسعي بين الصفا والمروة، ثم التحلل بحلق الرأس أو تقصيره."], ["الجناح", "الإثم، وما يترتب على ترك الواجب أو فعل المنهي عنه."], ["يطّوّف بهما", "يسعى بينهما ذاهباً وجائياً."], ["خيراً", "كل ما يجلب المسرة ويدفع المضرة، والمراد هنا العمل الصالح."]], "m": "تحرّج بعض المؤمنين من السعي بين الصفا والمروة، لأنه كان في الجاهلية على الصفا صنم اسمه إساف، وعلى المروة صنم اسمه نائلة، يتمسح بهما من يسعى. فأخبر الله أن الصفا والمروة، أي السعي بينهما، من شعائره وعباداته، وقد تعبّد به نبيه إبراهيم وولده إسماعيل والمسلمون من ذريتهما. فمن حجّ البيت أو اعتمر فليسعَ بينهما، فهو ركن في الحج والعمرة، ولا إثم عليه في كون المشركين كانوا يسعون عندهما للصنمين. ثم وعد من يتطوع بخير من الخيرات أن يجزيه عليه، لأن الله يشكر لعباده أعمالهم الصالحة ويثيبهم عليها، وهو عليم بها وبنيّات أصحابها.", "h": ["وجوب السعي بين الصفا والمروة لكل من طاف بالبيت حاجاً أو معتمراً، وقد قال النبي ﷺ: «اسعوا فإن الله كتب عليكم السعي».", "لا حرج في الصلاة في كنيسة حُوّلت مسجداً، ولا يضرّ كونها كانت معبداً للكفار.", "الترغيب في فعل الخيرات من غير الواجبات، كالطواف والصلاة والصيام والصدقات والرباط والجهاد."], "k": "هل لي نافلة أحافظ عليها، أرجو أن يشكرها الله لي ويعلمها من نيتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 21;
