-- 22. سورة البقرة ١٥٩ – ١٦٧ · كتمان العلم وتوحيد الله
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (22, 2, 159, 167, 'سورة البقرة ١٥٩ – ١٦٧', 'كتمان العلم وتوحيد الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 22) = $j$[{"lbl": "الآيات ١٥٩ – ١٦٢", "q": "إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَـٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّـٰعِنُونَ ﴿١٥٩﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَـٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٦٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَـٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١٦١﴾ خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ ﴿١٦٢﴾", "w": [["يكتمون", "يخفون ويغطّون حتى لا يظهر الشيء ولا يُعرف فيؤخذ به."], ["البيّنات", "جمع بيّنة، وهي ما يثبت به الشيء، والمراد هنا ما يثبت نبوة محمد ﷺ من أوصاف جاءت في كتب أهل الكتاب."], ["الهدى", "ما يدل على الطريق الصحيح ويعين على الوصول إليه، والمراد هنا الدين الصحيح الذي جاء به رسول الله ﷺ."], ["الكتاب", "التوراة والإنجيل."], ["اللعنة", "الطرد والبعد من كل خير ورحمة."], ["اللاعنون", "من يصدر عنهم اللعن، كالملائكة والمؤمنين."], ["أصلحوا", "ما أفسدوه من عقائد الناس وأمور دينهم، بإظهار ما كتموه والإيمان بما كذّبوا به."], ["ولا هم ينظرون", "لا يُمهلون ليعتذروا."]], "m": "عاد السياق، بعد الجواب عن حرج بعض المسلمين من السعي، إلى التنديد بجرائم علماء أهل الكتاب ودعوتهم إلى التوبة. فأخبر الله أن الذين يكتمون ما أنزل من البيّنات والهدى في التوراة والإنجيل من صفات الرسول ﷺ والأمر بالإيمان به، يلعنهم الله وتلعنهم الملائكة والمؤمنون. واستثنى منهم من تاب فبيّن ما كتم وأصلح ما أفسد، فهؤلاء يتوب الله عليهم، وهو التواب الرحيم. أما الذين كفروا من أهل الكتاب وغيرهم ولم يتوبوا فماتوا على كفرهم، فعليهم لعنة الله والملائكة والناس أجمعين، وهم خالدون في جهنم لا يخفف عنهم العذاب ولا يُمهلون ليعتذروا.", "h": ["حرمة كتمان الحق، لا سيما إذا كان للحصول على منافع دنيوية: مالاً أو رياسة.", "يُشترط لتوبة من أفسد بجهله أو ظلمه أن يصلح ما أفسد: يبيّن ما حرّف أو بدّل، ويظهر ما كتم، ويؤدي ما أخذه بغير حق.", "من كفر ومات على كفره فهو خالد في جهنم، لا يُخفف عنه ولا يُنظر فيعتذر."], "k": "هل علمتُ شيئاً من الخير ونفعُ الناس به ظاهر، ثم سكتّ عنه تهاوناً أو خوفاً؟"}, {"lbl": "الآيتان ١٦٣ – ١٦٤", "q": "وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ﴿١٦٣﴾ إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿١٦٤﴾", "w": [["الإله", "المعبود بحق أو بباطل، والله سبحانه هو الإله الحق المعبود."], ["إلهكم إله واحد", "واحد في ذاته وصفاته وربوبيته، فلا خالق ولا رازق ولا مدبّر إلا هو؛ وواحد في ألوهيته، فلا معبود بحق سواه."], ["اختلاف الليل والنهار", "تعاقبهما بوجود أحدهما وغياب الآخر لمنافع العباد، فلا يدوم نهار ولا ليل."], ["بثّ فيها من كل دابة", "فرّق في الأرض ونشر فيها كل أنواع الدواب."], ["تصريف الرياح", "تغيير مهابّها، مرة صَباً ومرة دَبوراً، شمالية وغربية، وملقِّحة وعقيماً."]], "m": "لما أوجب الله على العلماء بيان العلم وحرّم كتمانه، أخبر أول ما ينبغي بيانه: أنه الإله الواحد الرحمن الرحيم. فلما سمع بعض المشركين ذلك قالوا: هل من دليل على أنه لا إله إلا الله؟ فأنزل الله ستّ آيات كونية، كل واحدة برهان ساطع على وجوده وقدرته وعلمه وحكمته ورحمته: خلق السموات والأرض، واختلاف الليل والنهار، وجريان السفن في البحر بما ينفع الناس، وإنزال المطر من السماء فتحيا به الأرض بعد موتها وتنتشر فيها الدواب، وتصريف الرياح بحسب حاجة الناس، والسحاب المسخّر بين السماء والأرض يُساق من بلد إلى آخر بإرادة العزيز الحكيم. ولا يرى هذه الدلائل إلا العاقل الذي يستعمل عقله، أما من عطّل عقله واتبع هواه فهو كأنه أعمى لا يبصر، وأصمّ لا يسمع.", "h": ["لا إله إلا الله، فلا تصح العبادة لغير الله، لأنه لا إله حق إلا هو.", "الآيات الكونية في السموات والأرض تثبت وجود الله رباً وإلهاً موصوفاً بكل كمال، منزّهاً عن كل نقص.", "الآيات القرآنية تثبت وجود الله، وتثبت النبوة المحمدية وتقرّر الرسالة.", "الانتفاع بالآيات، كونيةً كانت أو قرآنية، خاص بمن يستعملون عقولهم دون أهوائهم."], "k": "متى آخر مرة وقفتُ أتأمل السماء أو المطر أو الرياح، وتذكّرتُ أن وراءها إلهاً واحداً رحيماً؟"}, {"lbl": "الآيات ١٦٥ – ١٦٧", "q": "وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ ﴿١٦٥﴾ إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ ﴿١٦٦﴾ وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ ﴿١٦٧﴾", "w": [["أنداداً", "جمع نِدّ، وهو المثيل والنظير، والمراد هنا الشركاء الذين يُعبدون بحبّهم والتقرب إليهم بالدعاء والنذر والحلف."], ["تبرّأ", "تنصّل من الشيء وتباعد عنه كراهةً له."], ["الذين اتُّبعوا", "المعبودون والرؤساء المضلّون."], ["الذين اتبعوا", "المشركون المقلّدون لرؤسائهم في الضلال."], ["الأسباب", "جمع سبب، وهو في اللغة الحبل، ثم استُعمل في كل ما يربط بين شيئين أو يُتوصل به إلى مقصد."], ["كرّة", "رجعة وعودة إلى الحياة الدنيا."], ["حسرات", "جمع حسرة، وهي الندم الشديد الذي يكاد يُقعد صاحبه عن الحركة."]], "m": "بعد أن تقرر بالأدلة القاطعة أن إله الناس واحد، أخبر الله أن من الناس من يتخذون من دونه أنداداً، أصناماً ورؤساء، يحبونهم كحبهم لله، والمؤمنون أشد حباً لله منهم. ولو رأى المشركون عند معاينة العذاب يوم القيامة لعلموا أن القوة لله جميعاً وأن الله شديد العذاب. ففي ذلك اليوم يتبرأ الرؤساء الظالمون، دعاة الشرك والضلال، من أتباعهم الجهلة المقلّدين، ويرون العذاب وتنقطع الروابط التي كانت بينهم، ويتمنى الأتباع العودة إلى الدنيا ليتبرؤوا من رؤسائهم كما تبرؤوا منهم. وكما أراهم العذاب، يريهم أعمالهم القبيحة حسرات عليهم، وما هم بخارجين من النار.", "h": ["وجوب حب الله وحب كل ما يحبه الله بحبه تعالى.", "من الشرك أن يُحَبّ غير الله كحبه تعالى، ومن التوحيد أن يُحَبّ ما يحبه الله لأجل حبه.", "يوم القيامة تنحلّ الروابط من صداقة ونسب، ولا تبقى إلا رابطة الإيمان والأخوّة فيه.", "يتبرأ رؤساء الشرك والفساد ممن أطاعوهم في الدنيا، ولا ينفعهم ذلك شيئاً."], "k": "من أحبّ حبّاً يجعلني أطيعه وأعصي الله، أو أخشاه فوق خشيتي لله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 22;
insert into public.tdb_cards(topic, i, body) select 22, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥٩ – ١٦٢", "q": "إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَـٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّـٰعِنُونَ ﴿١٥٩﴾ إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَـٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٦٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَـٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿١٦١﴾ خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ ﴿١٦٢﴾", "w": [["يكتمون", "يخفون ويغطّون حتى لا يظهر الشيء ولا يُعرف فيؤخذ به."], ["البيّنات", "جمع بيّنة، وهي ما يثبت به الشيء، والمراد هنا ما يثبت نبوة محمد ﷺ من أوصاف جاءت في كتب أهل الكتاب."], ["الهدى", "ما يدل على الطريق الصحيح ويعين على الوصول إليه، والمراد هنا الدين الصحيح الذي جاء به رسول الله ﷺ."], ["الكتاب", "التوراة والإنجيل."], ["اللعنة", "الطرد والبعد من كل خير ورحمة."], ["اللاعنون", "من يصدر عنهم اللعن، كالملائكة والمؤمنين."], ["أصلحوا", "ما أفسدوه من عقائد الناس وأمور دينهم، بإظهار ما كتموه والإيمان بما كذّبوا به."], ["ولا هم ينظرون", "لا يُمهلون ليعتذروا."]], "m": "عاد السياق، بعد الجواب عن حرج بعض المسلمين من السعي، إلى التنديد بجرائم علماء أهل الكتاب ودعوتهم إلى التوبة. فأخبر الله أن الذين يكتمون ما أنزل من البيّنات والهدى في التوراة والإنجيل من صفات الرسول ﷺ والأمر بالإيمان به، يلعنهم الله وتلعنهم الملائكة والمؤمنون. واستثنى منهم من تاب فبيّن ما كتم وأصلح ما أفسد، فهؤلاء يتوب الله عليهم، وهو التواب الرحيم. أما الذين كفروا من أهل الكتاب وغيرهم ولم يتوبوا فماتوا على كفرهم، فعليهم لعنة الله والملائكة والناس أجمعين، وهم خالدون في جهنم لا يخفف عنهم العذاب ولا يُمهلون ليعتذروا.", "h": ["حرمة كتمان الحق، لا سيما إذا كان للحصول على منافع دنيوية: مالاً أو رياسة.", "يُشترط لتوبة من أفسد بجهله أو ظلمه أن يصلح ما أفسد: يبيّن ما حرّف أو بدّل، ويظهر ما كتم، ويؤدي ما أخذه بغير حق.", "من كفر ومات على كفره فهو خالد في جهنم، لا يُخفف عنه ولا يُنظر فيعتذر."], "k": "هل علمتُ شيئاً من الخير ونفعُ الناس به ظاهر، ثم سكتّ عنه تهاوناً أو خوفاً؟"}, {"lbl": "الآيتان ١٦٣ – ١٦٤", "q": "وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ﴿١٦٣﴾ إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿١٦٤﴾", "w": [["الإله", "المعبود بحق أو بباطل، والله سبحانه هو الإله الحق المعبود."], ["إلهكم إله واحد", "واحد في ذاته وصفاته وربوبيته، فلا خالق ولا رازق ولا مدبّر إلا هو؛ وواحد في ألوهيته، فلا معبود بحق سواه."], ["اختلاف الليل والنهار", "تعاقبهما بوجود أحدهما وغياب الآخر لمنافع العباد، فلا يدوم نهار ولا ليل."], ["بثّ فيها من كل دابة", "فرّق في الأرض ونشر فيها كل أنواع الدواب."], ["تصريف الرياح", "تغيير مهابّها، مرة صَباً ومرة دَبوراً، شمالية وغربية، وملقِّحة وعقيماً."]], "m": "لما أوجب الله على العلماء بيان العلم وحرّم كتمانه، أخبر أول ما ينبغي بيانه: أنه الإله الواحد الرحمن الرحيم. فلما سمع بعض المشركين ذلك قالوا: هل من دليل على أنه لا إله إلا الله؟ فأنزل الله ستّ آيات كونية، كل واحدة برهان ساطع على وجوده وقدرته وعلمه وحكمته ورحمته: خلق السموات والأرض، واختلاف الليل والنهار، وجريان السفن في البحر بما ينفع الناس، وإنزال المطر من السماء فتحيا به الأرض بعد موتها وتنتشر فيها الدواب، وتصريف الرياح بحسب حاجة الناس، والسحاب المسخّر بين السماء والأرض يُساق من بلد إلى آخر بإرادة العزيز الحكيم. ولا يرى هذه الدلائل إلا العاقل الذي يستعمل عقله، أما من عطّل عقله واتبع هواه فهو كأنه أعمى لا يبصر، وأصمّ لا يسمع.", "h": ["لا إله إلا الله، فلا تصح العبادة لغير الله، لأنه لا إله حق إلا هو.", "الآيات الكونية في السموات والأرض تثبت وجود الله رباً وإلهاً موصوفاً بكل كمال، منزّهاً عن كل نقص.", "الآيات القرآنية تثبت وجود الله، وتثبت النبوة المحمدية وتقرّر الرسالة.", "الانتفاع بالآيات، كونيةً كانت أو قرآنية، خاص بمن يستعملون عقولهم دون أهوائهم."], "k": "متى آخر مرة وقفتُ أتأمل السماء أو المطر أو الرياح، وتذكّرتُ أن وراءها إلهاً واحداً رحيماً؟"}, {"lbl": "الآيات ١٦٥ – ١٦٧", "q": "وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ ﴿١٦٥﴾ إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ ﴿١٦٦﴾ وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ ﴿١٦٧﴾", "w": [["أنداداً", "جمع نِدّ، وهو المثيل والنظير، والمراد هنا الشركاء الذين يُعبدون بحبّهم والتقرب إليهم بالدعاء والنذر والحلف."], ["تبرّأ", "تنصّل من الشيء وتباعد عنه كراهةً له."], ["الذين اتُّبعوا", "المعبودون والرؤساء المضلّون."], ["الذين اتبعوا", "المشركون المقلّدون لرؤسائهم في الضلال."], ["الأسباب", "جمع سبب، وهو في اللغة الحبل، ثم استُعمل في كل ما يربط بين شيئين أو يُتوصل به إلى مقصد."], ["كرّة", "رجعة وعودة إلى الحياة الدنيا."], ["حسرات", "جمع حسرة، وهي الندم الشديد الذي يكاد يُقعد صاحبه عن الحركة."]], "m": "بعد أن تقرر بالأدلة القاطعة أن إله الناس واحد، أخبر الله أن من الناس من يتخذون من دونه أنداداً، أصناماً ورؤساء، يحبونهم كحبهم لله، والمؤمنون أشد حباً لله منهم. ولو رأى المشركون عند معاينة العذاب يوم القيامة لعلموا أن القوة لله جميعاً وأن الله شديد العذاب. ففي ذلك اليوم يتبرأ الرؤساء الظالمون، دعاة الشرك والضلال، من أتباعهم الجهلة المقلّدين، ويرون العذاب وتنقطع الروابط التي كانت بينهم، ويتمنى الأتباع العودة إلى الدنيا ليتبرؤوا من رؤسائهم كما تبرؤوا منهم. وكما أراهم العذاب، يريهم أعمالهم القبيحة حسرات عليهم، وما هم بخارجين من النار.", "h": ["وجوب حب الله وحب كل ما يحبه الله بحبه تعالى.", "من الشرك أن يُحَبّ غير الله كحبه تعالى، ومن التوحيد أن يُحَبّ ما يحبه الله لأجل حبه.", "يوم القيامة تنحلّ الروابط من صداقة ونسب، ولا تبقى إلا رابطة الإيمان والأخوّة فيه.", "يتبرأ رؤساء الشرك والفساد ممن أطاعوهم في الدنيا، ولا ينفعهم ذلك شيئاً."], "k": "من أحبّ حبّاً يجعلني أطيعه وأعصي الله، أو أخشاه فوق خشيتي لله؟"}]$j$::jsonb) with ordinality x(e, i);

-- 23. سورة البقرة ١٦٨ – ١٧٣ · الحذر من الشيطان وتقليد الآباء
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (23, 2, 168, 173, 'سورة البقرة ١٦٨ – ١٧٣', 'الحذر من الشيطان وتقليد الآباء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 23) = $j$[{"lbl": "الآيات ١٦٨ – ١٧٠", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ ﴿١٦٨﴾ إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿١٦٩﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ ﴿١٧٠﴾", "w": [["حلالاً طيباً", "ما أذن الله لهم فيه من رزقه، أما ما لم يأذن به فلا خير لهم في أكله لضرره على أبدانهم وأرواحهم."], ["خطوات الشيطان", "الشيطان وطرقه التي توصل العبد إلى تحريم ما أحلّ الله وتحليل ما حرّم."], ["عدو مبين", "عداوته ظاهرة، وهو الذي أخرج أبوينا آدم وحواء من الجنة، وأكثر الشرور والمفاسد في الدنيا من وسوسته وإغوائه."], ["السوء", "كل ما يسوء النفس ويصيبها بالحزن والغم، ويدخل فيه سائر الذنوب."], ["الفحشاء", "كل خصلة قبيحة كالزنا واللواط والبخل، وسائر المعاصي الشديدة القبح."], ["ألفينا", "وجدنا."]], "m": "بعد أن عرض الله أحوال أهل الشرك والعذاب الذي انتهوا إليه، نادى الناس جميعاً بنداء الرحمة: كلوا مما في الأرض حلالاً طيباً، وهو عطاؤه وإفضاله حيث أذن فيه. أما ما لم يأذن فيه فلا خير لكم في أكله لما فيه من الأذى لأبدانكم وأرواحكم. ونهاهم عن اتباع طرق عدوهم الشيطان، فإنه لا يأمرهم إلا بما يضرّهم: بالسوء وهو كل ما يسوء النفس، وبالفحشاء وهي أقبح الأفعال وأردأ الأخلاق، وأشنع من ذلك أن يأمرهم أن يكذبوا على الله فيقولوا عليه ما لا يعلمون، فيحرّموا ويحلّلوا ويشرّعوا باسمه. فإذا قيل لهم اتبعوا ما أنزل الله قالوا: بل نتبع ما وجدنا عليه آباءنا. فبيّن الله أنهم يقلّدون آباءهم ولو كانوا لا يعقلون شيئاً من أمور الدين، ولا يهتدون إلى ما فيه الصلاح والخير.", "h": ["وجوب طلب الحلال والاقتصار على العيش منه ولو كان ضيقاً قليلاً.", "الحلال ما أحلّه الله، والحرام ما حرّمه الله، فلا يستقل العقل بشيء من ذلك.", "حرمة اتباع مسالك الشيطان، وهي كل معتقد أو قول أو عمل نهى الله عنه.", "وجوب الابتعاد عن كل سوء وفحش، لأنهما مما يأمر به الشيطان.", "حرمة تقليد من لا علم له ولا بصيرة في الدين، وجواز اتباع أهل العلم والأخذ بآرائهم المستقاة من الكتاب والسنة."], "k": "هل في طعامي وكسبي شبهة أتساهل فيها لأن «الجميع يفعلونها»؟"}, {"lbl": "الآية ١٧١", "q": "وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ ﴿١٧١﴾", "w": [["النداء", "طلب القريب أو البعيد بالصوت، كأذان الصلاة."], ["الصمّ", "جمع أصمّ، وهو فاقد حاسة السمع."], ["البكم", "جمع أبكم، وهو فاقد حاسة النطق."], ["لا يعقلون", "لا يدركون معنى الكلام ولا يميّزون بين الأشياء، لتعطّل آلة الإدراك عندهم، وهي العقل."]], "m": "لما ندّدت الآية السابقة بالتقليد والمقلّدين الذين يعطّلون حواسهم ومداركهم ويفعلون ما يقوله لهم رؤساؤهم لا يعرفون لماذا فعلوا ولا لماذا تركوا، جاءت هذه الآية بمَثَل عجيب لهؤلاء. فمثل الذين كفروا، في جمودهم وتقليد آبائهم في الشرك والضلال، كمثل غنم ينعق بها راعيها، فإذا صاح فيها سمعت الصوت ولكنها لا تدري لماذا دُعيت، لفقدها العقل. تجيبه إذا ناداها ولو كان داعياً لذبحها، وإذا ناداها من بعيد أجابته وهي لا تفهم إلا مجرد الصوت الذي ألفته بطول التقليد والاتباع من غير دليل. وهذا المثل يصلح لكل من يدعو أهل الكفر والضلال إلى الإيمان والهداية، فهو مع من يدعوهم من الكفرة المقلّدين كمثل الذي ينعق بما لا يسمع إلا دعاءً ونداءً.", "h": ["تسلية الدعاة إلى الله حين يواجهون المقلّدة من أهل الشرك والضلال.", "حرمة التقليد لأهل الأهواء والبدع.", "وجوب طلب العلم والمعرفة حتى لا يفعل المؤمن ولا يترك إلا على علم بما فعل وبما ترك.", "لا يُتابَع إلا أهل العلم والبصيرة في الدين، لأن اتباع الجهال يُعدّ تقليداً."], "k": "هل أفعل بعض ما أفعله في ديني لأنني ورثته فقط، دون أن أسأل: ما دليله؟"}, {"lbl": "الآيتان ١٧٢ – ١٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿١٧٢﴾ إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٧٣﴾", "w": [["الطيبات", "جمع طيّب، وهو الحلال."], ["اشكروا لله", "اعترفوا بنعمه عليكم واحمدوه عليها واصرفوها في مرضاته."], ["إن كنتم إياه تعبدون", "إن كنتم مطيعين لله منقادين لأمره ونهيه."], ["حرّم", "حظر ومنع."], ["الميتة", "ما مات من الحيوان حتف أنفه دون تذكية."], ["الدم", "المسفوح السائل، لا المختلط باللحم."], ["الخنزير", "حيوان خبيث معروف بأكل القاذورات، ولا يغار على أنثاه."], ["ما أُهلّ به لغير الله", "ما رُفع الصوت عند ذبحه باسم غير الله من الآلهة."], ["اضطُرّ", "أُلجئ وأُكره بحكم الضرر الذي لحقه من الجوع أو الإكراه."], ["غير باغٍ ولا عاد", "الباغي: الظالم الطالب لما لا يحل له، والعادي: المعتدي المجاوز لما له إلى ما ليس له."], ["الإثم", "أثر المعصية على النفس بالظلمة والتدنيس."]], "m": "بعد أن بيّنت الآية السابقة حال الكفرة المقلّدين لآبائهم في الشرك وتحريم ما أحل الله من الأنعام، كالسوائب والحامات والبحائر، نادى الله عباده المؤمنين: كلوا من طيبات ما رزقناكم واشكروا لله ما أنعم به عليكم من حلال اللحوم، ولا تحرّموه كما حرّمه مقلّدة المشركين. فإن الله لم يحرّم عليكم إلا الميتة والدم ولحم الخنزير وما ذُبح لغير الله. ومع ذلك فمن ألجأته الضرورة وخاف على نفسه الهلاك فأكل فلا إثم عليه، بشرط ألا يكون في سفره باغياً على المسلمين ولا عادياً بقطع الطريق عليهم؛ لأن الله غفور لأوليائه التائبين، رحيم بهم لا يتركهم في ضيق ولا حرج.", "h": ["الندب إلى أكل الطيبات من رزق الله في غير إسراف.", "وجوب شكر الله بالاعتراف بنعمته وحمده عليها، وعدم صرفها في معاصيه.", "حرمة أكل الميتة والدم المسفوح ولحم الخنزير وما أُهلّ به لغير الله.", "جواز الأكل من المذكورات عند الضرورة، وهي خوف الهلاك، مع مراعاة الاستثناء في الآية: «غير باغ ولا عاد».", "أذن النبي ﷺ في أكل السمك والجراد وهما من الميتة، وحرّم كل ذي ناب من السباع وذي مخلب من الطيور."], "k": "هل أشكر الله على الطعام بعد الأكل شكراً حقيقياً، أم أكتفي بأن أنتهي منه فحسب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 23;
insert into public.tdb_cards(topic, i, body) select 23, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦٨ – ١٧٠", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ ﴿١٦٨﴾ إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿١٦٩﴾ وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ ﴿١٧٠﴾", "w": [["حلالاً طيباً", "ما أذن الله لهم فيه من رزقه، أما ما لم يأذن به فلا خير لهم في أكله لضرره على أبدانهم وأرواحهم."], ["خطوات الشيطان", "الشيطان وطرقه التي توصل العبد إلى تحريم ما أحلّ الله وتحليل ما حرّم."], ["عدو مبين", "عداوته ظاهرة، وهو الذي أخرج أبوينا آدم وحواء من الجنة، وأكثر الشرور والمفاسد في الدنيا من وسوسته وإغوائه."], ["السوء", "كل ما يسوء النفس ويصيبها بالحزن والغم، ويدخل فيه سائر الذنوب."], ["الفحشاء", "كل خصلة قبيحة كالزنا واللواط والبخل، وسائر المعاصي الشديدة القبح."], ["ألفينا", "وجدنا."]], "m": "بعد أن عرض الله أحوال أهل الشرك والعذاب الذي انتهوا إليه، نادى الناس جميعاً بنداء الرحمة: كلوا مما في الأرض حلالاً طيباً، وهو عطاؤه وإفضاله حيث أذن فيه. أما ما لم يأذن فيه فلا خير لكم في أكله لما فيه من الأذى لأبدانكم وأرواحكم. ونهاهم عن اتباع طرق عدوهم الشيطان، فإنه لا يأمرهم إلا بما يضرّهم: بالسوء وهو كل ما يسوء النفس، وبالفحشاء وهي أقبح الأفعال وأردأ الأخلاق، وأشنع من ذلك أن يأمرهم أن يكذبوا على الله فيقولوا عليه ما لا يعلمون، فيحرّموا ويحلّلوا ويشرّعوا باسمه. فإذا قيل لهم اتبعوا ما أنزل الله قالوا: بل نتبع ما وجدنا عليه آباءنا. فبيّن الله أنهم يقلّدون آباءهم ولو كانوا لا يعقلون شيئاً من أمور الدين، ولا يهتدون إلى ما فيه الصلاح والخير.", "h": ["وجوب طلب الحلال والاقتصار على العيش منه ولو كان ضيقاً قليلاً.", "الحلال ما أحلّه الله، والحرام ما حرّمه الله، فلا يستقل العقل بشيء من ذلك.", "حرمة اتباع مسالك الشيطان، وهي كل معتقد أو قول أو عمل نهى الله عنه.", "وجوب الابتعاد عن كل سوء وفحش، لأنهما مما يأمر به الشيطان.", "حرمة تقليد من لا علم له ولا بصيرة في الدين، وجواز اتباع أهل العلم والأخذ بآرائهم المستقاة من الكتاب والسنة."], "k": "هل في طعامي وكسبي شبهة أتساهل فيها لأن «الجميع يفعلونها»؟"}, {"lbl": "الآية ١٧١", "q": "وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ ﴿١٧١﴾", "w": [["النداء", "طلب القريب أو البعيد بالصوت، كأذان الصلاة."], ["الصمّ", "جمع أصمّ، وهو فاقد حاسة السمع."], ["البكم", "جمع أبكم، وهو فاقد حاسة النطق."], ["لا يعقلون", "لا يدركون معنى الكلام ولا يميّزون بين الأشياء، لتعطّل آلة الإدراك عندهم، وهي العقل."]], "m": "لما ندّدت الآية السابقة بالتقليد والمقلّدين الذين يعطّلون حواسهم ومداركهم ويفعلون ما يقوله لهم رؤساؤهم لا يعرفون لماذا فعلوا ولا لماذا تركوا، جاءت هذه الآية بمَثَل عجيب لهؤلاء. فمثل الذين كفروا، في جمودهم وتقليد آبائهم في الشرك والضلال، كمثل غنم ينعق بها راعيها، فإذا صاح فيها سمعت الصوت ولكنها لا تدري لماذا دُعيت، لفقدها العقل. تجيبه إذا ناداها ولو كان داعياً لذبحها، وإذا ناداها من بعيد أجابته وهي لا تفهم إلا مجرد الصوت الذي ألفته بطول التقليد والاتباع من غير دليل. وهذا المثل يصلح لكل من يدعو أهل الكفر والضلال إلى الإيمان والهداية، فهو مع من يدعوهم من الكفرة المقلّدين كمثل الذي ينعق بما لا يسمع إلا دعاءً ونداءً.", "h": ["تسلية الدعاة إلى الله حين يواجهون المقلّدة من أهل الشرك والضلال.", "حرمة التقليد لأهل الأهواء والبدع.", "وجوب طلب العلم والمعرفة حتى لا يفعل المؤمن ولا يترك إلا على علم بما فعل وبما ترك.", "لا يُتابَع إلا أهل العلم والبصيرة في الدين، لأن اتباع الجهال يُعدّ تقليداً."], "k": "هل أفعل بعض ما أفعله في ديني لأنني ورثته فقط، دون أن أسأل: ما دليله؟"}, {"lbl": "الآيتان ١٧٢ – ١٧٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿١٧٢﴾ إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٧٣﴾", "w": [["الطيبات", "جمع طيّب، وهو الحلال."], ["اشكروا لله", "اعترفوا بنعمه عليكم واحمدوه عليها واصرفوها في مرضاته."], ["إن كنتم إياه تعبدون", "إن كنتم مطيعين لله منقادين لأمره ونهيه."], ["حرّم", "حظر ومنع."], ["الميتة", "ما مات من الحيوان حتف أنفه دون تذكية."], ["الدم", "المسفوح السائل، لا المختلط باللحم."], ["الخنزير", "حيوان خبيث معروف بأكل القاذورات، ولا يغار على أنثاه."], ["ما أُهلّ به لغير الله", "ما رُفع الصوت عند ذبحه باسم غير الله من الآلهة."], ["اضطُرّ", "أُلجئ وأُكره بحكم الضرر الذي لحقه من الجوع أو الإكراه."], ["غير باغٍ ولا عاد", "الباغي: الظالم الطالب لما لا يحل له، والعادي: المعتدي المجاوز لما له إلى ما ليس له."], ["الإثم", "أثر المعصية على النفس بالظلمة والتدنيس."]], "m": "بعد أن بيّنت الآية السابقة حال الكفرة المقلّدين لآبائهم في الشرك وتحريم ما أحل الله من الأنعام، كالسوائب والحامات والبحائر، نادى الله عباده المؤمنين: كلوا من طيبات ما رزقناكم واشكروا لله ما أنعم به عليكم من حلال اللحوم، ولا تحرّموه كما حرّمه مقلّدة المشركين. فإن الله لم يحرّم عليكم إلا الميتة والدم ولحم الخنزير وما ذُبح لغير الله. ومع ذلك فمن ألجأته الضرورة وخاف على نفسه الهلاك فأكل فلا إثم عليه، بشرط ألا يكون في سفره باغياً على المسلمين ولا عادياً بقطع الطريق عليهم؛ لأن الله غفور لأوليائه التائبين، رحيم بهم لا يتركهم في ضيق ولا حرج.", "h": ["الندب إلى أكل الطيبات من رزق الله في غير إسراف.", "وجوب شكر الله بالاعتراف بنعمته وحمده عليها، وعدم صرفها في معاصيه.", "حرمة أكل الميتة والدم المسفوح ولحم الخنزير وما أُهلّ به لغير الله.", "جواز الأكل من المذكورات عند الضرورة، وهي خوف الهلاك، مع مراعاة الاستثناء في الآية: «غير باغ ولا عاد».", "أذن النبي ﷺ في أكل السمك والجراد وهما من الميتة، وحرّم كل ذي ناب من السباع وذي مخلب من الطيور."], "k": "هل أشكر الله على الطعام بعد الأكل شكراً حقيقياً، أم أكتفي بأن أنتهي منه فحسب؟"}]$j$::jsonb) with ordinality x(e, i);

-- 24. سورة البقرة ١٧٤ – ١٧٧ · كتمان الحق وحقيقة البر
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (24, 2, 174, 177, 'سورة البقرة ١٧٤ – ١٧٧', 'كتمان الحق وحقيقة البر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 24) = $j$[{"lbl": "الآيات ١٧٤ – ١٧٦", "q": "إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿١٧٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ ﴿١٧٥﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ ﴿١٧٦﴾", "w": [["يكتمون", "يجحدون ويخفون."], ["ما أنزل الله من الكتاب", "التوراة، وما أنزل الله فيها من صفة النبي محمد ﷺ والأمر بالإيمان به."], ["لا يكلّمهم الله", "لسخطه عليهم ولعنه لهم."], ["ولا يزكّيهم", "لا يطهّرهم من ذنوبهم لعدم رضاه عنهم."], ["الضلالة", "العمى المانع من الهداية إلى المطلوب."], ["الشقاق", "التنازع والعداء حتى يكون صاحبه في شق ومنازعه في شق آخر."], ["بعيد", "يصعب إنهاؤه والاتفاق بعده."]], "m": "نزلت هذه الآيات الثلاث في أحبار أهل الكتاب، تندّد بهم وتريهم جزاء كتمان الحق. فقد باعوا العلم الذي أُخذ عليهم أن يبيّنوه بعرض خسيس من الدنيا، فجحدوا أمر النبي ﷺ ودينه إرضاءً لعوامّهم حتى لا تنقطع هداياهم ومساعداتهم المالية ويبقى لهم السلطان الروحي عليهم. وأخبر الله أن ما يأكلونه من ذلك ما هو إلا نار في بطونهم، ومع النار غضب الجبار، فلا يكلّمهم ولا يطهّرهم، ولهم عذاب أليم. وأخبر أنهم اشتروا الضلالة بالهدى، أي الكفر بالإيمان، والعذاب بالمغفرة، فما أصبرهم على النار! أي ما أجرأهم على عمل أهلها. وذلك لأن الله أنزل الكتاب بالحق مبيّناً سبيل الهداية وما يفضي إليه من النعيم المقيم، وسبيل الغواية وما يؤدي إلى غضب الله وأليم عذابه. وأخبر أن الذين اختلفوا في الكتاب، التوراة والإنجيل، وهم اليهود والنصارى، في شقاق بعيد، ولا يزالون إلى اليوم مختلفين متعادين، لأنهم تركوا الحق الذي أمرهم الله به وأخذوا بالباطل.", "h": ["حرمة كتمان الحق، لا سيما إذا كان للحصول على منافع دنيوية من مال أو رياسة.", "تحذير علماء الإسلام من سلوك مسلك علماء أهل الكتاب بكتمان الحق وإفتاء الناس بالباطل للحصول على منافع مادية.", "التحذير من الاختلاف في القرآن الكريم لما يفضي إليه من العداء والشقاق البعيد."], "k": "هل سكتّ يوماً عن قول حقّ، أو قلت ما يرضي الناس وأنا أعلم أنه ليس الحق؟"}, {"lbl": "الآية ١٧٧", "q": "۞لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّـٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ﴿١٧٧﴾", "w": [["البرّ", "اسم جامع لكل خير وطاعة لله ولرسوله ﷺ."], ["ولكن البر من آمن بالله", "أي البرّ الحق برّ من آمن بالله واليوم الآخر، إلى آخر الصفات."], ["وآتى المال على حبه", "أعطى المال حيث تعيّن إعطاؤه مع شدة حبه له، فآثر ما يحبه الله على ما يحبه هو."], ["ذوي القربى", "أصحاب القرابات، الأقرب فالأقرب."], ["اليتامى", "جمع يتيم، وهو من مات أبوه وهو لم يبلغ."], ["المساكين", "جمع مسكين، وهو الفقير المعدم الذي أسكنته الحاجة فلم يقدر على التصرف."], ["ابن السبيل", "المسافر البعيد الدار المنقطع عن أهله وماله."], ["السائلين", "جمع سائل، وهو الفقير المحتاج الذي أُذن له في السؤال ليدفع عن نفسه الحاجة."], ["في الرقاب", "الإنفاق فيها معناه في عتقها."], ["البأساء والضراء", "البأساء: شدة البؤس من الفقر. والضراء: شدة الضر أو المرض."], ["حين البأس", "عند القتال واشتداده في سبيل الله."], ["صدقوا", "في دعواهم الإيمان والبرّ."]], "m": "في الآيات الثلاث السابقة ندّد الله بأحبار أهل الكتاب وتوعّدهم بغضبه وأليم عقابه، وفيها تخويف لعلماء الإسلام من كتمان العلم طلباً لحظوظ الدنيا. وفي هذه الآية ردّ على أهل الكتاب، الذين تباهَوا بقبلتهم وادّعوا كمال الإيمان لمجرد أنهم يصلون إلى بيت المقدس أو إلى المشرق. فقال: ليس البرّ كل البرّ أن تولّوا وجوهكم قبل المشرق والمغرب. وفي هذا تنبيه عظيم للمسلم الذي يقصر إسلامه على الصلاة ولا يبالي بعدها بما ترك من واجبات وما ارتكب من منهيات. ثم بيّن من هو البارّ حقاً: من آمن بالله واليوم الآخر والملائكة والكتاب والنبيين، وأنفق المال مع حبه له على ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي تحرير الرقاب، وأقام الصلاة وأتى الزكاة، ووفّى بعهده إذا عاهد، وصبر في الفقر والمرض وعند القتال. وهذا هو مبدأ الإحسان: مراقبة الله والنظر إليه وهو يزاول عبادته. فأولئك الصادقون في دعوى الإيمان والإسلام، وأولئك هم المتقون حقاً.", "h": ["الاكتفاء ببعض أمور الدين دون القيام ببعض لا يجعل صاحبه مؤمناً ولا ناجياً.", "أركان الإيمان هي المذكورة في هذه الآية، والمراد بالكتاب فيها الكتب.", "بيان وجوه الإنفاق المرجوّ ثوابه يوم القيامة: ذوو القربى وغيرهم.", "بيان عظم شأن الصلاة والزكاة، ووجوب الوفاء بالعهود، ووجوب الصبر وخاصة عند القتال.", "التقوى هي ملاك الأمر، والغاية التي لا غاية بعدها للعاملين."], "k": "أي صفة من صفات البارّين في هذه الآية أحتاج أن أبدأ بها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 24;
insert into public.tdb_cards(topic, i, body) select 24, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧٤ – ١٧٦", "q": "إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿١٧٤﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ ﴿١٧٥﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ ﴿١٧٦﴾", "w": [["يكتمون", "يجحدون ويخفون."], ["ما أنزل الله من الكتاب", "التوراة، وما أنزل الله فيها من صفة النبي محمد ﷺ والأمر بالإيمان به."], ["لا يكلّمهم الله", "لسخطه عليهم ولعنه لهم."], ["ولا يزكّيهم", "لا يطهّرهم من ذنوبهم لعدم رضاه عنهم."], ["الضلالة", "العمى المانع من الهداية إلى المطلوب."], ["الشقاق", "التنازع والعداء حتى يكون صاحبه في شق ومنازعه في شق آخر."], ["بعيد", "يصعب إنهاؤه والاتفاق بعده."]], "m": "نزلت هذه الآيات الثلاث في أحبار أهل الكتاب، تندّد بهم وتريهم جزاء كتمان الحق. فقد باعوا العلم الذي أُخذ عليهم أن يبيّنوه بعرض خسيس من الدنيا، فجحدوا أمر النبي ﷺ ودينه إرضاءً لعوامّهم حتى لا تنقطع هداياهم ومساعداتهم المالية ويبقى لهم السلطان الروحي عليهم. وأخبر الله أن ما يأكلونه من ذلك ما هو إلا نار في بطونهم، ومع النار غضب الجبار، فلا يكلّمهم ولا يطهّرهم، ولهم عذاب أليم. وأخبر أنهم اشتروا الضلالة بالهدى، أي الكفر بالإيمان، والعذاب بالمغفرة، فما أصبرهم على النار! أي ما أجرأهم على عمل أهلها. وذلك لأن الله أنزل الكتاب بالحق مبيّناً سبيل الهداية وما يفضي إليه من النعيم المقيم، وسبيل الغواية وما يؤدي إلى غضب الله وأليم عذابه. وأخبر أن الذين اختلفوا في الكتاب، التوراة والإنجيل، وهم اليهود والنصارى، في شقاق بعيد، ولا يزالون إلى اليوم مختلفين متعادين، لأنهم تركوا الحق الذي أمرهم الله به وأخذوا بالباطل.", "h": ["حرمة كتمان الحق، لا سيما إذا كان للحصول على منافع دنيوية من مال أو رياسة.", "تحذير علماء الإسلام من سلوك مسلك علماء أهل الكتاب بكتمان الحق وإفتاء الناس بالباطل للحصول على منافع مادية.", "التحذير من الاختلاف في القرآن الكريم لما يفضي إليه من العداء والشقاق البعيد."], "k": "هل سكتّ يوماً عن قول حقّ، أو قلت ما يرضي الناس وأنا أعلم أنه ليس الحق؟"}, {"lbl": "الآية ١٧٧", "q": "۞لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّـٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ﴿١٧٧﴾", "w": [["البرّ", "اسم جامع لكل خير وطاعة لله ولرسوله ﷺ."], ["ولكن البر من آمن بالله", "أي البرّ الحق برّ من آمن بالله واليوم الآخر، إلى آخر الصفات."], ["وآتى المال على حبه", "أعطى المال حيث تعيّن إعطاؤه مع شدة حبه له، فآثر ما يحبه الله على ما يحبه هو."], ["ذوي القربى", "أصحاب القرابات، الأقرب فالأقرب."], ["اليتامى", "جمع يتيم، وهو من مات أبوه وهو لم يبلغ."], ["المساكين", "جمع مسكين، وهو الفقير المعدم الذي أسكنته الحاجة فلم يقدر على التصرف."], ["ابن السبيل", "المسافر البعيد الدار المنقطع عن أهله وماله."], ["السائلين", "جمع سائل، وهو الفقير المحتاج الذي أُذن له في السؤال ليدفع عن نفسه الحاجة."], ["في الرقاب", "الإنفاق فيها معناه في عتقها."], ["البأساء والضراء", "البأساء: شدة البؤس من الفقر. والضراء: شدة الضر أو المرض."], ["حين البأس", "عند القتال واشتداده في سبيل الله."], ["صدقوا", "في دعواهم الإيمان والبرّ."]], "m": "في الآيات الثلاث السابقة ندّد الله بأحبار أهل الكتاب وتوعّدهم بغضبه وأليم عقابه، وفيها تخويف لعلماء الإسلام من كتمان العلم طلباً لحظوظ الدنيا. وفي هذه الآية ردّ على أهل الكتاب، الذين تباهَوا بقبلتهم وادّعوا كمال الإيمان لمجرد أنهم يصلون إلى بيت المقدس أو إلى المشرق. فقال: ليس البرّ كل البرّ أن تولّوا وجوهكم قبل المشرق والمغرب. وفي هذا تنبيه عظيم لل