-- 25. سورة البقرة ١٧٨ – ١٨٢ · القصاص والوصية
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (25, 2, 178, 182, 'سورة البقرة ١٧٨ – ١٨٢', 'القصاص والوصية', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 25) = $j$[{"lbl": "الآيتان ١٧٨ – ١٧٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ ﴿١٧٨﴾ وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٧٩﴾", "w": [["كُتب عليكم القصاص", "فُرض عليكم القصاص: وهو أن يُقتل القاتل إذا لم يرضَ ولي الدم بالدية."], ["في القتلى", "جمع قتيل، وهو من قُتل."], ["الحرّ", "خلاف العبد، والعبد هو الرقيق المملوك."], ["فمن عُفي له من أخيه شيء", "فمن تنازل له ولي الدم عن القود إلى الدية أو العفو."], ["فاتباع بالمعروف", "فالواجب أن تكون مطالبة الدية بالرفق واللين."], ["وأداء إليه بإحسان", "وأن يكون أداء الدية بإحسان، خالياً من المماطلة والنقص."], ["ذلك تخفيف من ربكم", "جواز أخذ الدية بدل القصاص، وأنتم مخيّرون بين العفو والدية والقصاص."], ["فمن اعتدى بعد ذلك", "من أخذ الدية ثم قتل، فإنه يتعيّن قتله."], ["القصاص", "المساواة في القتل والجراحات وفي آلة القتل أيضاً."], ["حياة", "إبقاء شامل عميم؛ فمن يريد أن يقتل يتذكر أنه سيُقتل فيترك القتل فيحيا ويحيا من أراد قتله، ويحيا بحياتهما خلق كثير."], ["أولي الألباب", "أصحاب العقول الراجحة، واحد الألباب لُبّ وهو العقل."], ["لعلكم تتقون", "ليعدّكم بهذا التشريع الحكيم لاتقاء ما يضر ولا يسر في الدنيا والآخرة."]], "m": "نزلت هذه الآية في حيّين من العرب كان أحدهما يرى أنه أشرف من الآخر، فكان يقتل الحرّ بالعبد والرجل بالمرأة تطاولاً وكبرياءً، فحدث بينهما قتل وهما في الإسلام، فشكوا ذلك إلى رسول الله ﷺ، فنزلت الآية تُبطل ذلك من أعراف الجاهلية وتقرّر مبدأ العدل والمساواة. فلا يُقتل بالرجل رجلان، ولا بالمرأة رجل ولا امرأتان. ومن تنازل له وليّ الدم عن القصاص إلى الدية أو العفو فليقبل، وليطلب الدية بالرفق والأدب، وليؤدّها القاتل بإحسان دون مماطلة ولا نقص. وبيّن الله منّته على المسلمين إذ وسّع عليهم، فجعل وليّ الدم مخيّراً بين العفو والدية والقصاص، في حين أن اليهود كان مفروضاً عليهم القصاص فقط، والنصارى الدية فقط. ومن اعتدى بعد ذلك فقتل بعد أخذ الدية فله عذاب أليم، واختُلف في هذا العذاب: هل هو في الدنيا بالقتل أم في الآخرة؟ ثم أخبر أن في القصاص حياةً عظيمة، لما فيه من الكفّ عن إزهاق الأرواح وسفك الدماء، يا أولي الألباب لعلكم تتقون.", "h": ["حكم القصاص في الإسلام هو المساواة والمماثلة، فيُقتل القاتل بما قَتل به لحديث: «المرء مقتول بما قتل به». ولما كان العبد يُقوَّم بالمال لا يُقتل به الحر عند الأئمة الثلاثة مالك والشافعي وأحمد، وخالف أبو حنيفة فرأى القود أخذاً بظاهر الآية.", "محاسن الشرع الإسلامي وما فيه من اليسر والرحمة، حيث أجاز العفو والدية بدل القصاص.", "بلاغة القرآن: كان حكماء العرب يقولون «القتل أنفى للقتل»، فقال القرآن: ﴿وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ﴾ فنفى لفظ القتل بالمرة، نفاه لفظاً وواقعاً."], "k": "هل أتسامح عند الغضب كما يتسامح الله معي، أم أتشبّث بحقي حتى النهاية؟"}, {"lbl": "الآيات ١٨٠ – ١٨٢", "q": "كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ ﴿١٨٠﴾ فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿١٨١﴾ فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٨٢﴾", "w": [["كُتب عليكم", "فُرض وأُثبت."], ["خيراً", "مالاً نقداً أو عرَضاً أو عقاراً."], ["الوصية", "ما يُوصى به من مال وغيره."], ["المعروف", "ما تعارف عليه الناس كثيراً أو قليلاً، بحيث لا يزيد على الثلث."], ["التبديل", "تغيير الشيء بآخر."], ["جَنَفاً أو إثماً", "الجنف: الميل عن الحق خطأً. والإثم: تعمّد الخروج عن الحق والعدل."]], "m": "بمناسبة ذكر القصاص، وفيه أن القاتل عرضة للقتل والمفروض فيه أن يوصي في ماله قبل قتله، ذكر الله آية الوصية: كُتب عليكم إذا حضر أحدكم الموت، إن ترك مالاً، الوصية للوالدين والأقربين بالمعروف حقاً على المتقين. ثم نُسخ هذا الحكم بآية المواريث، ويقول النبي ﷺ: «لا وصية لوارث». فنُسخ الوجوب وبقي الاستحباب، ولكن لغير الوالدين والأقربين الوارثين إلا أن يجيز ذلك الورثة، وأن تكون الوصية بالثلث فأقل. ودليل استحباب الوصية حديث سعد حين أذن له النبي ﷺ بالوصية بالثلث. وقد تكون الوصية واجبة إن ترك الموصي ديوناً لازمة وحقوقاً واجبة، فيجب أن يوصي بقضائها. وفي الآية الثانية: من بدّل وصية مؤمن بزيادة أو نقص أو تغيير فلا إثم على الموصي، وإنما الإثم على من بدّل، والله سميع عليم تهديداً لمن يغيّر الوصايا لغرض فاسد. وفي الآية الأخيرة: من خاف من موصٍ ميلاً عن الحق خطأً أو تعمّد إثم، فأصلح بينهم، فلا إثم عليه في إصلاح الخطأ، إن الله غفور رحيم.", "h": ["نسخ الوصية للوارثين مطلقاً، إلا بإجازة الورثة.", "استحباب الوصية بالمال لمن ترك مالاً كثيراً، يوصي به في وجوه البر.", "تأكّد الوصية، حضر الموت أو لم يحضر، لمن له أو عليه حقوق، خشية أن يموت فتضيع."], "k": "هل كتبتُ وصيتي، وما لي وما عليّ من حقوق، أم أتركها لما بعد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 25;
insert into public.tdb_cards(topic, i, body) select 25, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٧٨ – ١٧٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ ﴿١٧٨﴾ وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٧٩﴾", "w": [["كُتب عليكم القصاص", "فُرض عليكم القصاص: وهو أن يُقتل القاتل إذا لم يرضَ ولي الدم بالدية."], ["في القتلى", "جمع قتيل، وهو من قُتل."], ["الحرّ", "خلاف العبد، والعبد هو الرقيق المملوك."], ["فمن عُفي له من أخيه شيء", "فمن تنازل له ولي الدم عن القود إلى الدية أو العفو."], ["فاتباع بالمعروف", "فالواجب أن تكون مطالبة الدية بالرفق واللين."], ["وأداء إليه بإحسان", "وأن يكون أداء الدية بإحسان، خالياً من المماطلة والنقص."], ["ذلك تخفيف من ربكم", "جواز أخذ الدية بدل القصاص، وأنتم مخيّرون بين العفو والدية والقصاص."], ["فمن اعتدى بعد ذلك", "من أخذ الدية ثم قتل، فإنه يتعيّن قتله."], ["القصاص", "المساواة في القتل والجراحات وفي آلة القتل أيضاً."], ["حياة", "إبقاء شامل عميم؛ فمن يريد أن يقتل يتذكر أنه سيُقتل فيترك القتل فيحيا ويحيا من أراد قتله، ويحيا بحياتهما خلق كثير."], ["أولي الألباب", "أصحاب العقول الراجحة، واحد الألباب لُبّ وهو العقل."], ["لعلكم تتقون", "ليعدّكم بهذا التشريع الحكيم لاتقاء ما يضر ولا يسر في الدنيا والآخرة."]], "m": "نزلت هذه الآية في حيّين من العرب كان أحدهما يرى أنه أشرف من الآخر، فكان يقتل الحرّ بالعبد والرجل بالمرأة تطاولاً وكبرياءً، فحدث بينهما قتل وهما في الإسلام، فشكوا ذلك إلى رسول الله ﷺ، فنزلت الآية تُبطل ذلك من أعراف الجاهلية وتقرّر مبدأ العدل والمساواة. فلا يُقتل بالرجل رجلان، ولا بالمرأة رجل ولا امرأتان. ومن تنازل له وليّ الدم عن القصاص إلى الدية أو العفو فليقبل، وليطلب الدية بالرفق والأدب، وليؤدّها القاتل بإحسان دون مماطلة ولا نقص. وبيّن الله منّته على المسلمين إذ وسّع