-- 26. سورة البقرة ١٨٣ – ١٨٧ · فرض الصيام وأحكامه
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (26, 2, 183, 187, 'سورة البقرة ١٨٣ – ١٨٧', 'فرض الصيام وأحكامه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 26) = $j$[{"lbl": "الآيتان ١٨٣ – ١٨٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٨٣﴾ أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١٨٤﴾", "w": [["الصيام", "في اللغة الإمساك، والمراد هنا الامتناع عن الأكل والشرب والجماع من طلوع الفجر إلى غروب الشمس."], ["أياماً معدودات", "تسعة وعشرون يوماً أو ثلاثون، بحسب شهر رمضان."], ["فعدّة من أيام أُخر", "على من أفطر لعذر المرض أو السفر صيام أيام أخرى بعدد الأيام التي أفطر فيها."], ["يطيقونه", "يتحمّلونه بمشقة لكبر سن أو مرض لا يُرجى برؤه."], ["فدية طعام مسكين", "على من أفطر لعذر مما ذُكر أن يُطعم عن كل يوم مسكيناً، ولا قضاء عليه."], ["فمن تطوّع خيراً", "زاد على المقدار، أو أطعم أكثر من مسكين فهو خير له."], ["وأن تصوموا خير لكم", "الصيام لمن يطيقه ولو بمشقة خير من الإفطار مع الطعام."]], "m": "لما هاجر الرسول ﷺ إلى المدينة وصارت دار إسلام، أخذ التشريع ينزل ويتوالى. ففي الآيات السابقة كان حكم القصاص والوصية ومراقبة الله فيهما، وأعظم ما يُنمّي في المؤمن ملَكة التقوى الصيام، فأنزل الله فرض الصيام في السنة الثانية للهجرة. ناداهم بعنوان الإيمان، وأعلمهم أنه كتب عليهم الصيام كما كتبه على الأمم السابقة، وعلّل ذلك بقوله: لعلكم تتقون، أي ليُعدّكم به للتقوى، وهي امتثال الأوامر واجتناب النواهي، لما في الصيام من مراقبة الله. وقوله «أياماً معدودات» ليهوّن عليهم مشقة الصوم، إذ لم يجعله شهوراً ولا أعواماً. وزاد في التخفيف: فمن كان مريضاً أو على سفر فعدّة من أيام أخر. وجعل لمن يطيق الصيام بمشقة شديدة أن يفطر ويطعم عن كل يوم مسكيناً، وأعلمهم أن الصيام في هذه الحال خير. ثم نُسخ هذا الحكم الأخير بقوله في الآية الآتية: ﴿فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ﴾. وقوله «إن كنتم تعلمون» أي تعلمون فوائد الصوم الدنيوية والأخروية، وهي كثيرة، أجلّها مغفرة الذنوب وذهاب الأمراض.", "h": ["فرضية الصيام، وهو شهر رمضان.", "يجوز للحامل والمرضع الإفطار مع القضاء، وكذا الشيخ الكبير والمريض مرضاً لا يُرجى برؤه، وعليهما أن يطعما عن كل يوم مسكيناً.", "في الصيام فوائد دينية واجتماعية عظيمة، أُشير إليها بقوله: «إن كنتم تعلمون».", "من هذه الفوائد: يعوّد الصائم خشية الله في السر والعلن، ويكسر حدّة الشهوة، ويربّي الشفقة والرحمة في النفس، ويحقق المساواة بين الأغنياء والفقراء، ويعوّد الأمة النظام والوحدة والوئام، ويذهب المواد المترسبة في البدن فتتحسن صحة الصائم."], "k": "ما الذي أريد أن يتغير في نفسي بعد رمضان القادم، لتكون ثمرة صيامي «لعلكم تتقون»؟"}, {"lbl": "الآية ١٨٥", "q": "شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٨٥﴾", "w": [["شهر رمضان", "الشهر التاسع من الشهور القمرية؛ ولفظ «الشهر» مأخوذ من الشهرة، و«رمضان» من رَمِض الصائم إذا حرّ جوفه من العطش."], ["هدى للناس", "هادياً للناس إلى ما فيه كمالهم وسعادتهم في الدارين."], ["وبيّنات من الهدى والفرقان", "البيّنات جمع بيّنة، والهدى الإرشاد، والمراد أن القرآن نزل هادياً وفارقاً بين الحق والباطل في كل شؤون الحياة."], ["شهد الشهر", "حضر الإعلان عن رؤية الهلال."], ["فعدّة من أيام أخر", "فعليه القضاء بعدد الأيام التي أفطرها مريضاً أو مسافراً."], ["ولتكملوا العدة", "وجب القضاء من أجل إكمال عدة الشهر ثلاثين يوماً أو تسعة وعشرين."], ["ولتكبّروا الله على ما هداكم", "عند إتمام صيام رمضان، من رؤية هلال شوال إلى العودة من صلاة العيد."], ["ولعلكم تشكرون", "فُرض عليكم الصوم وندبكم إلى التكبير لتكونوا من الشاكرين لله، لأن الشكر هو الطاعة."]], "m": "لما ذكر الله أنه كتب الصيام على هذه الأمة أياماً معدودات، بيّن في هذه الآية أن المراد بها أيام شهر رمضان المبارك، الذي أنزل فيه القرآن هادياً وموضّحاً طرق الهداية وفارقاً بين الحق والباطل. فمن حضر الشهر غير مسافر لما أُعلن عن رؤية الهلال فليصمه وجوباً إن كان مكلفاً. ثم ذكر عذر المرض والسفر، وأن على من أفطر بهما قضاء ما أفطر بعدده. وأخبر أنه يريد بالإذن في الإفطار اليسر بالأمة ولا يريد بها العسر. وعلّل القضاء بأمرين: لتكملوا عدة الشهر، ولتكبّروا الله على ما هداكم عند إتمام الصيام برؤية هلال شوال. وأخيراً ليُعدّكم بالصيام والذكر للشكر: لعلكم تشكرون.", "h": ["فضل شهر رمضان وفضل القرآن.", "وجوب صيام رمضان على المكلفين، وهو المسلم العاقل البالغ مع سلامة المرأة من الحيض والنفاس.", "الرخصة للمريض الذي يخاف تأخر برئه أو زيادة مرضه، وللمسافر مسافة القصر.", "وجوب القضاء على من أفطر لعذر.", "يُسر الشريعة الإسلامية وخلوّها من العسر والحرج.", "مشروعية التكبير ليلة العيد ويومه، وهو من شكر نعمة الهداية إلى الإسلام.", "الطاعات هي الشكر، فمن لم يطع الله ورسوله لم يكن شاكراً."], "k": "هل أعتبر القرآن هديةَ رمضان فعلاً، فأفتحه فيه كما أفتح الهدية الغالية؟"}, {"lbl": "الآية ١٨٦", "q": "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ ﴿١٨٦﴾", "w": [["فليستجيبوا لي", "فليجيبوا ندائي إذا دعوتُهم لطاعتي وطاعة رسولي، بفعل المأمور وترك المنهي والتقرب إليّ بفعل القربات وترك ما يوجب السخط."], ["يرشدون", "يبلغون كمال القوتين العلمية والعملية؛ فالرشد هو العلم بما يحبه الله وما يسخطه، وفعل ما يحب وترك ما يسخط. ومن لا علم له ولا عمل فهو السفيه الغاوي الضال الهالك."]], "m": "ورد أن جماعة من الصحابة سألوا النبي ﷺ: أقريب ربنا فنناجيه أم بعيد فنناديه؟ فأنزل الله: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِ﴾. والمناجاة: المكالمة بخفض الصوت، والمناداة: برفع الصوت. وإجابة الله دعوة عبده قبول طلبه وإعطاؤه مطلوبه. وما على العباد إلا أن يستجيبوا لربهم بالإيمان به وطاعته في أمره ونهيه، وبذلك يتم رشدهم ويتأهلون للكمال والإسعاد في الدنيا والآخرة.", "h": ["قرب الله من عباده، فالعوالم كلها في قبضته وتحت سلطانه، ولا يبعد عنه شيء من خلقه، فما من كائن إلا والله يراه ويسمعه ويقدر عليه؛ وهذه حقيقة القرب.", "كراهية رفع الصوت بالعبادات إلا ما كان في التلبية والأذان والإقامة.", "وجوب الاستجابة لله بالإيمان وصالح الأعمال.", "الرشد في طاعة الله، والغيّ والسفه في معصيته.", "فضل الدعاء، فقد سمّاه النبي ﷺ عبادة. ومما يمنع الإجابة أكل الحرام والاستعجال بقول: دعوتُ فلم يُستجب لي."], "k": "ما الدعاء الذي أُلحّ فيه، وهل أستجيب لله فيما طلبه مني قبل أن أطلب منه؟"}, {"lbl": "الآية ١٨٧", "q": "أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ ﴿١٨٧﴾", "w": [["ليلة الصيام", "الليلة التي يصبح العبد بعدها صائماً."], ["الرفث", "الجماع."], ["لباس لكم", "كناية عن اختلاط بعضكم ببعض كاختلاط الثوب بالبدن."], ["تختانون أنفسكم", "بتعريضها للعقاب ونقصان حظها من الثواب بالجماع ليلة الصيام قبل أن يحلّ الله ذلك."], ["باشروهنّ", "جامعوهنّ، وأباح لهم ذلك ليلاً."], ["وابتغوا ما كتب الله لكم", "اطلبوا بالجماع الولد إن كُتب لكم، ولا يكن لمجرد الشهوة."], ["الخيط الأبيض", "الفجر الكاذب، بياض يلوح في الأفق كذَنَب السِّرحان."], ["الخيط الأسود", "سواد يأتي بعد البياض الأول فينسخه تماماً، وهو الفجر الصادق."], ["عاكفون في المساجد", "منقطعون إلى العبادة في المسجد تقرباً إلى الله."], ["حدود الله", "جمع حد، وهو ما شرع الله من الطاعات فعلاً أو تركاً."], ["كذلك يبيّن الله آياته", "كما بيّن أحكام الصيام يبيّن أحكام سائر العبادات ليهيّئهم للتقوى."]], "m": "كان في بداية فرض الصيام أن من نام بالليل لم يأكل ولم يشرب ولم يقرب امرأته حتى الليلة الآتية، كأن الصيام يبتدئ من النوم لا من طلوع الفجر. ثم إن ناساً أتَوا نساءهم وأخبروا بذلك رسول الله ﷺ، فنزلت هذه الآية تُبيح لهم الأكل والشرب والجماع طوال الليل إلى طلوع الفجر. وأعلمهم الله أنه علم منهم ما فعلوه من إتيان نسائهم ليلاً قبل أن ينزل الحكم، فكان خيانة منهم لأنفسهم، فتاب عليهم وعفا عنهم. وأعلن الإباحة بقوله: فالآن باشروهنّ وابتغوا ما كتب الله لكم، أي الولد، لأن الجماع لا يكون لمجرد قضاء الشهوة. وحدّد وقت الصيام: من طلوع الفجر حتى الليل. وحرّم على المعتكفين في المساجد مباشرة نسائهم، فمن اعتكف لم يحلّ له الخروج من المسجد ليأتي امرأته، فإن فعل أثِم وفسد اعتكافه ووجب قضاؤه. وأخبر أن ما بيّنه من الواجبات والمحرمات هو حدوده فلا يحلّ تعدّيها، ومنّ على المسلمين ببيان الشرائع والأحكام ليُعدّهم للتقوى، إذ لا تكون تقوى ما لم تكن شرائع تُتّبع وحدود تُحترم.", "h": ["إباحة الأكل والشرب والجماع في ليالي الصيام، من غروب الشمس إلى طلوع الفجر.", "بيان ظرف الصيام، وهو من طلوع الفجر الصادق إلى غروب الشمس، وما يُمسك عنه الصائم: الأكل والشرب والجماع.", "مشروعية الاعتكاف وخاصة في رمضان، وأن المعتكف لا يحل له مخالطة امرأته حتى تنتهي مدة اعتكافه.", "استعمال الكناية بدل التصريح فيما يُستحيا من ذكره، فقد كنّى بالمباشرة عن الوطء.", "حرمة انتهاك حرمات الشرع وتعدّي حدوده.", "الغاية من إنزال الشرائع ووضع الحدود هي تقوى الله عز وجل."], "k": "أي حدّ من حدود الله أقترب منه أحياناً وأنا أظن أنه «شيء بسيط»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 26;
insert into public.tdb_cards(topic, i, body) select 26, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٨٣ – ١٨٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ﴿١٨٣﴾ أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿١٨٤﴾", "w": [["الصيام", "في اللغة الإمساك، والمراد هنا الامتناع عن الأكل والشرب والجماع من طلوع الفجر إلى غروب الشمس."], ["أياماً معدودات", "تسعة وعشرون يوماً أو ثلاثون، بحسب شهر رمضان."], ["فعدّة من أيام أُخر", "على من أفطر لعذر المرض أو السفر صيام أيام أخرى بعدد الأيام التي أفطر فيها."], ["يطيقونه", "يتحمّلونه بمشقة لكبر سن أو مرض لا يُرجى برؤه."], ["فدية طعام مسكين", "على من أفطر لعذر مما ذُكر أن يُطعم عن كل يوم مسكيناً، ولا قضاء عليه."], ["فمن تطوّع خيراً", "زاد على المقدار، أو أطعم أكثر من مسكين فهو خير له."], ["وأن تصوموا خير لكم", "الصيام لمن يطيقه ولو بمشقة خير من الإفطار مع الطعام."]], "m": "لما هاجر الرسول ﷺ إلى المدينة وصارت دار إسلام، أخذ التشريع ينزل ويتوالى. ففي الآيات السابقة كان حكم القصاص والوصية ومراقبة الله فيهما، وأعظم ما يُنمّي في المؤمن ملَكة التقوى الصيام، فأنزل الله فرض الصيام في السنة الثانية للهجرة. ناداهم بعنوان الإيمان، وأعلمهم أنه كتب عليهم الصيام كما كتبه على الأمم السابقة، وعلّل ذلك بقوله: لعلكم تتقون، أي ليُعدّكم به للتقوى، وهي امتثال الأوامر واجتناب النواهي، لما في الصيام من مراقبة الله. وقوله «أياماً معدودات» ليهوّن عليهم مشقة الصوم، إذ لم يجعله شهوراً ولا أعواماً. وزاد في التخفيف: فمن كان مريضاً أو على سفر فعدّة من أيام أخر. وجعل لمن يطيق الصيام بمشقة شديدة أن يفطر ويطعم عن كل يوم مسكيناً، وأعلمهم أن الصيام في هذه الحال خير. ثم نُسخ هذا الحكم الأخير بقوله في الآية الآتية: ﴿فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ﴾. وقوله «إن كنتم تعلمون» أي تعلمون فوائد الصوم الدنيوية والأخروية، وهي كثيرة، أجلّها مغفرة الذنوب وذهاب الأمراض.", "h": ["فرضية الصيام، وهو شهر رمضان.", "يجوز للحامل والمرضع الإفطار مع القضاء، وكذا الشيخ الكبير والمريض مرضاً لا يُرجى برؤه، وعليهما أن يطعما عن كل يوم مسكيناً.", "في الصيام فوائد دينية واجتماعية عظيمة، أُشير إليها بقوله: «إن كنتم تعلمون».", "من هذه الفوائد: يعوّد الصائم خشية الله في السر والعلن، ويكسر حدّة الشهوة، ويربّي الشفقة والرحمة في النفس، ويحقق المساواة بين الأغنياء والفقراء، ويعوّد الأمة النظام والوحدة والوئام، ويذهب المواد المترسبة في البدن فتتحسن صحة الصائم."], "k": "ما الذي أريد أن يتغير في نفسي بعد رمضان القادم، لتكون ثمرة صيامي «لعلكم تتقون»؟"}, {"lbl": "الآية ١٨٥", "q": "شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٨٥﴾", "w": [["شهر رمضان", "الشهر التاسع من الشهور القمرية؛ ولفظ «الشهر» مأخوذ من الشهرة، و«رمضان» من رَمِض الصائم إذا حرّ جوفه من العطش."], ["هدى للناس", "هادياً للناس إلى ما فيه كمالهم وسعادتهم في الدارين."], ["وبيّنات من الهدى والفرقان", "البيّنات جمع بيّنة، والهدى الإرشاد، والمراد أن القرآن نزل هادياً وفارقاً بين الحق والباطل في كل شؤون الحياة."], ["شهد الشهر", "حضر الإعلان عن رؤية الهلال."], ["فعدّة من أيام أخر", "فعليه القضاء بعدد الأيام التي أفطرها مريضاً أو مسافراً."], ["ولتكملوا العدة", "وجب القضاء من أجل إكمال عدة الشهر ثلاثين يوماً أو تسعة وعشرين."], ["ولتكبّروا الله على ما هداكم", "عند إتمام صيام رمضان، من رؤية هلال شوال إلى العودة من صلاة العيد."], ["ولعلكم تشكرون", "فُرض عليكم الصوم وندبكم إلى التكبير لتكونوا من الشاكرين لله، لأن الشكر هو الطاعة."]], "m": "لما ذكر الله أنه كتب الصيام على هذه الأمة أياماً معدودات، بيّن في هذه الآية أن المراد بها أيام شهر رمضان المبارك، الذي أنزل فيه القرآن هادياً وموضّحاً طرق الهداية وفارقاً بين الحق والباطل. فمن حضر الشهر غير مسافر لما أُعلن عن رؤية الهلال فليصمه وجوباً إن كان مكلفاً. ثم ذكر عذر المرض والسفر، وأن على من أفطر بهما قضاء ما أفطر بعدده. وأخبر أنه يريد بالإذن في الإفطار اليسر بالأمة ولا يريد بها العسر. وعلّل القضاء بأمرين: لتكملوا عدة الشهر، ولتكبّروا الله على ما هداكم عند إتمام الصيام برؤية هلال شوال. وأخيراً ليُعدّكم بالصيام والذكر للشكر: لعلكم تشكرون.", "h": ["فضل شهر رمضان وفضل القرآن.", "وجوب صيام رمضان على المكلفين، وهو المسلم العاقل البالغ مع سلامة المرأة من الحيض والنفاس.", "الرخصة للمريض الذي يخاف تأخر برئه أو زيادة مرضه، وللمسافر مسافة القصر.", "وجوب القضاء على من أفطر لعذر.", "يُسر الشريعة الإسلامية وخلوّها من العسر والحرج.", "مشروعية التكبير ليلة العيد ويومه، وهو من شكر نعمة الهداية إلى الإسلام.", "الطاعات هي الشكر، فمن لم يطع الله ورسوله لم يكن شاكراً."], "k": "هل أعتبر القرآن هديةَ رمضان فعلاً، فأفتحه فيه كما أفتح الهدية الغالية؟"}, {"lbl": "الآية ١٨٦", "q": "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ ﴿١٨٦﴾", "w": [["فليستجيبوا لي", "فليجيبوا ندائي إذا دعوتُهم لطاعتي وطاعة رسولي، بفعل المأمور وترك المنهي والتقرب إليّ بفعل القربات وترك ما يوجب السخط."], ["يرشدون", "يبلغون كمال القوتين العلمية والعملية؛ فالرشد هو العلم بما يحبه الله وما يسخطه، وفعل ما يحب وترك ما يسخط. ومن لا علم له ولا عمل فهو السفيه الغاوي الضال الهالك."]], "m": "ورد أن جماعة من الصحابة سألوا النبي ﷺ: أقريب ربنا فنناجيه أم بعيد فنناديه؟ فأنزل الله: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِ﴾. والمناجاة: المكالمة بخفض الصوت، والمناداة: برفع الصوت. وإجابة الله دعوة عبده قبول طلبه وإعطاؤه مطلوبه. وما على العباد إلا أن يستجيبوا لربهم بالإيمان به وطاعته في أمره ونهيه، وبذلك يتم رشدهم ويتأهلون للكمال والإسعاد في الدنيا والآخرة.", "h": ["قرب الله من عباده، فالعوالم كلها في قبضته وتحت سلطانه، ولا يبعد عنه شيء من خلقه، فما من كائن إلا والله يراه ويسمعه ويقدر عليه؛ وهذه حقيقة القرب.", "كراهية رفع الصوت بالعبادات إلا ما كان في التلبية والأذان والإقامة.", "وجوب الاستجابة لله بالإيمان وصالح الأعمال.", "الرشد في طاعة الله، والغيّ والسفه في معصيته.", "فضل الدعاء، فقد سمّاه النبي ﷺ عبادة. ومما يمنع الإجابة أكل الحرام والاستعجال بقول: دعوتُ فلم يُستجب لي."], "k": "ما الدعاء الذي أُلحّ فيه، وهل أستجيب لله فيما طلبه مني قبل أن أطلب منه؟"}, {"lbl": "الآية ١٨٧", "q": "أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ ﴿١٨٧﴾", "w": [["ليلة الصيام", "الليلة التي يصبح العبد بعدها صائماً."], ["الرفث", "الجماع."], ["لباس لكم", "كناية عن اختلاط بعضكم ببعض كاختلاط الثوب بالبدن."], ["تختانون أنفسكم", "بتعريضها للعقاب ونقصان حظها من الثواب بالجماع ليلة الصيام قبل أن يحلّ الله ذلك."], ["باشروهنّ", "جامعوهنّ، وأباح لهم ذلك ليلاً."], ["وابتغوا ما كتب الله لكم", "اطلبوا بالجماع الولد إن كُتب لكم، ولا يكن لمجرد الشهوة."], ["الخيط الأبيض", "الفجر الكاذب، بياض يلوح في الأفق كذَنَب السِّرحان."], ["الخيط الأسود", "سواد يأتي بعد البياض الأول فينسخه تماماً، وهو الفجر الصادق."], ["عاكفون في المساجد", "منقطعون إلى العبادة في المسجد تقرباً إلى الله."], ["حدود الله", "جمع حد، وهو ما شرع الله من الطاعات فعلاً أو تركاً."], ["كذلك يبيّن الله آياته", "كما بيّن أحكام الصيام يبيّن أحكام سائر العبادات ليهيّئهم للتقوى."]], "m": "كان في بداية فرض الصيام أن من نام بالليل لم يأكل ولم يشرب ولم يقرب امرأته حتى الليلة الآتية، كأن الصيام يبتدئ من النوم لا من طلوع الفجر. ثم إن ناساً أتَوا نساءهم وأخبروا بذلك رسول الله ﷺ، فنزلت هذه الآية تُبيح لهم الأكل والشرب والجماع طوال الليل إلى طلوع الفجر. وأعلمهم الله أنه علم منهم ما فعلوه من إتيان نسائهم ليلاً قبل أن ينزل الحكم، فكان خيانة منهم لأنفسهم، فتاب عليهم وعفا عنهم. وأعلن الإباحة بقوله: فالآن باشروهنّ وابتغوا ما كتب الله لكم، أي الولد، لأن الجماع لا يكون لمجرد قضاء الشهوة. وحدّد وقت الصيام: من طلوع الفجر حتى الليل. وحرّم على المعتكفين في المساجد مباشرة نسائهم، فمن اعتكف لم يحلّ له الخروج من المسجد ليأتي امرأته، فإن فعل أثِم وفسد اعتكافه ووجب قضاؤه. وأخبر أن ما بيّنه من الواجبات والمحرمات هو حدوده فلا يحلّ تعدّيها، ومنّ على المسلمين ببيان الشرائع والأحكام ليُعدّهم للتقوى، إذ لا تكون تقوى ما لم تكن شرائع تُتّبع وحدود تُحترم.", "h": ["إباحة الأكل والشرب والجماع في ليالي الصيام، من غروب الشمس إلى طلوع الفجر.", "بيان ظرف الصيام، وهو من طلوع الفجر الصادق إلى غروب الشمس، وما يُمسك عنه الصائم: الأكل والشرب والجماع.", "مشروعية الاعتكاف وخاصة في رمضان، وأن المعتكف لا يحل له مخالطة امرأته حتى تنتهي مدة اعتكافه.", "استعمال الكناية بدل التصريح فيما يُستحيا من ذكره، فقد كنّى بالمباشرة عن الوطء.", "حرمة انتهاك حرمات الشرع وتعدّي حدوده.", "الغاية من إنزال الشرائع ووضع الحدود هي تقوى الله عز وجل."], "k": "أي حدّ من حدود الله أقترب منه أحياناً وأنا أظن أنه «شيء بسيط»؟"}]$j$::jsonb) with ordinality x(e, i);

-- 27. سورة البقرة ١٨٨ – ١٩٥ · أكل المال بالباطل والأهلة وقتال المعتدين
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (27, 2, 188, 195, 'سورة البقرة ١٨٨ – ١٩٥', 'أكل المال بالباطل والأهلة وقتال المعتدين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 27) = $j$[{"lbl": "الآية ١٨٨", "q": "وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ ﴿١٨٨﴾", "w": [["الباطل", "خلاف الحق."], ["تدلوا بها إلى الحكام", "تعطوا الرشوة للقضاة والحكام ليحكموا لكم بالباطل حتى تصلوا إلى أموال غيركم."], ["فريقاً", "طائفة وقطعة من المال."], ["بالإثم", "بالرشوة وشهادة الزور واليمين الفاجرة، وهي الحلف بالكذب ليقضي القاضي لكم بالباطل في صورة حق."]], "m": "لما بيّن الله في الآية السابقة أنه يوضّح للناس أحكام دينه ليتقوه، بيّن هنا حكم أكل أموال المسلمين بالباطل، وأنه حرام فلا يحلّ لمسلم أن يأكل مال أخيه بغير طيب نفس منه. وذكر نوعاً هو من شر أنواع أكل المال بالباطل، وهو دفع الرشوة إلى القضاة والحكام ليحكموا لهم بغير الحق، فيُوقعوا القضاة في الحكم بغير الحق ويأكلوا أموال إخوانهم بشهادة الزور واليمين الغموس، وهي التي يحلف فيها المرء كاذباً.", "h": ["حرمة أكل مال المسلم بغير حق، سواء كان بسرقة أو غصب أو غش أو احتيال ومغالطة.", "حرمة الرشوة تُدفع للحاكم ليحكم بغير الحق.", "مال الكافر غير المحارب كمال المسلم في الحرمة، إلا أن مال المسلم أشد حرمة لحديث: «كل المسلم على المسلم حرام: دمه وعرضه وماله»."], "k": "هل في معاملاتي اليومية مال لا أطمئن إلى حلّه، ولو كان القانون يسمح به؟"}, {"lbl": "الآية ١٨٩", "q": "۞يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٨٩﴾", "w": [["الأهلة", "جمع هلال، وهو القمر في أول ظهوره في الأيام الثلاثة الأولى من الشهر."], ["مواقيت", "جمع ميقات، وهو الوقت المحدد المعلوم للناس."], ["إتيان البيوت من ظهورها", "أن يتسوّر الرجل الجدار ويدخل البيت من خلفه تحاشياً أن يدخل من الباب."], ["البرّ", "البر الموصل إلى رضوان الله هو بر من اتقى الله بفعل أوامره واجتناب نواهيه."], ["الفلاح", "الفوز، وهو النجاة من النار ودخول الجنة."]], "m": "روي أن بعض الصحابة سألوا النبي ﷺ: ما بال الهلال يبدو دقيقاً ثم يزيد حتى يعظم ويصير بدراً، ثم لا يزال ينقص حتى يعود كما كان؟ فأنزل الله: ﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ﴾ وأمر رسوله أن يقول لهم: هي مواقيت للناس، يعرفون بها أوقاتهم التي يؤقّتون بها أعمالهم؛ فبوجود القمر على هذه الأحوال تُعرف عدة النساء، وتُعرف الشهور فيُعرف رمضان وشهر الحج ووقته، وتُعرف آجال العقود في البيع والإيجار وسداد الديون. وكان الأنصار في الجاهلية إذا أحرم أحدهم بحج أو عمرة وخرج من بيته ثم أراد أن يدخل لغرض خاص لم يدخل من الباب، بل يتسوّر الجدار ويدخل من خلف البيت، ويرون ذلك طاعة وبراً، فأبطل الله هذه العبادة الجاهلية، وأمرهم أن يأتوا البيوت من أبوابها، وأمرهم بتقواه ليفلحوا في الدنيا والآخرة.", "h": ["أن يسأل المرء عما ينفعه ويترك السؤال عما لا يعنيه.", "فائدة الشهور القمرية عظيمة، إذ بها تُعرف كثير من العبادات.", "حرمة الابتداع في الدين ولو كان برغبة في طاعة الله وحصول الأجر.", "الأمر بالتقوى المفضية إلى فلاح العبد ونجاته في الدارين."], "k": "ما الذي أحسبه «برّاً» وهو عادة ورثتُها، وليس في ما شرع الله؟"}, {"lbl": "الآيات ١٩٠ – ١٩٣", "q": "وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿١٩٠﴾ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ ﴿١٩١﴾ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٩٢﴾ وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ ﴿١٩٣﴾", "w": [["سبيل الله", "الطريق الموصل إلى رضوانه، وهو الإسلام؛ والمراد إعلاء كلمة الله."], ["الذين يقاتلونكم", "المشركون الذين يبدؤونكم بالقتال."], ["ولا تعتدوا", "لا تجاوزوا الحد فتقتلوا النساء والأطفال ومن اعتزل القتال."], ["ثقفتموهم", "تمكنتم من قتالهم."], ["الفتنة", "الشرك، وفتنة المؤمنين لحملهم على الكفر بالاضطهاد والتعذيب."], ["المسجد الحرام", "المراد به مكة والحرم من حولها."], ["ويكون الدين لله", "بأن لا يبقى من يُضطهد في دينه ولا من يعبد غير الله."], ["فلا عدوان إلا على الظالمين", "لا اعتداء بالقتل والمحاربة إلا على الظالمين، أما من أسلم فلا يُقاتل."]], "m": "هذه الآيات من أوائل ما نزل في شأن قتال المشركين، وهي تتضمن الإذن للرسول ﷺ والمؤمنين بقتال من يقاتلهم والكفّ عمن يكفّ عنهم. قال تعالى: قاتلوا في سبيل الله، أي في سبيل إعلاء كلمته ليُعبد وحده، الذين يقاتلونكم، واقتلوهم حيث تمكنتم منهم، وأخرجوهم من ديارهم كما أخرجوكم أيها المهاجرون من دياركم، ولا تتحرّجوا من القتل، فإن فتنتهم للمؤمنين بالاضطهاد والتعذيب أشد من القتل. ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه، فلا تكونوا البادئين، فإن قاتلوكم فاقتلوهم. فإن انتهوا عن الشرك وأسلموا فإن الله يغفر لهم ويرحمهم. وأما الآية الرابعة فهي مقرّرة لما قبلها: قاتلوا المشركين حتى لا يبقى في مكة من يُضطهد في دينه ويُفتن فيه، ويكون الدين كله لله. فإن انتهوا فكفّوا عنهم، إذ لا عدوان إلا على الظالمين، وهم بعد إسلامهم لم يعودوا ظالمين.", "h": ["وجوب قتال من يقاتل المسلمين والكف عمن يكف عن قتالهم، وهذا قبل نسخ هذه الآية.", "حرمة الاعتداء في القتال بقتل الأطفال والشيوخ والنساء إلا أن يقاتلوا.", "حرمة القتال عند المسجد الحرام أي مكة والحرم، إلا أن يبدأ العدو بالقتال فيه فيُقاتَل.", "الإسلام يجُبّ ما قبله، لقوله تعالى: «فإن انتهوا فإن الله غفور رحيم».", "الجهاد فرض كفاية ما وُجد مؤمن يُضطهد لإسلامه أو يُفتن في دينه."], "k": "كيف أحفظ العدل حتى في أشد الخصومة؟ وأين حدّ «ولا تعتدوا» في حياتي؟"}, {"lbl": "الآيتان ١٩٤ – ١٩٥", "q": "ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿١٩٤﴾ وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٩٥﴾", "w": [["الشهر الحرام", "الشهر المحرّم القتال فيه، والأشهر الحرم أربعة: ثلاثة سرد وواحد فرد؛ ذو القعدة وذو الحجة ومحرم، والفرد رجب."], ["الحرمات", "جمع حرمة، كالشهر الحرام والبلد الحرام والإحرام."], ["إن الله مع المتقين", "المتقون هم المؤمنون الذين يتقون معاصي الله ومخالفة سنته في الحياة، ومعيّته لهم تسديدهم وإعانتهم ونصرهم."], ["التهلكة", "الهلاك."], ["الإحسان", "إتقان الطاعة وتخليصها من شوائب الشرك، وفعل الخير أيضاً."]], "m": "في الآية الأولى تشجيع للمؤمنين المعتدى عليهم على قتال أعدائهم، وإعلام لهم أن من قاتلهم في الشهر الحرام فليقاتلوه فيه، ومن قاتلهم في الحرم فليقاتلوه في الحرم، ومن قاتلهم وهم محرمون فليقاتلوه وهم محرمون، وهكذا الحرمات قصاص، أي مساواة. ومن اعتدى عليهم فليعتدوا عليه بمثل اعتدائه. وأمرهم بتقواه وأعلمهم أنه معهم ما اتقوه بالتسديد والعون والنصر. وأما الآية الثانية فقد أمرهم بإنفاق المال في الجهاد لإعداد العدة وتسيير المقاتلين، ونهاهم أن يتركوا الإنفاق في سبيل الله، فإنهم متى تركوا الإنفاق والجهاد كانوا كمن ألقى بيده إلى الهلاك، إذ العدو المتربص بهم إذا رآهم قعدوا غزاهم وانتصر عليهم. وأمرهم بالإحسان في أعمالهم كلها، وإحسان العمل إتقانه وتجويده وتنقيته من الخلل والفساد، ووعدهم إن أحسنوا بالتأييد والنصر: إن الله يحب المحسنين، ومن أحبه الله أكرمه ونصره.", "h": ["احترام الشهر الحرام وسائر الحرمات.", "جواز المقاصّة والمجازاة لمن اعتدى، بحيث يُعامَل بما عامل به سواءً بسواء.", "ردّ الاعتداء والنيل من المعتدي الظالم البادئ بالظلم.", "معيّة الله لأهل الإيمان والتقوى والإحسان.", "فضيلة الإحسان لحب الله للمحسنين."], "k": "ما العمل الذي أستطيع أن أزيد في إتقانه هذا الأسبوع طلباً لمحبة الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 27;
insert into public.tdb_cards(topic, i, body) select 27, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ١٨٨", "q": "وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ ﴿١٨٨﴾", "w": [["الباطل", "خلاف الحق."], ["تدلوا بها إلى الحكام", "تعطوا الرشوة للقضاة والحكام ليحكموا لكم بالباطل حتى تصلوا إلى أموال غيركم."], ["فريقاً", "طائفة وقطعة من المال."], ["بالإثم", "بالرشوة وشهادة الزور واليمين الفاجرة، وهي الحلف بالكذب ليقضي القاضي لكم بالباطل في صورة حق."]], "m": "لما بيّن الله في الآية السابقة أنه يوضّح للناس أحكام دينه ليتقوه، بيّن هنا حكم أكل أموال المسلمين بالباطل، وأنه حرام فلا يحلّ لمسلم أن يأكل مال أخيه بغير طيب نفس منه. وذكر نوعاً هو من شر أنواع أكل المال بالباطل، وهو دفع الرشوة إلى القضاة والحكام ليحكموا لهم بغير الحق، فيُوقعوا القضاة في الحكم بغير الحق ويأكلوا أموال إخوانهم بشهادة الزور واليمين الغموس، وهي التي يحلف فيها المرء كاذباً.", "h": ["حرمة أكل مال المسلم بغير حق، سواء كان بسرقة أو غصب أو غش أو احتيال ومغالطة.", "حرمة الرشوة تُدفع للحاكم ليحكم بغير الحق.", "مال الكافر غير المحارب كمال المسلم في الحرمة، إلا أن مال المسلم أشد حرمة لحديث: «كل المسلم على المسلم حرام: دمه وعرضه وماله»."], "k": "هل في معاملاتي اليومية مال لا أطمئن إلى حلّه، ولو كان القانون يسمح به؟"}, {"lbl": "الآية ١٨٩", "q": "۞يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿١٨٩﴾", "w": [["الأهلة", "جمع هلال، وهو القمر في أول ظهوره في الأيام الثلاثة الأولى من الشهر."], ["مواقيت", "جمع ميقات، وهو الوقت المحدد المعلوم للناس."], ["إتيان البيوت من ظهورها", "أن يتسوّر الرجل الجدار ويدخل البيت من خلفه تحاشياً أن يدخل من الباب."], ["البرّ", "البر الموصل إلى رضوان الله هو بر من اتقى الله بفعل أوامره واجتناب نواهيه."], ["الفلاح", "الفوز، وهو النجاة من النار ودخول الجنة."]], "m": "روي أن بعض الصحابة سألوا النبي ﷺ: ما بال الهلال يبدو دقيقاً ثم يزيد حتى يعظم ويصير بدراً، ثم لا يزال ينقص حتى يعود كما كان؟ فأنزل الله: ﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ﴾ وأمر رسوله أن يقول لهم: هي مواقيت للناس، يعرفون بها أوقاتهم التي يؤقّتون بها أعمالهم؛ فبوجود القمر على هذه الأحوال تُعرف عدة النساء، وتُعرف الشهور فيُعرف رمضان وشهر الحج ووقته، وتُعرف آجال العقود في البيع والإيجار وسداد الديون. وكان الأنصار في الجاهلية إذا أحرم أحدهم بحج أو عمرة وخرج من بيته ثم أراد أن يدخل لغرض خاص لم يدخل من الباب، بل يتسوّر الجدار ويدخل من خلف البيت، ويرون ذلك طاعة وبراً، فأبطل الله هذه العبادة الجاهلية، وأمرهم أن يأتوا البيوت من أبوابها، وأمرهم بتقواه ليفلحوا في الدنيا والآخرة.", "h": ["أن يسأل المرء عما ينفعه ويترك السؤال عما لا يعنيه.", "فائدة الشهور القمرية عظيمة، إذ بها تُعرف كثير من العبادات.", "حرمة الابتداع في الدين ولو كان برغبة في طاعة الله وحصول الأجر.", "الأمر بالتقوى المفضية إلى فلاح العبد ونجاته في الدارين."], "k": "ما الذي أحسبه «برّاً» وهو عادة ورثتُها، وليس في ما شرع الله؟"}, {"lbl": "الآيات ١٩٠ – ١٩٣", "q": "وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿١٩٠﴾ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ ﴿١٩١﴾ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٩٢﴾ وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ ﴿١٩٣﴾", "w": [["سبيل الله", "الطريق الموصل إلى رضوانه، وهو الإسلام؛ والمراد إعلاء كلمة الله."], ["الذين يقاتلونكم", "المشركون الذين يبدؤونكم بالقتال."], ["ولا تعتدوا", "لا تجاوزوا الحد فتقتلوا النساء والأطفال ومن اعتزل القتال."], ["ثقفتموهم", "تمكنتم من قتالهم."], ["الفتنة", "الشرك، وفتنة المؤمنين لحملهم على الكفر بالاضطهاد والتعذيب."], ["المسجد الحرام", "المراد به مكة والحرم من حولها."], ["ويكون الدين لله", "بأن لا يبقى من يُضطهد في دينه ولا من يعبد غير الله."], ["فلا عدوان إلا على الظالمين", "لا اعتداء بالقتل والمحاربة إلا على الظالمين، أما من أسلم فلا يُقاتل."]], "m": "هذه الآيات من أوائل ما نزل في شأن قتال المشركين، وهي تتضمن الإذن للرسول ﷺ والمؤمنين بقتال من يقاتلهم والكفّ عمن يكفّ عنهم. قال تعالى: قاتلوا في سبيل الله، أي في سبيل إعلاء كلمته ليُعبد وحده، الذين يقاتلونكم، واقتلوهم حيث تمكنتم منهم، وأخرجوهم من ديارهم كما أخرجوكم أيها المهاجرون من دياركم، ولا تتحرّجوا من القتل، فإن فتنتهم للمؤمنين بالاضطهاد والتعذيب أشد من القتل. ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه، فلا تكونوا البادئين، فإن قاتلوكم فاقتلوهم. فإن انتهوا عن الشرك وأسلموا فإن الله يغفر لهم ويرحمهم. وأما الآية الرابعة فهي مقرّرة لما قبلها: قاتلوا المشركين حتى لا يبقى في مكة من يُضطهد في دينه ويُفتن فيه، ويكون الدين كله لله. فإن انتهوا فكفّوا عنهم، إذ لا عدوان إلا على الظالمين، وهم بعد إسلامهم لم يعودوا ظالمين.", "h": ["وجوب قتال من يقاتل المسلمين والكف عمن يكف عن قتالهم، وهذا قبل نسخ هذه الآية.", "حرمة الاعتداء في القتال بقتل الأطفال والشيوخ والنساء إلا أن يقاتلوا.", "حرمة القتال عند المسجد الحرام أي مكة والحرم، إلا أن يبدأ العدو بالقتال فيه فيُقاتَل.", "الإسلام يجُبّ ما قبله، لقوله تعالى: «فإن انتهوا فإن الله غفور رحيم».", "الجهاد فرض كفاية ما وُجد مؤمن يُضطهد لإسلامه أو يُفتن في دينه."], "k": "كيف أحفظ العدل حتى في أشد الخصومة؟ وأين حدّ «ولا تعتدوا» في حياتي؟"}, {"lbl": "الآيتان ١٩٤ – ١٩٥", "q": "ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿١٩٤﴾ وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٩٥﴾", "w": [["الشهر الحرام", "الشهر المحرّم القتال فيه، والأشهر الحرم أربعة: ثلاثة سرد وواحد فرد؛ ذو القعدة وذو الحجة ومحرم، والفرد رجب."], ["الحرمات", "جمع حرمة، كالشهر الحرام والبلد الحرام والإحرام."], ["إن الله مع المتقين", "المتقون هم المؤمنون الذين يتقون معاصي الله ومخالفة سنته في الحياة، ومعيّته لهم تسديدهم وإعانتهم ونصرهم."], ["التهلكة", "الهلاك."], ["الإحسان", "إتقان الطاعة وتخليصها من شوائب الشرك، وفعل الخير أيضاً."]], "m": "في الآية الأولى تشجيع للمؤمنين المعتدى عليهم على قتال أعدائهم، وإعلام لهم أن من قاتلهم في الشهر الحرام فليقاتلوه فيه، ومن قاتلهم في الحرم فليقاتلوه في الحرم، ومن قاتلهم وهم محرمون فليقاتلوه وهم محرمون، وهكذا الحرمات قصاص، أي مساواة. ومن اعتدى عليهم فليعتدوا عليه بمثل اعتدائه. وأمرهم بتقواه وأعلمهم أنه معهم ما اتقوه بالتسديد والعون والنصر. وأما الآية الثانية فقد أمرهم بإنفاق المال في الجهاد لإعداد العدة وتسيير المقاتلين، ونهاهم أن يتركوا الإنفاق في سبيل الله، فإنهم متى تركوا الإنفاق والجهاد كانوا كمن ألقى بيده إلى الهلاك، إذ العدو المتربص بهم إذا رآهم قعدوا غزاهم وانتصر عليهم. وأمرهم بالإحسان في أعمالهم كلها، وإحسان العمل إتقانه وتجويده وتنقيته من الخلل والفساد، ووعدهم إن أحسنوا بالتأييد والنصر: إن الله يحب المحسنين، ومن أحبه الله أكرمه ونصره.", "h": ["احترام الشهر الحرام وسائر الحرمات.", "جواز المقاصّة والمجازاة لمن اعتدى، بحيث يُعامَل بما عامل به سواءً بسواء.", "ردّ الاعتداء والنيل من المعتدي الظالم البادئ بالظلم.", "معيّة الله لأهل الإيمان والتقوى والإحسان.", "فضيلة الإحسان لحب الله للمحسنين."], "k": "ما العمل الذي أستطيع أن أزيد في إتقانه هذا الأسبوع طلباً لمحبة الله؟"}]$j$::jsonb) with ordinality x(e, i);

-- 28. سورة البقرة ١٩٦ – ٢٠٣ · أحكام الحج
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (28, 2, 196, 203, 'سورة البقرة ١٩٦ – ٢٠٣', 'أحكام الحج', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 28) = $j$[{"lbl": "الآية ١٩٦", "q": "وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿١٩٦﴾", "w": [["وأتموا الحج والعمرة لله", "إتمامهما أن يُحرم بهما من الميقات، ويأتي بأركانهما وواجباتهما على الوجه المطلوب شرعاً، ويخلص فيهما لله."], ["أُحصرتم", "الإحصار أن يعجز الحاج أو المعتمر عن إتمام حجه أو عمرته، إما بعدو يصدّه عن دخول مكة، أو بمرض شديد لا يقدر معه على مواصلة السير."], ["فما استيسر من الهدي", "الواجب على من أُحصر ما تيسر له من الهدي: شاة أو بقرة أو بعير."], ["حتى يبلغ الهدي محلّه", "لا يتحلل المحصر من إحرامه حتى يذبح ما تيسر له من الهدي، فإذا ذبح تحلل بحلق رأسه."], ["ففدية", "فالواجب فدية من صيام أو صدقة أو نسك."], ["فمن تمتع بالعمرة إلى الحج", "من أحرم بعمرة في أشهر الحج وتحلل وبقي في مكة ينتظر الحج ثم حج، فالواجب عليه ما استيسر من الهدي."], ["حاضري المسجد الحرام", "سكان مكة والحرم حولها، فلا يجب عليهم شيء إن تمتعوا."]], "m": "يأمر الله عباده المؤمنين أن يتموا الحج والعمرة له، فيأتوا بهما على الوجه المطلوب ويريدوا بهما وجه الله. ويخبرهم أنهم إذا أُحصروا فلم يتمكنوا من إتمامهما، فالواجب أن يذبحوا أو ينحروا ما تيسر لهم، فإذا ذبحوا حلّوا من إحرامهم بحلق شعور رؤوسهم أو تقصيرها. وأعلمهم أن من كان منهم مريضاً أو به أذى من رأسه واضطر إلى حلق شعره أو لبس ثوب أو تغطية رأس، فالواجب بعد أن يفعل ذلك فدية، وهي واحد من ثلاثة على التخيير: صيام ثلاثة أيام، أو إطعام ستة مساكين لكل مسكين حفنتان من طعام، أو ذبح شاة. وأعلمهم أن من تمتع بالعمرة إلى الحج ولم يكن من سكان الحرم فعليه ما استيسر من الهدي، فإن لم يجد صام ثلاثة أيام في الحج، من أول ذي الحجة إلى يوم التاسع منه، وسبعة أيام إذا رجع إلى بلاده. وأمرهم بتقواه، وهي امتثال أوامره والأخذ بشرعه، وحذّرهم من إهمال أمره والاستخفاف بشرعه: واتقوا الله واعلموا أن الله شديد العقاب.", "h": ["وجوب إتمام الحج والعمرة لمن شرع فيهما بالإحرام من الميقات، وإن كان الحج تطوعاً والعمرة غير واجبة.", "حكم الإحصار: ذبح شاة من مكان الإحصار ثم التحلل بالحلق أو التقصير، ثم القضاء من قابل إن تيسر، لأن الرسول ﷺ وأصحابه قضوا العمرة التي صُدّوا فيها عن المسجد الحرام عام الحديبية.", "فدية الأذى: من ارتكب محظوراً من محظورات الإحرام كأن حلق أو لبس مخيطاً أو غطى رأسه لعذر، وجبت عليه فدية: صيام أو إطعام أو ذبح شاة.", "حكم التمتع: من كان من غير سكان مكة والحرم وأحرم بعمرة في أشهر الحج وتحلل وبقي في مكة وحج من عامه، فعليه ذبح شاة، فإن عجز صام ثلاثة أيام في مكة وسبعة في بلاده.", "الأمر بالتقوى، وهي طاعة الله بامتثال أمره واجتناب نهيه، والتحذير من تركها لما يترتب عليه من العقاب الشديد."], "k": "ما الذي أبدأ به من الطاعات ولا أتمّه؟ وهل أخلص فيه لله حتى النهاية؟"}, {"lbl": "الآيات ١٩٧ – ١٩٩", "q": "ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ﴿١٩٧﴾ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ ﴿١٩٨﴾ ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٩٩﴾", "w": [["أشهر معلومات", "شوال وذو القعدة وعشر ليال من ذي الحجة، فلا يُحرم بالحج إلا فيها."], ["فرض فيهن الحج", "نوى الحج وأحرم به."], ["فلا رفث", "الرفث الجماع ومقدماته."], ["ولا فسوق", "الخروج من طاعة الله بترك واجب أو فعل محرم."], ["ولا جدال", "المخاصمة والمنازعة."], ["تبتغوا فضلاً", "تطلبوا ربحاً في التجارة أثناء الحج."], ["المشعر الحرام", "مزدلفة، وذكر الله عندها هو صلاة المغرب والعشاء جمعاً بها، والمبيت فيها."]], "m": "ما زال السياق في بيان أحكام الحج والعمرة، فأخبر الله أن الحج له أشهر معلومة، وأن من أحرم بالحج وجب عليه أن يتجنب الرفث والفسوق والجدال، وحثّ المؤمنين على فعل الخير من صدقة وغيرها: وما تفعلوا من خير يعلمه الله، ولازمه أنه يثيب عليه. وأمر الحجاج أن يتزودوا لسفرهم بطعام وشراب يكفّون به وجوههم عن السؤال، وأرشد إلى خير الزاد وهو التقوى، ومن التقوى عدم سؤال الناس أموالهم والعبد غير محتاج. وأباح لهم الاتجار أثناء وجودهم في مكة ومنى، يريد رزقاً حلالاً بطريق التجارة المباحة. ثم أمرهم بذكر الله في مزدلفة بعد إفاضتهم من عرفة بعد غروب الشمس. وذكّرهم بنعمة هدايته لهم بعد الضلال الذي كانوا فيه، وندبهم إلى شكره بالإكثار من ذكره. ثم أمرهم بالمساواة في الوقوف بعرفة والإفاضة منها: ثم أفيضوا من حيث أفاض الناس. وأخيراً أمرهم باستغفار الله ووعدهم بالمغفرة: إن الله غفور رحيم.", "h": ["حرمة الرفث والفسوق والجدال في الإحرام.", "استحباب فعل الخيرات للحاج أثناء حجه ليعظم أجره ويبرّ حجه.", "إباحة الاتجار والعمل للحاج طلباً للرزق، على ألا يحج لأجل ذلك.", "وجوب المبيت بمزدلفة لذكر الله.", "وجوب شكر الله بذكره وطاعته على هدايته وإنعامه.", "وجوب المساواة في أداء مناسك الحج بين سائر الحجاج، فلا يتميز بعضهم عن بعض في شعيرة من شعائر الحج.", "الترغيب في الاستغفار."], "k": "ما «الزاد» الذي أتزوّد به لرحلتي الكبرى؟ وهل أتزوّد به أكثر مما أتزوّد للرحلات الصغيرة؟"}, {"lbl": "الآيات ٢٠٠ – ٢٠٣", "q": "فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ ﴿٢٠٠﴾ وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ﴿٢٠١﴾ أُوْلَـٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ ﴿٢٠٢﴾ ۞وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ ﴿٢٠٣﴾", "w": [["قضيتم مناسككم", "أدّيتموها وفرغتم منها."], ["المناسك", "جمع منسك، وهي عبادات الحج المختلفة."], ["خلاق", "حظ ونصيب."], ["حسنة الدنيا", "كل ما يسر ولا يضر، من زوجة صالحة وولد صالح ورزق حلال."], ["حسنة الآخرة", "النجاة من النار ودخول الجنان."], ["قنا", "احفظنا ونجّنا من عذاب النار."], ["نصيب", "حظ وقسط من أعمالهم الصالحة ودعائهم الصالح."], ["الأيام المعدودات", "أيام التشريق الثلاثة بعد يوم العيد."], ["تعجّل في يومين", "رمى اليوم الأول والثاني وسافر."], ["ومن تأخر", "رمى الأيام الثلاثة كلها."], ["تُحشرون", "تُجمعون للحساب والجزاء يوم القيامة."]], "m": "بهذه الآيات الأربع انتهى الكلام على أحكام الحج. ففي الأولى يرشد الله المؤمنين، إذا فرغوا من مناسكهم بأن رموا جمرة العقبة ونحروا وطافوا طواف الإفاضة واستقروا بمنى، أن يكثروا من ذكر الله عند رمي الجمرات وعند الخروج من الصلوات، على نحو ما كانوا في الجاهلية يذكرون مفاخر آبائهم وأحساب أجدادهم. وبيّن حال الناس: منهم من همّه الدنيا فلا يسأل الله إلا ما ينفعه فيها، وهذا ما كان عليه أكثر الحجاج في الجاهلية، ومنهم من يسأل الله خير الدنيا والآخرة وهم المؤمنون الموحّدون، فيقولون: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار. وفي الآية الثانية أن لأهل الدعاء الصالح نصيباً من الأجر على ما كسبوا، وهو سريع الحساب. وفي الآية الأخيرة يأمر الحجاج بذكره في أيام التشريق عند رمي الجمار وبعد الصلوات الخمس، ثم أخبرهم أنه لا حرج على من تعجّل السفر بعد رمي اليوم الثاني، ولا على من تأخر فرمى اليوم الثالث، والأمر على التخيير، ونفي الإثم مقيّد بالتقوى. ونبّههم إلى مصيرهم الحتمي، وهو الوقوف بين يديه، ليستعدوا لذلك بذكره وشكره والحرص على طاعته.", "h": ["وجوب الذكر بمنى عند رمي الجمرات، إذ يكبّر مع كل حصاة قائلاً: الله أكبر.", "فضيلة الذكر والرغبة فيه لأنه من أحبّ الأعمال إلى الله.", "فضيلة سؤال الله خير الدنيا والآخرة وعدم الاقتصار على أحدهما، وشرّ الاقتصار على الدنيا.", "فضيلة دعاء «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار»، فهي جامعة للخيرين، وكان النبي ﷺ إذا طاف بالبيت يختم بها كل شوط.", "وجوب المبيت ثلاث ليال بمنى ووجوب رمي الجمرات، إذ بهما يتأتّى ذكر الله في أيام التشريق."], "k": "هل دعائي يجمع الدنيا والآخرة، أم يقتصر على ما أحتاجه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 28;
insert into public.tdb_cards(topic, i, body) select 28, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ١٩٦", "q": "وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿١٩٦﴾", "w": [["وأتموا الحج والعمرة لله", "إتمامهما أن يُحرم بهما من الميقات، ويأتي بأركانهما وواجباتهما على الوجه المطلوب شرعاً، ويخلص فيهما لله."], ["أُحصرتم", "الإحصار أن يعجز الحاج أو المعتمر عن إتمام حجه أو عمرته، إما بعدو يصدّه عن دخول مكة، أو بمرض شديد لا يقدر معه على مواصلة السير."], ["فما استيسر من الهدي", "الواجب على من أُحصر ما تيسر له من الهدي: شاة أو بقرة أو بعير."], ["حتى يبلغ الهدي محلّه", "لا يتحلل المحصر من إحرامه حتى يذبح ما تيسر له من الهدي، فإذا ذبح تحلل بحلق رأسه."], ["ففدية", "فالواجب فدية من صيام أو صدقة أو نسك."], ["فمن تمتع بالعمرة إلى الحج", "من أحرم بعمرة في أشهر الحج وتحلل وبقي في مكة ينتظر الحج ثم حج، فالواجب عليه ما استيسر من الهدي."], ["حاضري المسجد الحرام", "سكان مكة والحرم حولها، فلا يجب عليهم شيء إن تمتعوا."]], "m": "يأمر الله عباده المؤمنين أن يتموا الحج والعمرة له، فيأتوا بهما على الوجه المطلوب ويريدوا بهما وجه الله. ويخبرهم أنهم إذا أُحصروا فلم يتمكنوا من إتمامهما، فالواجب أن يذبحوا أو ينحروا ما تيسر لهم، فإذا ذبحوا حلّوا من إحرامهم بحلق شعور رؤوسهم أو تقصيرها. وأعلمهم أن من كان منهم مريضاً أو به أذى من رأسه واضطر إلى حلق شعره أو لبس ثوب أو تغطية رأس، فالواجب بعد أن يفعل ذلك فدية، وهي واحد من ثلاثة على التخيير: صيام ثلاثة أيام، أو إطعام ستة مساكين لكل مسكين حفنتان من طعام، أو ذبح شاة. وأعلمهم أن من تمتع بالعمرة إلى الحج ولم يكن من سكان الحرم فعليه ما استيسر من الهدي، فإن لم يجد صام ثلاثة أيام في الحج، من أول ذي الحجة إلى يوم التاسع منه، وسبعة أيام إذا رجع إلى بلاده. وأمرهم بتقواه، وهي امتثال أوامره والأخذ بشرعه، وحذّرهم من إهمال أمره والاستخفاف بشرعه: واتقوا الله واعلموا أن الله شديد العقاب.", "h": ["وجوب إتمام الحج والعمرة لمن شرع فيهما بالإحرام من الميقات، وإن كان الحج تطوعاً والعمرة غير واجبة.", "حكم الإحصار: ذبح شاة من مكان الإحصار ثم التحلل بالحلق أو التقصير، ثم القضاء من قابل إن تيسر، لأن الرسول ﷺ وأصحابه قضوا العمرة التي صُدّوا فيها عن المسجد الحرام عام الحديبية.", "فدية الأذى: من ارتكب محظوراً من محظورات الإحرام كأن حلق أو لبس مخيطاً أو غطى رأسه لعذر، وجبت عليه فدية: صيام أو إطعام أو ذبح شاة.", "حكم التمتع: من كان من غير سكان مكة والحرم وأحرم بعمرة في أشهر الحج وتحلل وبقي في مكة وحج من عامه، فعليه ذبح شاة، فإن عجز صام ثلاثة أيام في مكة وسبعة في بلاده.", "الأمر بالتقوى، وهي طاعة الله بامتثال أمره واجتناب نهيه، والتحذير من تركها لما يترتب عليه من العقاب الشديد."], "k": "ما الذي أبدأ به من الطاعات ولا أتمّه؟ وهل أخلص فيه لله حتى النهاية؟"}, {"lbl": "الآيات ١٩٧ – ١٩٩", "q": "ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ﴿١٩٧﴾ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ ﴿١٩٨﴾ ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١٩٩﴾", "w": [["أشهر معلومات", "شوال وذو القعدة وعشر ليال من ذي الحجة، فلا يُحرم بالحج إلا فيها."], ["فرض فيهن الحج", "نوى الحج وأحرم به."], ["فلا رفث", "الرفث الجماع ومقدماته."], ["ولا فسوق", "الخروج من طاعة الله بترك واجب أو فعل محرم."], ["ولا جدال", "المخاصمة والمنازعة."], ["تبتغوا فضلاً", "تطلبوا ربحاً في التجارة أثناء الحج."], ["المشعر الحرام", "مزدلفة، وذكر الله عندها هو صلاة المغرب والعشاء جمعاً بها، والمبيت فيها."]], "m": "ما زال السياق في بيان أحكام الحج والعمرة، فأخبر الله أن الحج له أشهر معلومة، وأن من أحرم بالحج وجب عليه أن يتجنب الرفث والفسوق والجدال، وحثّ المؤمنين على فعل الخير من صدقة وغيرها: وما تفعلوا من خير يعلمه الله، ولازمه أنه يثيب عليه. وأمر الحجاج أن يتزودوا لسفرهم بطعام وشراب يكفّون به وجوههم عن السؤال، وأرشد إلى خير الزاد وهو التقوى، ومن التقوى عدم سؤال الناس أموالهم والعبد غير محتاج. وأباح لهم الاتجار أثناء وجودهم في مكة ومنى، يريد رزقاً حلالاً بطريق التجارة المباحة. ثم أمرهم بذكر الله في مزدلفة بعد إفاضتهم من عرفة بعد غروب الشمس. وذكّرهم بنعمة هدايته لهم بعد الضلال الذي كانوا فيه، وندبهم إلى شكره بالإكثار من ذكره. ثم أمرهم بالمساواة في الوقوف بعرفة والإفاضة منها: ثم أفيضوا من حيث أفاض الناس. وأخيراً أمرهم باستغفار الله ووعدهم بالمغفرة: إن الله غفور رحيم.", "h": ["حرمة الرفث والفسوق والجدال في الإحرام.", "استحباب فعل الخيرات للحاج أثناء حجه ليعظم أجره ويبرّ حجه.", "إباحة الاتجار والعمل للحاج طلباً للرزق، على ألا يحج لأجل ذلك.", "وجوب المبيت بمزدلفة لذكر الله.", "وجوب شكر الله بذكره وطاعته على هدايته وإنعامه.", "وجوب المساواة في أداء مناسك الحج بين سائر الحجاج، فلا يتميز بعضهم عن بعض في شعيرة من شعائر الحج.", "الترغيب في الاستغفار."], "k": "ما «الزاد» الذي أتزوّد به لرحلتي الكبرى؟ وهل أتزوّد به أكثر مما أتزوّد للرحلات الصغيرة؟"}, {"lbl": "الآيات ٢٠٠ – ٢٠٣", "q": "فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ ﴿٢٠٠﴾ وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ﴿٢٠١﴾ أُوْلَـٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ ﴿٢٠٢﴾ ۞وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ ﴿٢٠٣﴾", "w": [["قضيتم مناسككم", "أدّيتموها وفرغتم منها."], ["المناسك", "جمع منسك، وهي عبادات الحج المختلفة."], ["خلاق", "حظ ونصيب."], ["حسنة الدنيا", "كل ما يسر ولا يضر، من زوجة صالحة وولد صالح ورزق حلال."], ["حسنة الآخرة", "النجاة من النار ودخول الجنان."], ["قنا", "احفظنا ونجّنا من عذاب النار."], ["نصيب", "حظ وقسط من أعمالهم الصالحة ودعائهم الصالح."], ["الأيام المعدودات", "أيام التشريق الثلاثة بعد يوم العيد."], ["تعجّل في يومين", "رمى اليوم الأول والثاني وسافر."], ["ومن تأخر", "رمى الأيام الثلاثة كلها."], ["تُحشرون", "تُجمعون للحساب والجزاء يوم القيامة."]], "m": "بهذه الآيات الأربع انتهى الكلام على أحكام الحج. ففي الأولى يرشد الله المؤمنين، إذا فرغوا من مناسكهم بأن رموا جمرة العقبة ونحروا وطافوا طواف الإفاضة واستقروا بمنى، أن يكثروا من ذكر الله عند رمي الجمرات وعند الخروج من الصلوات، على نحو ما كانوا في الجاهلية يذكرون مفاخر آبائهم وأحساب أجدادهم. وبيّن حال الناس: منهم من همّه الدنيا فلا يسأل الله إلا ما ينفعه فيها، وهذا ما كان عليه أكثر الحجاج في الجاهلية، ومنهم من يسأل الله خير الدنيا والآخرة وهم المؤمنون الموحّدون، فيقولون: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار. وفي الآية الثانية أن لأهل الدعاء الصالح نصيباً من الأجر على ما كسبوا، وهو سريع الحساب. وفي الآية الأخيرة يأمر الحجاج بذكره في أيام التشريق عند رمي الجمار وبعد الصلوات الخمس، ثم أخبرهم أنه لا حرج على من تعجّل السفر بعد رمي اليوم الثاني، ولا على من تأخر فرمى اليوم الثالث، والأمر على التخيير، ونفي الإثم مقيّد بالتقوى. ونبّههم إلى مصيرهم الحتمي، وهو الوقوف بين يديه، ليستعدوا لذلك بذكره وشكره والحرص على طاعته.", "h": ["وجوب الذكر بمنى عند رمي الجمرات، إذ يكبّر مع كل حصاة قائلاً: الله أكبر.", "فضيلة الذكر والرغبة فيه لأنه من أحبّ الأعمال إلى الله.", "فضيلة سؤال الله خير الدنيا والآخرة وعدم الاقتصار على أحدهما، وشرّ الاقتصار على الدنيا.", "فضيلة دعاء «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار»، فهي جامعة للخيرين، وكان النبي ﷺ إذا طاف بالبيت يختم بها كل شوط.", "وجوب المبيت ثلاث ليال بمنى ووجوب رمي الجمرات، إذ بهما يتأتّى ذكر الله في أيام التشريق."], "k": "هل دعائي يجمع الدنيا والآخرة، أم يقتصر على ما أحتاجه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);

-- 29. سورة البقرة ٢٠٤ – ٢١٠ · حال المنافق والمؤمن الصادق، والدخول في السلم كافة
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (29, 2, 204, 210, 'سورة البقرة ٢٠٤ – ٢١٠', 'حال المنافق والمؤمن الصادق، والدخول في السلم كافة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 29) = $j$[{"lbl": "الآيات ٢٠٤ – ٢٠٧", "q": "وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ﴿٢٠٤﴾ وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ ﴿٢٠٥﴾ وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ ﴿٢٠٦﴾ وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ﴿٢٠٧﴾", "w": [["يعجبك", "يروق لك وتستحسنه."], ["في الحياة الدنيا", "إذا تحدث في أمور الدنيا."], ["ألدّ الخصام", "قوي الخصومة شديدها لذلاقة لسانه."], ["تولّى", "رجع وانصرف، أو كانت له ولاية."], ["سعى في الأرض", "مشى فيها بالفساد، والسعي المشي الحثيث ويُطلق على الكسب والعمل."], ["الحرث والنسل", "الحرث الزرع، والنسل الحيوان."], ["أخذته العزة بالإثم", "أخذته الحميّة والأنفة بذنوبه، فلا يتقي الله."], ["يشري نفسه", "يبيع نفسه لله بالجهاد في سبيله بنفسه وماله."]], "m": "يخبر الله عن حال المنافقين والمؤمنين الصادقين. فمن الناس رجل منافق يحسن القول فيعجبك كلامه في أمور الدنيا، ويُشهد الله أنه يعتقد ما يقول، فإذا انصرف عنك سعى في الأرض بالفساد ليهلك الحرث والنسل بارتكاب عظائم الجرائم، والله لا يحب الفساد. وإذا قيل له: اتق الله، أخذته الأنفة والحمية بذنوبه فلا يتقي الله ولا يتوب، فيكفيه جهنم ولبئس المهاد. وفي المقابل مؤمن صادق باع نفسه وماله لله طلباً لمرضاته: ومن الناس من يشري نفسه ابتغاء مرضاة الله والله رؤوف بالعباد. وقيل إن المنافق هو الأخنس بن شريق، وإن المؤمن هو صهيب الرومي الذي أعطى المشركين ماله كله وهاجر، فقال له النبي ﷺ: ربح البيع أبا يحيى. والعبرة بعموم اللفظ لا بخصوص السبب، فهما مثلان لكل من اتصف بصفاتهما.", "h": ["التحذير من الاغترار بفصاحة وبيان الرجل إذا لم يكن من أهل الإيمان والإخلاص.", "شرّ الناس من يفسد في الأرض بارتكاب الجرائم مما يسبب فساداً وهلاكاً للناس والمواشي.", "قول الرجل: «يعلم الله» و«يشهد الله» يُعتبر يميناً، فليحذر المؤمن أن يقول ذلك وهو يعلم من نفسه أنه كاذب.", "إذا قيل للمؤمن: اتق الله، وجب ألا يغضب ولا يكره ذلك، بل يعترف بذنبه ويستغفر الله ويُقلع عن المعصية فوراً.", "الترغيب في الجهاد بالنفس والمال، وجواز أن يخرج المسلم من كل ماله في سبيل الله، ولا يُعدّ ذلك إسرافاً ولا تبذيراً، إذ الإسراف والتبذير في الإنفاق في المعاصي والذنوب."], "k": "هل يوافق لساني ما في قلبي؟ وإذا قيل لي «اتق الله» فبماذا أجيب؟"}, {"lbl": "الآيات ٢٠٨ – ٢١٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿٢٠٨﴾ فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ﴿٢٠٩﴾ هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَـٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٢١٠﴾", "w": [["كافة", "جميعاً، لا يتخلف أحد عن الدخول في الإسلام ولا يُترك من شرائعه وأحكامه شيء."], ["خطوات الشيطان", "مسالكه في الدعوة إلى الباطل وتزيين الشر والقبيح."], ["زللتم", "وقعتم في الزلل، وهو الفسق والمعاصي."], ["هل ينظرون", "أي: ما ينظرون؛ والاستفهام للنفي."], ["ظلل", "جمع ظلّة، وهي ما يظلّل من سحاب أو شجر ونحوهما."], ["الغمام", "السحاب الرقيق الأبيض."]], "m": "ينادي الله عباده المؤمنين آمراً بالدخول في الإسلام دخولاً شاملاً، فلا يتخيّرون بين شرائعه وأحكامه، بل يقبلونها كافة، وينهاهم عن اتباع خطوات الشيطان في تحسين القبيح وتزيين المنكر. وفي الآية الثانية تهديد شديد لمن أزلّه الشيطان فقبل بعض الشرائع ورفض بعضها وقد عرف أن الإسلام حق: فإن زللتم من بعد ما جاءتكم البينات فاعلموا أن الله عزيز حكيم. وفي الثالثة حثّ للمتباطئين على الدخول في الإسلام إذ لا عذر لهم: هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام والملائكة، وعندئذ لا ينفع الإيمان الاضطراري لأن الأمر قد قُضي. وعبّر عن الإسلام بالسلم لأن الدخول فيه حقاً سلم والخروج منه حرب.", "h": ["وجوب قبول شرائع الإسلام كافة وحرمة التخيّر فيها.", "ما من مستحلّ حراماً أو تارك واجباً إلا وهو متبع للشيطان في ذلك.", "وجوب توقع العقوبة عند ظهور المعاصي العظام لئلا يكون أمن من مكر الله.", "إثبات صفة المجيء للرب تعالى لفصل القضاء يوم القيامة.", "حرمة التسويف والمماطلة في التوبة."], "k": "ما الحكم الشرعي الذي أتحرّج منه وأؤجّله، وأنا أقبل ما سواه بسهولة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 29;
insert into public.tdb_cards(topic, i, body) select 29, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠٤ – ٢٠٧", "q": "وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ﴿٢٠٤﴾ وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ ﴿٢٠٥﴾ وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ ﴿٢٠٦﴾ وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ﴿٢٠٧﴾", "w": [["يعجبك", "يروق لك وتستحسنه."], ["في الحياة الدنيا", "إذا تحدث في أمور الدنيا."], ["ألدّ الخصام", "قوي الخصومة شديدها لذلاقة لسانه."], ["تولّى", "رجع وانصرف، أو كانت له ولاية."], ["سعى في الأرض", "مشى فيها بالفساد، والسعي المشي الحثيث ويُطلق على الكسب والعمل."], ["الحرث والنسل", "الحرث الزرع، والنسل الحيوان."], ["أخذته العزة بالإثم", "أخذته الحميّة والأنفة بذنوبه، فلا يتقي الله."], ["يشري نفسه", "يبيع نفسه لله بالجهاد في سبيله بنفسه وماله."]], "m": "يخبر الله عن حال المنافقين والمؤمنين الصادقين. فمن الناس رجل منافق يحسن القول فيعجبك كلامه في أمور الدنيا، ويُشهد الله أنه يعتقد ما يقول، فإذا انصرف عنك سعى في الأرض بالفساد ليهلك الحرث والنسل بارتكاب عظائم الجرائم، والله لا يحب الفساد. وإذا قيل له: اتق الله، أخذته الأنفة والحمية بذنوبه فلا يتقي الله ولا يتوب، فيكفيه جهنم ولبئس المهاد. وفي المقابل مؤمن صادق باع نفسه وماله لله طلباً لمرضاته: ومن الناس من يشري نفسه ابتغاء مرضاة الله والله رؤوف بالعباد. وقيل إن المنافق هو الأخنس بن شريق، وإن المؤمن هو صهيب الرومي الذي أعطى المشركين ماله كله وهاجر، فقال له النبي ﷺ: ربح البيع أبا يحيى. والعبرة بعموم اللفظ لا بخصوص السبب، فهما مثلان لكل من اتصف بصفاتهما.", "h": ["التحذير من الاغترار بفصاحة وبيان الرجل إذا لم يكن من أهل الإيمان والإخلاص.", "شرّ الناس من يفسد في الأرض بارتكاب الجرائم مما يسبب فساداً وهلاكاً للناس والمواشي.", "قول الرجل: «يعلم الله» و«يشهد الله» يُعتبر يميناً، فليحذر المؤمن أن يقول ذ