-- 30. سورة البقرة ٢١١ – ٢١٤ · سنة الله في الاختلاف والابتلاء
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (30, 2, 211, 214, 'سورة البقرة ٢١١ – ٢١٤', 'سنة الله في الاختلاف والابتلاء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 30) = $j$[{"lbl": "الآيتان ٢١١ – ٢١٢", "q": "سَلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢١١﴾ زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٢١٢﴾", "w": [["سل", "اسأل؛ سقطت منه الهمزتان للتخفيف."], ["بني إسرائيل", "ذرية يعقوب بن إسحاق بن إبراهيم، وإسرائيل لقب يعقوب."], ["آية", "خارقة للعادة كعصا موسى تدل على أن من أعطاه الله إياها رسول حقاً؛ ومن آيات بني إسرائيل فلق البحر لهم وإنزال المنّ والسلوى عليهم في التيه."], ["نعمة الله", "ما وهبه لعبده من خير يجلب له المسرة ويدفع عنه المضرة، ونعم الله كثيرة."], ["يسخرون", "يحتقرون ويستهزئون."]], "m": "يأمر الله رسوله أن يسأل بني إسرائيل عن الآيات الكثيرة التي آتاهم الله، وكيف كفروا بها فلم تنفعهم شيئاً، والمراد تسلية النبي ﷺ من الألم النفسي الذي يصيبه من عدم إيمان أهل الكتاب والمشركين به، وفي ذلك تقريع لليهود وتأنيب على كفرهم بآيات الله وإصرارهم على عدم الدخول في الإسلام. ثم أخبر أن من يبدّل نعمة الله، وهي الإسلام، بالكفر به وبنبيه ﷺ فإن عقوبة الله تنزل به عاجلاً في الدنيا أو في الآخرة، لأن الله شديد العقاب. وأخبر في الآية الثانية أن الشيطان زيّن للذين كفروا بالله ورسوله وشرائعه الحياة الدنيا، فرغبوا فيها وعملوا لها ولم يروا غيرها، ولذلك سخروا من المؤمنين الزاهدين فيها لعلمهم بزوالها وقلة نفعها، فلم يكرّسوا كل جهدهم لجمعها بل أقبلوا على طاعة ربهم وأنفقوا ما في أيديهم في سبيل الله. وأخبر أن المؤمنين المتقين سيجازيهم يوم القيامة خير الجزاء وأوفره، ويخزي أعداءهم الساخرين منهم، والله يرزق من يشاء بغير حساب لواسع فضله.", "h": ["التحذير من كفر النعم لما يترتب عليه من أليم العذاب، ومن أجلّ النعم نعمة الإسلام، فمن كفر بها وأعرض عنها تعرّض لأشد العقوبات. وما حلّ ببني إسرائيل من ألوان الهوان دهراً طويلاً شاهد، وكذلك ما حلّ بالمسلمين يوم أعرضوا عن الإسلام واستبدلوا به الخرافات ثم القوانين الوضعية.", "التحذير من زينة الحياة الدنيا والرغبة فيها والجمع لها ونسيان الدار الآخرة وترك العمل لها؛ فأبناء الدنيا اليوم يسخرون من أبناء الآخرة، لكن أبناء الآخرة أهل الإيمان والتقوى سيكونون يوم القيامة فوقهم درجات."], "k": "هل أخجل أحياناً من التزامي بدين الله أمام من يسخر منه؟ وماذا يقول لي هذا الخجل؟"}, {"lbl": "الآية ٢١٣", "q": "كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ ﴿٢١٣﴾", "w": [["الناس أمة واحدة", "كانوا قبل وجود الشرك فيهم أمة واحدة على الإسلام والتوحيد، وذلك قبل قوم نوح."], ["النبيون", "جمع نبي، والمراد بهم الرسل، لأن رسالتهم قائمة على البشارة والنذارة المستمدة من كتب الله."], ["الكتاب", "اسم جنس يدخل فيه كل الكتب الإلهية."], ["أوتوه", "أُعطوه."], ["البينات", "الحجج والبراهين التي تحملها الرسل إليهم، وتورثها فيهم شرائع وأحكاماً وهدايات عامة."], ["بغياً", "البغي الظلم والحسد."], ["الصراط المستقيم", "الإسلام المفضي بصاحبه إلى السعادة والكمال في الحياتين."]], "m": "يخبر الله أن الناس كانوا بين آدم ونوح عليهما السلام أمة واحدة على الإسلام، حتى زيّن الشيطان لبعضهم عبادة غير الله، فبعث الله نوحاً فاختلفوا إلى مؤمن وكافر. وتوالت الرسل بكتب الله فيها الحكم الفصل فيما يختلفون فيه. ثم بيّن سنته أن الذين يختلفون في الكتاب هم الذين أُوتوه وجاءتهم البينات، فيحملهم الحسد وحب الرئاسة والإبقاء على مصالحهم على رفض ما فيه، واليهود مثل لذلك. وهدى الله أمة محمد ﷺ لما اختلف فيه أهل الكتابين من الحق بإذنه: كالإيمان بعيسى عبد الله ورسوله بلا غلو ولا جحود، ويوم الجمعة وقد أخذ اليهود السبت والنصارى الأحد، والقبلة قبلة إبراهيم عليه السلام. والله يهدي من يشاء إلى صراط مستقيم.", "h": ["الأصل هو التوحيد، والشرك طارئ على البشرية.", "الأصل في مهمة الرسل البشارة لمن آمن واتقى والنذارة لمن كفر وفجر.", "من علامات خذلان الأمة وتعرضها للخسار والدمار أن تختلف في كتابها ودينها، فيحرّفوا كلام الله ويبدلوا شرائعه طلباً للرئاسة وجرياً وراء الأهواء والعصبيات، وكان ذلك سبب دمار بني إسرائيل.", "أمة الإسلام التي تعيش على الكتاب والسنة عقيدة وعبادة وقضاء هي المعنية بقوله: «فهدى الله الذين آمنوا لما اختلفوا فيه من الحق بإذنه».", "الهداية بيد الله، فليطلب العبد دائماً الهداية من الله بسؤاله المتكرر أن يهديه دائماً إلى الحق."], "k": "هل أطلب الهداية بصدق في «اهدنا الصراط المستقيم»، وأنا أُقبل على الحق إذا خالف رأيي؟"}, {"lbl": "الآية ٢١٤", "q": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ ﴿٢١٤﴾", "w": [["أم حسبتم", "أظننتم؟ والاستفهام إنكاري، ينكر عليهم ظنهم هذا لأنه غير واقع موقعه."], ["مثل", "صفة وحال الذين من قبلكم."], ["البأساء والضراء", "البأساء الشدة من الحاجة وغيرها، والضراء المرض والجراحات والقتل."], ["زلزلوا", "اضطربوا وقلقوا من الأهوال."], ["متى نصر الله", "الاستفهام للاستبطاء."]], "m": "ينكر الله على المؤمنين وهم في أيام شدة ولأواء ظنهم أنهم يدخلون الجنة بدون امتحان وابتلاء في النفس والمال، بل يصيبهم ما أصاب غيرهم من البأساء والضراء والزلزال، وهو الاضطراب والقلق من الأهوال، حتى يقول الرسول والمؤمنون معه استبطاءً للنصر الذي وُعدوا به: متى نصر الله؟ فيجيبهم ربهم بقوله: ألا إن نصر الله قريب.", "h": ["الترغيب في التأسّي بالصالحين والاقتداء بهم في العمل والصبر.", "جواز الأعراض البشرية على الرسل كالقلق والاستبطاء للوعد الإلهي انتظاراً له."], "k": "ما الابتلاء الذي أمرّ به الآن؟ وهل أقول فيه «متى نصر الله» مع اليقين بأنه قريب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 30;
insert into public.tdb_cards(topic, i, body) select 30, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢١١ – ٢١٢", "q": "سَلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢١١﴾ زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٢١٢﴾", "w": [["سل", "اسأل؛ سقطت منه الهمزتان للتخفيف."], ["بني إسرائيل", "ذرية يعقوب بن إسحاق بن إبراهيم، وإسرائيل لقب يعقوب."], ["آية", "خارقة للعادة كعصا موسى تدل على أن من أعطاه الله إياها رسول حقاً؛ ومن آيات بني إسرائيل فلق البحر لهم وإنزال المنّ والسلوى عليهم في التيه."], ["نعمة الله", "ما وهبه لعبده من خير يجلب له المسرة ويدفع عنه المضرة، ونعم الله كثيرة."], ["يسخرون", "يحتقرون ويستهزئون."]], "m": "يأمر الله رسوله أن يسأل بني إسرائيل عن الآيات الكثيرة التي آتاهم الله، وكيف كفروا بها فلم تنفعهم شيئاً، والمراد تسلية النبي ﷺ من الألم النفسي الذي يصيبه من عدم إيمان أهل الكتاب والمشركين به، وفي ذلك تقريع لليهود وتأنيب على كفرهم بآيات الله وإصرارهم على عدم الدخول في الإسلام. ثم أخبر أن من يبدّل نعمة الله، وهي الإسلام، بالكفر به وبنبيه ﷺ فإن عقوبة الله تنزل به عاجلاً في الدنيا أو في الآخرة، لأن الله شديد العقاب. وأخبر في الآية الثانية أن الشيطان زيّن للذين كفروا بالله ورسوله وشرائعه الحياة الدنيا، فرغبوا فيها وعملوا لها ولم يروا غيرها، ولذلك سخروا من المؤمنين الزاهدين فيها لعلمهم بزوالها وقلة نفعها، فلم يكرّسوا كل جهدهم لجمعها بل أقبلوا على طاعة ربهم وأنفقوا ما في أيديهم في سبيل الله. وأخبر أن المؤمنين المتقين سيجازيهم يوم القيامة خير الجزاء وأوفره، ويخزي أعداءهم الساخرين منهم، والله يرزق من يشاء بغير حساب لواسع فضله.", "h": ["التحذير من كفر النعم لما يترتب عليه من أليم العذاب، ومن أجلّ النعم نعمة الإسلام، فمن كفر بها وأعرض عنها تعرّض لأشد العقوبات. وما حلّ ببني إسرائيل من ألوان الهوان دهراً طويلاً شاهد، وكذلك ما حلّ بالمسلمين يوم أعرضوا عن الإسلام واستبدلوا به الخرافات ثم القوانين الوضعية.", "التحذير من زينة الحياة الدنيا والرغبة فيها والجمع لها ونسيان الدار الآخرة وترك العمل لها؛ فأبناء الدنيا اليوم يسخرون من أبناء الآخرة، لكن أبناء الآخرة أهل الإيمان والتقوى سيكونون يوم القيامة فوقهم درجات."], "k": "هل أخجل أحياناً من التزامي بدين الله أمام من يسخر منه؟ وماذا يقول لي هذا الخجل؟"}, {"lbl": "الآية ٢١٣", "q": "كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ ﴿٢١٣﴾", "w": [["الناس أمة واحدة", "كانوا قبل وجود الشرك فيهم أمة واحدة على الإسلام والتوحيد، وذلك قبل قوم نوح."], ["النبيون", "جمع نبي، والمراد بهم الرسل، لأن رسالتهم قائمة على البشارة والنذارة المستمدة من كتب الله."], ["الكتاب", "اسم جنس يدخل فيه كل الكتب الإلهية."], ["أوتوه", "أُعطوه."], ["البينات", "الحجج والبراهين التي تحملها الرسل إليهم، وتورثها فيهم شرائع وأحكاماً وهدايات عامة."], ["بغياً", "البغي الظلم والحسد."], ["الصراط المستقيم", "الإسلام المفضي بصاحبه إلى السعادة والكمال في الحياتين."]], "m": "يخبر الله أن الناس كانوا بين آدم ونوح عليهما السلام أمة واحدة على الإسلام، حتى زيّن الشيطان لبعضهم عبادة غير الله، فبعث الله نوحاً فاختلفوا إلى مؤمن وكافر. وتوالت الرسل بكتب الله فيها الحكم الفصل فيما يختلفون فيه. ثم بيّن سنته أن الذين يختلفون في الكتاب هم الذين أُوتوه وجاءتهم البينات، فيحملهم الحسد وحب الرئاسة والإبقاء على مصالحهم على رفض ما فيه، واليهود مثل لذلك. وهدى الله أمة محمد ﷺ لما اختلف فيه أهل الكتابين من الحق بإذنه: كالإيمان بعيسى عبد الله ورسوله بلا غلو ولا جحود، ويوم الجمعة وقد أخذ اليهود السبت والنصارى الأحد، والقبلة قبلة إبراهيم عليه السلام. والله يهدي من يشاء إلى صراط مستقيم.", "h": ["الأصل هو التوحيد، والشرك طارئ على البشرية.", "الأصل في مهمة الرسل البشارة لمن آمن واتقى والنذارة لمن كفر وفجر.", "من علامات خذلان الأمة وتعرضها للخسار والدمار أن تختلف في كتابها ودينها، فيحرّفوا كلام الله ويبدلوا شرائعه طلباً للرئاسة وجرياً وراء الأهواء والعصبيات، وكان ذلك سبب دمار بني إسرائيل.", "أمة الإسلام التي تعيش على الكتاب والسنة عقيدة وعبادة وقضاء هي المعنية بقوله: «فهدى الله الذين آمنوا لما اختلفوا فيه من الحق بإذنه».", "الهداية بيد الله، فليطلب العبد دائماً الهداية من الله بسؤاله المتكرر أن يهديه دائماً إلى الحق."], "k": "هل أطلب الهداية بصدق في «اهدنا الصراط المستقيم»، وأنا أُقبل على الحق إذا خالف رأيي؟"}, {"lbl": "الآية ٢١٤", "q": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ ﴿٢١٤﴾", "w": [["أم حسبتم", "أظننتم؟ والاستفهام إنكاري، ينكر عليهم ظنهم هذا لأنه غير واقع موقعه."], ["مثل", "صفة وحال الذين من قبلكم."], ["البأساء والضراء", "البأساء الشدة من الحاجة وغيرها، والضراء المرض والجراحات والقتل."], ["زلزلوا", "اضطربوا وقلقوا من الأهوال."], ["متى نصر الله", "الاستفهام للاستبطاء."]], "m": "ينكر الله على المؤمنين وهم في أيام شدة ولأواء ظنهم أنهم يدخلون الجنة بدون امتحان وابتلاء في النفس والمال، بل يصيبهم ما أصاب غيرهم من البأساء والضراء والزلزال، وهو الاضطراب والقلق من الأهوال، حتى يقول الرسول والمؤمنون معه استبطاءً للنصر الذي وُعدوا به: متى نصر الله؟ فيجيبهم ربهم بقوله: ألا إن نصر الله قريب.", "h": ["الترغيب في التأسّي بالصالحين والاقتداء بهم في العمل والصبر.", "جواز الأعراض البشرية على الرسل كالقلق والاستبطاء للوعد الإلهي انتظاراً له."], "k": "ما الابتلاء الذي أمرّ به الآن؟ وهل أقول فيه «متى نصر الله» مع اليقين بأنه قريب؟"}]$j$::jsonb) with ordinality x(e, i);

-- 31. سورة البقرة ٢١٥ – ٢١٨ · الإنفاق والقتال في الشهر الحرام
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (31, 2, 215, 218, 'سورة البقرة ٢١٥ – ٢١٨', 'الإنفاق والقتال في الشهر الحرام', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 31) = $j$[{"lbl": "الآية ٢١٥", "q": "يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ ﴿٢١٥﴾", "w": [["الأقربين", "كالإخوة والأخوات وأولادهم، والأعمام والعمات وأولادهم، والأخوال والخالات وأولادهم."], ["وما تفعلوا من خير", "«ما» شرطية و«من» بيانية، والخير هنا لسائر أنواع البر والإحسان."], ["فإن الله به عليم", "جملة هي علة لجواب الشرط المحذوف المقدّر: يثبكم عليه."]], "m": "سأل عمرو بن الجموح، وكان ذا مال، رسول الله ﷺ: ماذا ينفق وعلى من ينفق؟ فنزلت الآية جواباً لسؤاله، فبيّنت أن ما يُنفَق هو المال وسائر الخيرات، وأن الأحق بالإنفاق عليهم هم الوالدان والأقربون واليتامى والمساكين وابن السبيل. وأعلمهم الله أن ما يفعله العبد من خير يعلمه الله ويجزي به، فرغّب بذلك في فعل الخير مطلقاً.", "h": ["سؤال من لا يعلم حتى يعلم، وهذا طريق العلم؛ ولذا قالوا: السؤال نصف العلم.", "أفضلية الإنفاق على المذكورين في الآية إن كان المنفق غنياً وهم فقراء محتاجون.", "الترغيب في فعل الخير والوعد من الله بالجزاء الأوفى عليه."], "k": "هل يصل إنفاقي أولاً إلى من هم أقرب إليّ ممن يحتاج؟"}, {"lbl": "الآية ٢١٦", "q": "كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٢١٦﴾", "w": [["كُتب", "فُرض فرضاً مؤكداً حتى كأنه مكتوب."], ["القتال", "قتال الكافرين بجهادهم حتى يسلموا أو يعطوا الجزية."], ["كُره", "مكروه في نفوسكم طبعاً."], ["عسى", "معناها الترجّي والتوقع، إلا أنها إن كانت من الله تفيد اليقين."]], "m": "يخبر الله رسوله وعباده المؤمنين بأنه فرض عليهم قتال المشركين والكافرين، وهو يعلم أنه مكروه لهم بطبعهم لما فيه من الآلام والأتعاب وإضاعة المال والنفس. وأخبرهم أن ما يكرهونه قد يكون خيراً لهم وأن ما يحبونه قد يكون شراً لهم، ومن ذلك الجهاد، فإنه مكروه لهم وهو خير لهم لما فيه من عزتهم ونصرتهم ونصرة دينهم مع حسن الثواب وعظم الجزاء في الآخرة، كما أن ترك الجهاد محبوب لهم وهو شر لهم لأنه يشجّع عدوهم على قتالهم واستباحة بيضتهم وانتهاك حرمات دينهم مع سوء الجزاء في الآخرة. والله يعلم وهم لا يعلمون، فيجب التسليم لله في أمره وشرعه مع حب ما أمر به واعتقاد أنه خير لا شر فيه.", "h": ["وجوب الجهاد على أمة الإسلام ما بقيت فتنة في الأرض وشرك فيها.", "ابتلاء الإنسان بالعواقب بجعله يحب المكروه ويكره المحبوب.", "أوامر الله كلها خير ونواهيه كلها شر، فلذا يجب فعل أوامره واجتناب نواهيه."], "k": "ما الأمر الذي أكرهه الآن وقد يكون فيه خير لي لا أراه بعد؟"}, {"lbl": "الآيتان ٢١٧ – ٢١٨", "q": "يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢١٧﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَـٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢١٨﴾", "w": [["الصد عن سبيل الله", "صرف الناس عن دين الله."], ["المسجد الحرام", "مكة والمسجد الحرام فيها، وأهله النبي ﷺ والمهاجرون."], ["أكبر", "أعظم وزراً."], ["الفتنة", "الشرك واضطهاد المؤمنين ليكفروا."], ["حبطت أعمالهم", "بطل أجرها فلا يثابون عليها بسبب ردتهم."], ["هاجروا", "تركوا ديارهم خوف الفتنة والاضطهاد في ذات الله."]], "m": "لما فرض الله القتال أرسل النبي ﷺ سرية بقيادة عبد الله بن جحش إلى بطن نخلة، فلقوا عيراً لقريش فقاتلوهم وقتلوا عمرو بن الحضرمي وأسروا اثنين، وكان ذلك آخر يوم من جمادى الآخرة وأول ليلة من رجب. فشنّعت قريش أن محمداً أحلّ الشهر الحرام بالقتال، فنزلت الآية: القتال في الشهر الحرام وزر كبير، لكن الصد عن دين الله والكفر به والصد عن المسجد الحرام وإخراج أهله منه أعظم عند الله، وفتنة المؤمنين لردّهم عن دينهم أعظم من القتل. وأعلم أن الكافرين لا يزالون يقاتلونهم حتى يردوهم عن دينهم إن استطاعوا، وحذّر المرتد الذي يموت كافراً أن أعماله تبطل وهو من أهل النار خالداً. وفي الآية الثانية طمأن عبد الله بن جحش وأصحابه أنهم لا إثم عليهم، وأنهم يرجون رحمة الله لإيمانهم وهجرتهم وجهادهم.", "h": ["حرمة الشهر الحرام والبلد الحرام.", "نسخ القتال في الشهر الحرام بدليل قتال الرسول ﷺ هوازن وثقيفاً في شوال وأول القعدة، وهما من الأشهر الحرم.", "الكشف عن نفسية الكافرين وهي عزمهم الدائم على قتال المسلمين إلى أن يردّوهم عن الإسلام ويخرجوهم منه.", "الردة محبطة للعمل؛ فإن تاب المرتد استأنف العمل من جديد، وإن مات قبل التوبة فهو من أهل النار الخالدين فيها أبداً.", "بيان فضل الإيمان والهجرة والجهاد في سبيل الله."], "k": "ما الذي أُعرّض له دِيني للإيذاء بالكلام أو بالفعل، وكيف أثبت عليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 31;
