insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (32, 2, 219, 223, 'سورة البقرة ٢١٩ – ٢٢٣', 'الخمر والميسر وأحكام النكاح', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 32) = $j$[{"lbl": "الآيتان ٢١٩ – ٢٢٠", "q": "۞يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ﴿٢١٩﴾ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٢٠﴾", "w": [["الخمر", "كل ما خامر العقل وغطّاه فأصبح شاربه لا يميّز ولا يعقل، ويُطلق على عصير العنب أو التمر أو الشعير وغيرها."], ["الميسر", "القمار، وسُمّي ميسراً لأن صاحبه ينال المال بيسر وسهولة."], ["الإثم", "كل ضار فاسد يضر بالنفس أو العقل أو البدن أو المال أو العرض."], ["المنافع", "جمع منفعة، وهي ما يسر ولا يضر من الأقوال والأفعال والمواد."], ["العفو", "ما فضل وزاد عن حاجة الإنسان من المال."], ["تتفكرون", "فتعرفون ما ينفع في كل منهما، فتعملون لدنياكم ما يصلحها ولآخرتكم ما يسعدكم فيها."], ["تخالطوهم", "تخلطون مالهم بمالكم ليكون سواء."], ["لأعنتكم", "العنت المشقة الشديدة، أي: لكلّفكم ما فيه مشقة شديدة."]], "m": "كان العرب في الجاهلية يشربون الخمر ويقامرون. ولما هاجر النبي ﷺ وأخذت الأحكام تنزل شيئاً فشيئاً، صلى بعض الصحابة بجماعة وهو ثمل فخلط في القراءة فنزل: لا تقربوا الصلاة وأنتم سكارى. ثم كثرت الأسئلة فنزلت: يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما. فترك كثير منهم الشرب واللعب، وكان عمر يتطلع إلى منعهم منعاً باتاً ويقول: اللهم بيّن لنا في الخمر بياناً شافياً، فنزلت آية المائدة وحُرّمتا تحريماً قاطعاً. وإثمهما في المائدة: أنهما يوقعان العداوة والبغضاء ويصدّان عن ذكر الله وعن الصلاة. وأما سؤالهم عما ينفقون فجوابه: العفو، أي ما فضل عن حاجتكم، لقوله ﷺ: «خير الصدقة ما كان عن ظهر غنى». وأما اليتامى فلما خاف المؤمنون من وعيد أكل مال اليتيم فصلوا طعامهم عن طعامه، فشقّ عليهم، بيّن الله أن المقصود إصلاح مال اليتيم: وإن تخالطوهم فإخوانكم، والله يعلم المفسد من المصلح.", "h": ["تحريم الخمر والميسر، حيث نُسخت هذه الآية بآية المائدة لقوله فيها: «فاجتنبوه» وقوله: «فهل أنتم منتهون».", "بيان أفضل صدقة في الآية: ما كان عن ظهر غنى.", "استحباب التفكر في أمر الدنيا والآخرة لإعطاء الأولى بقدر فنائها والآخرة بحسب بقائها.", "جواز خلط مال اليتيم بمال كافله إذا كان أربح له وأوفر، وهو معنى الإصلاح في الآية.", "حرمة مال اليتيم والتحذير من المساس به وخلطه إذا كان يسبب نقصاً فيه أو إفساداً."], "k": "هل أنفق مما يفيض عن حاجتي فقط، أم أحتفظ لنفسي بكل شيء ثم أتصدّق بما بقي؟"}, {"lbl": "الآية ٢٢١", "q": "وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَـٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٢١﴾", "w": [["ولا تنكحوا", "لا تتزوجوا."], ["الأمة", "خلاف الحرة."], ["ولو أعجبتكم", "أي: أعجبكم حسنها وجمالها."], ["يدعون إلى النار", "بحالهم ومقالهم وأفعالهم."], ["آياته", "أحكام دينه ومسائل شرعه."]], "m": "ينهى الله المؤمنين أن يتزوجوا المشركات إلا أن يؤمنّ بالله ورسوله، فإن آمنّ جاز نكاحهن. وأعلمهم منفّراً من نكاح المشركات مرغّباً في نكاح المؤمنات: ولأمة مؤمنة خير من مشركة ولو أعجبتكم لحسنها وجمالها. كما نهاهم عن أن يزوّجوا المؤمنات بالمشركين حتى يؤمنوا، فإن آمنوا جاز لهم أن ينكحوهم، فقال: ولا تنكحوا المشركين حتى يؤمنوا. وقال منفّراً مرغّباً: ولعبد مؤمن خير من مشرك ولو أعجبكم المشرك لشرفه أو ماله أو سلطانه. وعلّل لذلك بقوله: أولئك يدعون إلى النار، فمخالطتهم مضرة ومفسدة لا سيما بالتزوج منهم، والله يدعو إلى الجنة بالإيمان والعمل الصالح، وإلى المغفرة بالتوبة الصادقة، فاستجيبوا له. كما أنه يبيّن آياته للناس ليعدّهم للتذكر والاتعاظ فيقبلوا على طاعته الموصلة إلى رضاه والجنة.", "h": ["حرمة نكاح المشركات. أما الكتابيات فقد أباحهن الله بآية المائدة إذ قال: «والمحصنات من الذين أوتوا الكتاب من قبلكم».", "حرمة نكاح المؤمنة الكافر مطلقاً، مشركاً كان أو كتابياً.", "شرط الولاية في نكاح المرأة لقوله: «ولا تنكحوا المشركين»، فهو هنا يخاطب أولياء النساء المؤمنات؛ ولذا لا يصح نكاح إلا بولي.", "التنفير من مخالطة المشركين والترغيب في البعد عنهم لأنهم يدعون إلى الكفر بحالهم ومقالهم وأعمالهم.", "وجوب موالاة أهل الإيمان ومعاداة أهل الكفر والضلال، لأن الأولين يدعون إلى الجنة والآخرين يدعون إلى النار."], "k": "من أصحاب من يدعونني إلى الجنة بحالهم قبل مقالهم؟ وهل أُحسن اختيار من أخالطهم؟"}, {"lbl": "الآيتان ٢٢٢ – ٢٢٣", "q": "وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّـٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ ﴿٢٢٢﴾ نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿٢٢٣﴾", "w": [["المحيض", "مكان الحيض وزمنه، والحيض دم يخرج من رحم المرأة إذا خلا من الحمل."], ["أذى", "ضرر يضر المجامع في أيامه."], ["فاعتزلوا النساء في المحيض", "يريد في الجماع فقط لا في المعاشرة والمؤاكلة والمشاربة."], ["يطهرن", "ينقطع دمهن، ثم يغتسلن لقوله: فإذا تطهرن."], ["التوابين", "المقلعين عن الذنوب."], ["المتطهرين", "المتطهرين من النجاسات والأقذار."], ["نساؤكم حرث لكم", "يريد موضع إنجاب الأولاد، شبّه النساء بالحرث لأن الأرض إذا حُرثت أنبتت الزرع والمرأة إذا وُطئت أنبتت الولد بإذن الله."], ["وقدموا لأنفسكم", "يريد الأعمال الصالحة، ومنها إرادة تحصين النفس والزوجة بالجماع وإنجاب الأولاد الصالحين الذين يوحدون الله."]], "m": "يخبر الله أن بعض المؤمنين سألوا النبي ﷺ عن المحيض: هل تُساكَن المرأة وتؤاكَل أم تُهجر حتى تطهر، وكان هذا من عادة أهل الجاهلية؟ فأمره أن يقول لهم: الحيض أذى، فاعتزلوا النساء في المحيض في الجماع فقط، لا في المعاشرة والمؤاكلة والمشاربة، ولا تقربوهن حتى يطهرن بانقطاع الدم والاغتسال، فإذا تطهرن فأتوهن من حيث أمركم الله، وهو القُبُل لا الدُّبُر فإنه محرّم. وأعلمهم أنه يحب التوابين من الذنوب المتطهرين من النجاسات. وفي الآية الثانية: نساؤكم حرث لكم، أي موضع إنجاب الأولاد، فلا مانع من إتيانها مقبلة أو مدبرة إذا كان في القُبُل وكانت طاهرة من الحيض والنفاس. ثم وعظهم: وقدموا لأنفسكم من الخير واعلموا أنكم ملاقوه، وبشّر المؤمنين.", "h": ["حرمة الجماع أثناء الحيض والنفاس لما فيه من الضرر.", "حرمة وطء المرأة إذا انقطع دم حيضها أو نفاسها ولم تغتسل، لقوله: «فإذا تطهرن فأتوهن».", "حرمة نكاح المرأة في دبرها لقوله: «فأتوهن من حيث أمركم الله»، وهو القُبُل.", "وجوب التطهير من الذنوب بالتوبة، والتطهير من الأقذار والنجاسات بالماء.", "وجوب تقديم ما أمكن من العمل الصالح ليكون زاد المسلم إلى الدار الآخرة لقوله: «وقدموا لأنفسكم».", "وجوب تقوى الله بفعل ما أمر وترك ما نهى عنه وزجر."], "k": "ما العمل الصالح الذي أقدّمه اليوم لنفسي، ولو كان صغيراً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 32;
insert into public.tdb_cards(topic, i, body) select 32, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢١٩ – ٢٢٠", "q": "۞يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ﴿٢١٩﴾ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٢٠﴾", "w": [["الخمر", "كل ما خامر العقل وغطّاه فأصبح شاربه لا يميّز ولا يعقل، ويُطلق على عصير العنب أو التمر أو الشعير وغيرها."], ["الميسر", "القمار، وسُمّي ميسراً لأن صاحبه ينال المال بيسر وسهولة."], ["الإثم", "كل ضار فاسد يضر بالنفس أو العقل أو البدن أو المال أو العرض."], ["المنافع", "جمع منفعة، وهي ما يسر ولا يضر من الأقوال والأفعال والمواد."], ["العفو", "ما فضل وزاد عن حاجة الإنسان من المال."], ["تتفكرون", "فتعرفون ما ينفع في كل منهما، فتعملون لدنياكم ما يصلحها ولآخرتكم ما يسعدكم فيها."], ["تخالطوهم", "تخلطون مالهم بمالكم ليكون سواء."], ["لأعنتكم", "العنت المشقة الشديدة، أي: لكلّفكم ما فيه مشقة شديدة."]], "m": "كان العرب في الجاهلية يشربون الخمر ويقامرون. ولما هاجر النبي ﷺ وأخذت الأحكام تنزل شيئاً فشيئاً، صلى بعض الصحابة بجماعة وهو ثمل فخلط في القراءة فنزل: لا تقربوا الصلاة وأنتم سكارى. ثم كثرت الأسئلة فنزلت: يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما. فترك كثير منهم الشرب واللعب، وكان عمر يتطلع إلى منعهم منعاً باتاً ويقول: اللهم بيّن لنا في الخمر بياناً شافياً، فنزلت آية المائدة وحُرّمتا تحريماً قاطعاً. وإثمهما في المائدة: أنهما يوقعان العداوة والبغضاء ويصدّان عن ذكر الله وعن الصلاة. وأما سؤالهم عما ينفقون فجوابه: العفو، أي ما فضل عن حاجتكم، لقوله ﷺ: «خير الصدقة ما كان عن ظهر غنى». وأما اليتامى فلما خاف المؤمنون من وعيد أكل مال اليتيم فصلوا طعامهم عن طعامه، فشقّ عليهم، بيّن الله أن المقصود إصلاح مال اليتيم: وإن تخالطوهم فإخوانكم، والله يعلم المفسد من المصلح.", "h": ["تحريم الخمر والميسر، حيث نُسخت هذه الآية بآية المائدة لقوله فيها: «فاجتنبوه» وقوله: «فهل أنتم منتهون».", "بيان أفضل صدقة في الآية: ما كان عن ظهر غنى.", "استحباب التفكر في أمر الدنيا والآخرة لإعطاء الأولى بقدر فنائها والآخرة بحسب بقائها.", "جواز خلط مال اليتيم بمال كافله إذا كان أربح له وأوفر، وهو معنى الإصلاح في الآية.", "حرمة مال اليتيم والتحذير من المساس به وخلطه إذا كان يسبب نقصاً فيه أو إفساداً."], "k": "هل أنفق مما يفيض عن حاجتي فقط، أم أحتفظ لنفسي بكل شيء ثم أتصدّق بما بقي؟"}, {"lbl": "الآية ٢٢١", "q": "وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَـٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٢١﴾", "w": [["ولا تنكحوا", "لا تتزوجوا."], ["الأمة", "خلاف الحرة."], ["ولو أعجبتكم", "أي: أعجبكم حسنها وجمالها."], ["يدعون إلى النار", "بحالهم ومقالهم وأفعالهم."], ["آياته", "أحكام دينه ومسائل شرعه."]], "m": "ينهى الله المؤمنين أن يتزوجوا المشركات إلا أن يؤمنّ بالله ورسوله، فإن آمنّ جاز نكاحهن. وأعلمهم منفّراً من نكاح المشركات مرغّباً في نكاح المؤمنات: ولأمة مؤمنة خير من مشركة ولو أعجبتكم لحسنها وجمالها. كما نهاهم عن أن يزوّجوا المؤمنات بالمشركين حتى يؤمنوا، فإن آمنوا جاز لهم أن ينكحوهم، فقال: ولا تنكحوا المشركين حتى يؤمنوا. وقال منفّراً مرغّباً: ولعبد مؤمن خير من مشرك ولو أعجبكم المشرك لشرفه أو ماله أو سلطانه. وعلّل لذلك بقوله: أولئك يدعون إلى النار، فمخالطتهم مضرة ومفسدة لا سيما بالتزوج منهم، والله يدعو إلى الجنة بالإيمان والعمل الصالح، وإلى المغفرة بالتوبة الصادقة، فاستجيبوا له. كما أنه يبيّن آياته للناس ليعدّهم للتذكر والاتعاظ فيقبلوا على طاعته الموصلة إلى رضاه والجنة.", "h": ["حرمة نكاح المشركات. أما الكتابيات فقد أباحهن الله بآية المائدة إذ قال: «والمحصنات من الذين أوتوا الكتاب من قبلكم».", "حرمة نكاح المؤمنة الكافر مطلقاً، مشركاً كان أو كتابياً.", "شرط الولاية في نكاح المرأة لقوله: «ولا تنكحوا المشركين»، فهو هنا يخاطب أولياء النساء المؤمنات؛ ولذا لا يصح نكاح إلا بولي.", "التنفير من مخالطة المشركين والترغيب في البعد عنهم لأنهم يدعون إلى الكفر بحالهم ومقالهم وأعمالهم.", "وجوب موالاة أهل الإيمان ومعاداة أهل الكفر والضلال، لأن الأولين يدعون إلى الجنة والآخرين يدعون إلى النار."], "k": "من أصحاب من يدعونني إلى الجنة بحالهم قبل مقالهم؟ وهل أُحسن اختيار من أخالطهم؟"}, {"lbl": "الآيتان ٢٢٢ – ٢٢٣", "q": "وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّـٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ ﴿٢٢٢﴾ نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ ﴿٢٢٣﴾", "w": [["المحيض", "مكان الحيض وزمنه، والحيض دم يخرج من رحم المرأة إذا خلا من الحمل."], ["أذى", "ضرر يضر المجامع في أيامه."], ["فاعتزلوا النساء في المحيض", "يريد في الجماع فقط لا في المعاشرة والمؤاكلة والمشاربة."], ["يطهرن", "ينقطع دمهن، ثم يغتسلن لقوله: فإذا تطهرن."], ["التوابين", "المقلعين عن الذنوب."], ["المتطهرين", "المتطهرين من النجاسات والأقذار."], ["نساؤكم حرث لكم", "يريد موضع إنجاب الأولاد، شبّه النساء بالحرث لأن الأرض إذا حُرثت أنبتت الزرع والمرأة إذا وُطئت أنبتت الولد بإذن الله."], ["وقدموا لأنفسكم", "يريد الأعمال الصالحة، ومنها إرادة تحصين النفس والزوجة بالجماع وإنجاب الأولاد الصالحين الذين يوحدون الله."]], "m": "يخبر الله أن بعض المؤمنين سألوا النبي ﷺ عن المحيض: هل تُساكَن المرأة وتؤاكَل أم تُهجر حتى تطهر، وكان هذا من عادة أهل الجاهلية؟ فأمره أن يقول لهم: الحيض أذى، فاعتزلوا النساء في المحيض في الجماع فقط، لا في المعاشرة والمؤاكلة والمشاربة، ولا تقربوهن حتى يطهرن بانقطاع الدم والاغتسال، فإذا تطهرن فأتوهن من حيث أمركم الله، وهو القُبُل لا الدُّبُر فإنه محرّم. وأعلمهم أنه يحب التوابين من الذنوب المتطهرين من النجاسات. وفي الآية الثانية: نساؤكم حرث لكم، أي موضع إنجاب الأولاد، فلا مانع من إتيانها مقبلة أو مدبرة إذا كان في القُبُل وكانت طاهرة من الحيض والنفاس. ثم وعظهم: وقدموا لأنفسكم من الخير واعلموا أنكم ملاقوه، وبشّر المؤمنين.", "h": ["حرمة الجماع أثناء الحيض والنفاس لما فيه من الضرر.", "حرمة وطء المرأة إذا انقطع دم حيضها أو نفاسها ولم تغتسل، لقوله: «فإذا تطهرن فأتوهن».", "حرمة نكاح المرأة في دبرها لقوله: «فأتوهن من حيث أمركم الله»، وهو القُبُل.", "وجوب التطهير من الذنوب بالتوبة، والتطهير من الأقذار والنجاسات بالماء.", "وجوب تقديم ما أمكن من العمل الصالح ليكون زاد المسلم إلى الدار الآخرة لقوله: «وقدموا لأنفسكم».", "وجوب تقوى الله بفعل ما أمر وترك ما نهى عنه وزجر."], "k": "ما العمل الصالح الذي أقدّمه اليوم لنفسي، ولو كان صغيراً؟"}]$j$::jsonb) with ordinality x(e, i);

-- 33. سورة البقرة ٢٢٤ – ٢٣٢ · الإيلاء والطلاق
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (33, 2, 224, 232, 'سورة البقرة ٢٢٤ – ٢٣٢', 'الإيلاء والطلاق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 33) = $j$[{"lbl": "الآيات ٢٢٤ – ٢٢٧", "q": "وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٢٢٤﴾ لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ﴿٢٢٥﴾ لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٢٢٦﴾ وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٢٢٧﴾", "w": [["عُرضة", "ما يوضع مانعاً من شيء؛ والمراد اليمين يحلفها المؤمن ألا يفعل خيراً."], ["الأيمان", "جمع يمين، نحو: والله لا أفعل كذا، أو والله لأفعلنّ كذا."], ["البر", "الطاعة وفعل الخير."], ["اللغو", "الباطل وما لا خير فيه؛ ولغو اليمين أن يحلف العبد على الشيء يظنه كذا فيتبين خلافه، أو ما يجري على لسانه من أيمان من غير إرادة الحلف."], ["كسبت قلوبكم", "ما تعمّد القلب وقصد اليمين لأجله، لفعله حتماً أو منعه."], ["يؤلون", "الإيلاء الحلف على عدم وطء الزوجة."], ["التربص", "الانتظار والتمهل."], ["فاءوا", "رجعوا إلى وطء نسائهم بعد الامتناع عنه باليمين."], ["الطلاق", "فك رابطة الزوجية وحلّها بقوله: هي طالق أو مطلقة أو طلقتك."]], "m": "ينهى الله أن يجعل المؤمن الحلف به مانعاً من فعل الخير، كأن يحلف ألا يتصدق أو لا يصلح بين اثنين: ولا تجعلوا الله عرضة لأيمانكم أن تبروا وتتقوا وتصلحوا بين الناس. ثم أخبر أنه لا يؤاخذ باللغو في الأيمان، وهو أن يحلف على الشيء يظنه كذا فيظهر خلافه، أو أن يجري على لسانه ما لا يقصده كقوله: لا والله وبلى والله، لكن يؤاخذ بما كسبت القلوب، كمن يحلف كاذباً ليأخذ حق أخيه، وهي اليمين الغموس، وعلى صاحبها التوبة وردّ الحق. وبمناسبة اليمين ذكر حكم الإيلاء، وهو أن يحلف الرجل ألا يطأ امرأته: فله تربص أربعة أشهر، فإن فاء وكفّر عن يمينه فالله غفور رحيم، وإن أصرّ وعزم الطلاق أوقفه القاضي ليفيء أو يطلّق، والله سميع عليم.", "h": ["كراهية منع الخير بسبب اليمين، فمن حلف ألا يفعل خيراً فليكفّر عن يمينه وليفعل الخير، لحديث: «من حلف على يمين فرأى غيرها خيراً منها فليكفّر عن يمينه وليأتِ الذي هو خير».", "لغو اليمين معفو عنها، ولها صورتان: أن يجري على لسانه لفظ اليمين وهو لا يريد الحلف نحو: لا والله وبلى والله؛ أو أن يحلف على شيء يظنه كذا فيتبين خلافه.", "اليمين المؤاخَذ عليها العبد هي أن يحلف متعمداً الكذب لتحصيل منفعة دنيوية، وهي اليمين الغموس.", "اليمين التي تجب فيها الكفارة هي أن يحلف العبد على أن يفعل كذا فيعجز، أو ألا يفعل كذا ثم يضطر فيفعل، ولم يقل أثناء الحلف: إن شاء الله. والكفارة مبينة في آية المائدة: إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فإن لم يجد صام ثلاثة أيام.", "حكم الإيلاء: إن كانت مدته أقل من أربعة أشهر فله أن يستمر إلى انتهاء المدة، والأفضل أن يطأ ويكفّر؛ وإن كانت أكثر من أربعة أشهر فعليه أن يفيء إلى زوجته أو تُطلّق عليه."], "k": "هل لساني يسبق قلبي في الحلف؟ وهل أحلف ثم أترك الخير بسبب يميني؟"}, {"lbl": "الآية ٢٢٨", "q": "وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ ﴿٢٢٨﴾", "w": [["المطلقات", "جمع مطلقة، وهي المرأة تسوء عشرتها فيطلقها زوجها أو القاضي."], ["يتربصن", "ينتظرن."], ["قروء", "القرء إما مدة الطهر أو مدة الحيض."], ["ما خلق الله في أرحامهن", "من الأجنة، فلا يحل للمطلقة أن تكتم ذلك."], ["بعولتهن", "أزواجهن، واحدهم بَعْل."], ["أحق بردهن", "في مدة التربص والانتظار."], ["ولهن مثل الذي عليهن", "على الزوجة حقوق لزوجها ولها حقوق على زوجها."], ["درجة", "درجة القوامة، فالرجل شرعاً هو القيّم على المرأة."]], "m": "في هذه الآية أن على المطلقة التي تحيض أن تنتظر ثلاثة قروء قبل أن تتزوج، وتسمى هذه المدة عدة، وهي واجبة لحق زوجها إذ له أن يراجعها فيها: وبعولتهن أحق بردهن في ذلك إن أرادوا إصلاحاً. وعليها ألا تكتم ما خلق الله في رحمها من حيض أو حمل، فهذا من كبائر الذنوب، لأنها قد تدّعي ما يخالف الحقيقة طلباً للرجعة أو منعاً لها، أو تنسب إلى زوج آخر ولداً ليس منه. وللزوج أن يراجعها ما دامت في العدة بشرط ألا يريد المضارة بل الإصلاح وطيب العشرة، وعليها أن تنوي ذلك أيضاً. ثم قرر أن للزوجة من الحقوق مثل ما عليها بالمعروف، وللرجل عليها درجة هي القوامة المفهومة من آية النساء: الرجال قوامون على النساء. وختمت بقوله: والله عزيز حكيم، إشعاراً بوجوب تنفيذ هذه التعاليم.", "h": ["بيان عدة المطلقة إذا كانت تحيض، وهو التربص ثلاثة حيض أو أطهار.", "حرمة كتمان المطلقة حيضاً أو حملاً خلقه الله في رحمها، ولأي غرض كان.", "أحقية الزوج بالرجعة من مطلقته ما لم تنقضِ عدتها، حتى قيل: الرجعية زوجة، بدليل أنها لو ماتت يرثها زوجها ولو مات ترثه؛ وأنه لا يحل أن تُخطب أو تتزوج ما دامت في عدتها.", "إثبات حقوق كل من الزوجين على صاحبه.", "تقرير سيادة الرجل على المرأة لما وهبه الله من ميزات الرجولة."], "k": "هل أؤدي ما عليّ من حقوق في بيتي قبل أن أطالب بما لي؟"}, {"lbl": "الآية ٢٢٩", "q": "ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٢٩﴾", "w": [["الطلاق", "الاسم من طلّق، وهو أن يقول الرجل لزوجته: أنت طالق أو طلقتك."], ["مرتان", "يملك الزوج الإرجاع في طلقتين، أما إن طلّق الثالثة فلا يملك ذلك ولا ترجع إليه حتى تنكح زوجاً غيره."], ["فإن خفتم ألا يقيما حدود الله", "حسن العشرة؛ فإن خافت المرأة أو خاف الزوج ألا يؤدي حقوق الزوجية جاز الفداء، وهو دفع مال للزوج ليخلّي سبيل المرأة، ويسمى هذا خلعاً."], ["حدود الله", "ما يجب أن ينتهي إليه العبد من طاعة الله ولا يتجاوزه."], ["الظالم", "المتجاوز لما حدّ الله، والظلم وضع الشيء في غير موضعه."]], "m": "ما زال السياق في بيان أحكام الطلاق، فيقرر الله في هذه الآية أن الطلاق الذي يملك الزوج الرجعة فيه طلقتان: أولى وثانية فقط. ومن هنا فمن طلّق الثانية فهو بين خيارين: إما أن يمسك زوجته بمعروف، أي بحسن العشرة وأداء ما للزوجة من حقوق، أو يسرّح، أي يطلّق بإحسان، بأن يعطيها باقي صداقها إن بقي ويمتّعها بشيء من المال ولا يذكرها بسوء. وحرّم على الزوج أن يأخذ من مهر زوجته شيئاً بدون رضاها، إلا في حال واحدة، وهي إذا كرهت المرأة الزوج ولم تطق البقاء معه وهو غير ظالم لها، ففي هذه الحال يجوز أن تعطي الزوج مالاً ويطلقها، ويسمى هذا خلعاً، وهو حلال على الزوج غير الظالم. وقوله: تلك حدود الله، يريد أحكام شرعه، فلا يحل تجاوز الحلال إلى الحرام، ولا الإحسان إلى الإساءة، ولا المعروف إلى المنكر، ومن يتعدّ حدود الله فقد ظلم نفسه وعرّضها للعذاب.", "h": ["حرمة الطلاق الثلاث بلفظ واحد، لأن الله قال: «الطلاق مرتان».", "المطلقة ثلاث طلقات لا تحل لزوجها حتى تنكح زوجاً غيره ويطلقها أو يموت عنها.", "مشروعية الخلع، وهو أن تكره المرأة البقاء مع زوجها فتخلع نفسها منه بمال تعطيه إياه عوضاً عما أنفق عليها في الزواج بها.", "وجوب الوقوف عند حدود الله وحرمة تعديها.", "تحريم الظلم، وهو ثلاثة أنواع: ظلم الشرك ولا يغفر إلا بالتوبة منه، وظلم العبد لأخيه الإنسان ولا بد من التحلل منه، وظلم العبد لنفسه بتعدي حد من حدود الله وأمره إلى الله إن شاء غفره وإن شاء أخذ به."], "k": "عند الخلاف: هل أقف عند حدود الله فأصبر على الإمساك بمعروف أو أُفارق بإحسان؟"}, {"lbl": "الآية ٢٣٠", "q": "فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ ﴿٢٣٠﴾", "w": [["فإن طلقها فلا تحل له", "الطلقة الثالثة، فلا تحل له إلا بعد أن تنكح زوجاً غيره."], ["فلا جناح عليهما", "لا إثم ولا حرج عليهما في الزواج من جديد."], ["أن يتراجعا", "أن يرجع كل منهما لصاحبه بعقد جديد، بشرط أن يظنا إقامة حدود الله فيهما، وإلا فلا يجوز نكاحهما."]], "m": "يقول الله مبيّناً حكم من طلّق امرأته الطلقة الثالثة: فإن طلقها فلا تحل له من بعد حتى تنكح زوجاً غيره، ويكون النكاح صحيحاً ويبني بها الزوج الثاني، لحديث: «حتى تذوقي عسيلته ويذوق عسيلتك». فإن طلقها الثاني بعد البناء والخلوة والوطء أو مات عنها جاز لها أن تعود إلى الأول إن رغب هو في ذلك وعلما من أنفسهما أنهما يقيمان حدود الله، بإعطاء كل واحد حقوق صاحبه مع حسن العشرة، وإلا فلا مراجعة تحل لهما. ولذا قال: إن ظنّا أن يقيما حدود الله. ثم نوّه الله بشأن تلك الحدود فقال: وتلك حدود الله، وهي شرائعه.", "h": ["المطلقة ثلاثاً لا تحل لمطلقها إلا بشرطين: أن تنكح زوجاً غيره نكاحاً صحيحاً ويبني بها ويطأها، وأن يغلب على ظن كل منهما أن العشرة بينهما ستطيب وألا يتكرر الاعتداء الذي أدى إلى الطلاق ثلاث مرات.", "موت الزوج الثاني كطلاقه، تصح معه الرجعة إلى الزوج الأول بشرطه.", "إن تزوجت المطلقة ثلاثاً بنية التمرّد على الزوج حتى يطلقها لتعود إلى الأول، فلا يحلّها هذا النكاح، لأن الرسول ﷺ أبطله وقال: «لعن الله المحلِّل والمحلَّل له»."], "k": "هل أتأنّى قبل نطق ما لا رجعة فيه من كلام؟"}, {"lbl": "الآية ٢٣١", "q": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٢٣١﴾", "w": [["بلغن أجلهن", "قاربن انتهاء أيام عدتهن."], ["أو سرحوهن", "تسريح المطلقة تركها بلا مراجعة لها حتى تنقضي عدتها وتبين من زوجها."], ["ضراراً", "مضارة لها وإضراراً بها."], ["لتعتدوا", "لتتجاوزوا حد الإحسان إلى الإساءة."], ["هزواً", "لعباً بها بعدم التزامكم بتطبيق أحكامها."], ["نعمة الله", "هنا هي الإسلام."], ["الحكمة", "السنة النبوية."], ["يعظكم به", "بالذي أنزله من أحكام الحلال والحرام، لتشكروه بطاعته."]], "m": "ما زال السياق في بيان أحكام الطلاق والخلع والرجعة. ففي هذه الآية يأمر الله عباده المؤمنين إذا طلّق أحدهم امرأته وقاربت نهاية عدتها أن يراجعها فيمسكها بمعروف، والمعروف حسن عشرتها، أو يتركها حتى تنقضي عدتها ويسرّحها بمعروف، فيعطيها كامل حقوقها ولا يذكرها إلا بخير ويتركها تذهب حيث شاءت. وحرّم على أحدهم أن يراجع امرأته من أجل أن يضر بها، فلا هو يحسن إليها ولا يطلقها فتستريح منه، فقال: ولا تمسكوهن ضراراً لتعتدوا، حتى تضطر المرأة المظلومة إلى المخالعة فتفدي نفسها منه بمال. وأخبر أن من يفعل هذا الإضرار فقد عرّض نفسه للعذاب. كما نهى عن التلاعب بالأحكام الشرعية بإهمالها وعدم تنفيذها: ولا تتخذوا آيات الله هزواً. وأمرهم أن يذكروا نعمة الله عليهم، حيث منّ عليهم بالإسلام دين الرحمة والعدالة والإحسان، وأن يذكروا نعمة إنزال الكتاب والحكمة ليعظهم بذلك، فيأمرهم بما فيه سعادتهم وكمالهم وينهاهم عما فيه شقاؤهم وخسرانهم. ثم أمرهم بتقواه، وأعلمهم أنه بكل شيء عليم لا يخفى عليه من أمرهم شيء، فليحذروا أن يراهم على معصيته.", "h": ["لا يحل للمطلِّق أن يراجع امرأته من أجل أن يضر بها ويظلمها حتى تخالعه بمال.", "حرمة التلاعب بالأحكام الشرعية بعدم مراعاتها وتنفيذها.", "وجوب ذكر نعمة الله على العبد، بذكرها باللسان والاعتراف بها في الجنان.", "مراقبة الله في سائر شؤون الحياة لأنه بكل شيء عليم."], "k": "هل أستعمل حقوقي أحياناً وسيلةً لإيذاء من أخالفه؟"}, {"lbl": "الآية ٢٣٢", "q": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٢٣٢﴾", "w": [["بلغن أجلهن", "انتهت عدتهن."], ["فلا تعضلوهن", "لا تمنعوهن من التزوج مرة أخرى بالعودة إلى الرجل الذي طلقها ولم يراجعها حتى انقضت عدتها."], ["إذا تراضوا بينهم بالمعروف", "إذا رضي الزوج المطلق أن يردّها إليه ورضيت هي بذلك."], ["ذلك يوعظ به", "النهي عن العضل يكلّف به أهل الإيمان إذ هم القادرون على الطاعة."], ["أزكى لكم", "ترك العضل خير لكم وأطهر لقلوبكم، إذ العضل قد يسبب ارتكاب الفاحشة."]], "m": "ينهى الله أولياء أمور النساء أن يمنعوا المطلقة طلقة أو طلقتين فقط من أن تعود إلى زوجها الذي طلقها وبانت منه بانقضاء عدتها، إذا رضيت هي بالزواج منه مرة أخرى ورضي هو به وعزما على المعاشرة الحسنة بالمعروف. وكانت هذه الآية استجابة لأخت معقل بن يسار رضي الله عنه، حيث أرادت أن ترجع إلى زوجها الذي طلقها وبانت منه، فمنعها أخوها معقل. وقوله: ذلكم يوعظ به من كان يؤمن بالله واليوم الآخر، أي هذا النهي عن العضل موجّه إلى أهل الإيمان، فهم الأحياء الذين يستجيبون لله ورسوله. وأخيراً أخبرهم أن عدم منع المطلقة من العودة إلى زوجها خير لهم حالاً ومآلاً وأطهر لقلوبهم ومجتمعهم، وأنه يعلم عواقب الأمور وهم لا يعلمون، فيجب التسليم لشرعه.", "h": ["حرمة العضل، أي منع المطلقة أن ترجع إلى من طلقها.", "وجوب الولاية على المرأة، لأن الخطاب في الآية كان للأولياء: «فلا تعضلوهن».", "المواعظ تنفع أهل الإيمان لحياة قلوبهم."], "k": "هل أقف في طريق خير لغيري بدافع الكبرياء أو العادات؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 33;
insert into public.tdb_cards(topic, i, body) select 33, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٢٤ – ٢٢٧", "q": "وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ﴿٢٢٤﴾ لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ﴿٢٢٥﴾ لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٢٢٦﴾ وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٢٢٧﴾", "w": [["عُرضة", "ما يوضع مانعاً من شيء؛ والمراد اليمين يحلفها المؤمن ألا يفعل خيراً."], ["الأيمان", "جمع يمين، نحو: والله لا أفعل كذا، أو والله لأفعلنّ كذا."], ["البر", "الطاعة وفعل الخير."], ["اللغو", "الباطل وما لا خير فيه؛ ولغو اليمين أن يحلف العبد على الشيء يظنه كذا فيتبين خلافه، أو ما يجري على لسانه من أيمان من غير إرادة الحلف."], ["كسبت قلوبكم", "ما تعمّد القلب وقصد اليمين لأجله، لفعله حتماً أو منعه."], ["يؤلون", "الإيلاء الحلف على عدم وطء الزوجة."], ["التربص", "الانتظار والتمهل."], ["فاءوا", "رجعوا إلى وطء نسائهم بعد الامتناع عنه باليمين."], ["الطلاق", "فك رابطة الزوجية وحلّها بقوله: هي طالق أو مطلقة أو طلقتك."]], "m": "ينهى الله أن يجعل المؤمن الحلف به مانعاً من فعل الخير، كأن يحلف ألا يتصدق أو لا يصلح بين اثنين: ولا تجعلوا الله عرضة لأيمانكم أن تبروا وتتقوا وتصلحوا بين الناس. ثم أخبر أنه لا يؤاخذ باللغو في الأيمان، وهو أن يحلف على الشيء يظنه كذا فيظهر خلافه، أو أن يجري على لسانه ما لا يقصده كقوله: لا والله وبلى والله، لكن يؤاخذ بما كسبت القلوب، كمن يحلف كاذباً ليأخذ حق أخيه، وهي اليمين الغموس، وعلى صاحبها التوبة وردّ الحق. وبمناسبة اليمين ذكر حكم الإيلاء، وهو أن يحلف الرجل ألا يطأ امرأته: فله تربص أربعة أشهر، فإن فاء وكفّر عن يمينه فالله غفور رحيم، وإن أصرّ وعزم الطلاق أوقفه القاضي ليفيء أو يطلّق، والله سميع عليم.", "h": ["كراهية منع الخير بسبب اليمين، فمن حلف ألا يفعل خيراً فليكفّر عن يمينه وليفعل الخير، لحديث: «من حلف على يمين فرأى غيرها خيراً منها فليكفّر عن يمينه وليأتِ الذي هو خير».", "لغو اليمين معفو عنها، ولها صورتان: أن يجري على لسانه لفظ اليمين وهو لا يريد الحلف نحو: لا والله وبلى والله؛ أو أن يحلف على شيء يظنه كذا فيتبين خلافه.", "اليمين المؤاخَذ عليها العبد هي أن يحلف متعمداً الكذب لتحصيل منفعة دنيوية، وهي اليمين الغموس.", "اليمين التي تجب فيها الكفارة هي أن يحلف العبد على أن يفعل كذا فيعجز، أو ألا يفعل كذا ثم يضطر فيفعل، ولم يقل أثناء الحلف: إن شاء الله. والكفارة مبينة في آية المائدة: إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فإن لم يجد صام ثلاثة أيام.", "حكم الإيلاء: إن كانت مدته أقل من أربعة أشهر فله أن يستمر إلى انتهاء المدة، والأفضل أن يطأ ويكفّر؛ وإن كانت أكثر من أربعة أشهر فعليه أن يفيء إلى زوجته أو تُطلّق عليه."], "k": "هل لساني يسبق قلبي في الحلف؟ وهل أحلف ثم أترك الخير بسبب يميني؟"}, {"lbl": "الآية ٢٢٨", "q": "وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ ﴿٢٢٨﴾", "w": [["المطلقات", "جمع مطلقة، وهي المرأة تسوء عشرتها فيطلقها زوجها أو القاضي."], ["يتربصن", "ينتظرن."], ["قروء", "القرء إما مدة الطهر أو مدة الحيض."], ["ما خلق الله في أرحامهن", "من الأجنة، فلا يحل للمطلقة أن تكتم ذلك."], ["بعولتهن", "أزواجهن، واحدهم بَعْل."], ["أحق بردهن", "في مدة التربص والانتظار."], ["ولهن مثل الذي عليهن", "على الزوجة حقوق لزوجها ولها حقوق على زوجها."], ["درجة", "درجة القوامة، فالرجل شرعاً هو القيّم على المرأة."]], "m": "في هذه الآية أن على المطلقة التي تحيض أن تنتظر ثلاثة قروء قبل أن تتزوج، وتسمى هذه المدة عدة، وهي واجبة لحق زوجها إذ له أن يراجعها فيها: وبعولتهن أحق بردهن في ذلك إن أرادوا إصلاحاً. وعليها ألا تكتم ما خلق الله في رحمها من حيض أو حمل، فهذا من كبائر الذنوب، لأنها قد تدّعي ما يخالف الحقيقة طلباً للرجعة أو منعاً لها، أو تنسب إلى زوج آخر ولداً ليس منه. وللزوج أن يراجعها ما دامت في العدة بشرط ألا يريد المضارة بل الإصلاح وطيب العشرة، وعليها أن تنوي ذلك أيضاً. ثم قرر أن للزوجة من الحقوق مثل ما عليها بالمعروف، وللرجل عليها درجة هي القوامة المفهومة من آية النساء: الرجال قوامون على النساء. وختمت بقوله: والله عزيز حكيم، إشعاراً بوجوب تنفيذ هذه التعاليم.", "h": ["بيان عدة المطلقة إذا كانت تحيض، وهو التربص ثلاثة حيض أو أطهار.", "حرمة كتمان المطلقة حيضاً أو حملاً خلقه الله في رحمها، ولأي غرض كان.", "أحقية الزوج بالرجعة من مطلقته ما لم تنقضِ عدتها، حتى قيل: الرجعية زوجة، بدليل أنها لو ماتت يرثها زوجها ولو مات ترثه؛ وأنه لا يحل أن تُخطب أو تتزوج ما دامت في عدتها.", "إثبات حقوق كل من الزوجين على صاحبه.", "تقرير سيادة الرجل على المرأة لما وهبه الله من ميزات الرجولة."], "k": "هل أؤدي ما عليّ من حقوق في بيتي قبل أن أطالب بما لي؟"}, {"lbl": "الآية ٢٢٩", "q": "ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٢٩﴾", "w": [["الطلاق", "الاسم من طلّق، وهو أن يقول الرجل لزوجته: أنت طالق أو طلقتك."], ["مرتان", "يملك الزوج الإرجاع في طلقتين، أما إن طلّق الثالثة فلا يملك ذلك ولا ترجع إليه حتى تنكح زوجاً غيره."], ["فإن خفتم ألا يقيما حدود الله", "حسن العشرة؛ فإن خافت المرأة أو خاف الزوج ألا يؤدي حقوق الزوجية جاز الفداء، وهو دفع مال للزوج ليخلّي سبيل المرأة، ويسمى هذا خلعاً."], ["حدود الله", "ما يجب أن ينتهي إليه العبد من طاعة الله ولا يتجاوزه."], ["الظالم", "المتجاوز لما حدّ الله، والظلم وضع الشيء في غير موضعه."]], "m": "ما زال السياق في بيان أحكام الطلاق، فيقرر الله في هذه الآية أن الطلاق الذي يملك الزوج الرجعة فيه طلقتان: أولى وثانية فقط. ومن هنا فمن طلّق الثانية فهو بين خيارين: إما أن يمسك زوجته بمعروف، أي بحسن العشرة وأداء ما للزوجة من حقوق، أو يسرّح، أي يطلّق بإحسان، بأن يعطيها باقي صداقها إن بقي ويمتّعها بشيء من المال ولا يذكرها بسوء. وحرّم على الزوج أن يأخذ من مهر زوجته شيئاً بدون رضاها، إلا في حال واحدة، وهي إذا كرهت المرأة الزوج ولم تطق البقاء معه وهو غير ظالم لها، ففي هذه الحال يجوز أن تعطي الزوج مالاً ويطلقها، ويسمى هذا خلعاً، وهو حلال على الزوج غير الظالم. وقوله: تلك حدود الله، يريد أحكام شرعه، فلا يحل تجاوز الحلال إلى الحرام، ولا الإحسان إلى الإساءة، ولا المعروف إلى المنكر، ومن يتعدّ حدود الله فقد ظلم نفسه وعرّضها للعذاب.", "h": ["حرمة الطلاق الثلاث بلفظ واحد، لأن الله قال: «الطلاق مرتان».", "المطلقة ثلاث طلقات لا تحل لزوجها حتى تنكح زوجاً غيره ويطلقها أو يموت عنها.", "مشروعية الخلع، وهو أن تكره المرأة البقاء مع زوجها فتخلع نفسها منه بمال تعطيه إياه عوضاً عما أنفق عليها في الزواج بها.", "وجوب الوقوف عند حدود الله وحرمة تعديها.", "تحريم الظلم، وهو ثلاثة أنواع: ظلم الشرك ولا يغفر إلا بالتوبة منه، وظلم العبد لأخيه الإنسان ولا بد من التحلل منه، وظلم العبد لنفسه بتعدي حد من حدود الله وأمره إلى الله إن شاء غفره وإن شاء أخذ به."], "k": "عند الخلاف: هل أقف عند حدود الله فأصبر على الإمساك بمعروف أو أُفارق بإحسان؟"}, {"lbl": "الآية ٢٣٠", "q": "فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ ﴿٢٣٠﴾", "w": [["فإن طلقها فلا تحل له", "الطلقة الثالثة، فلا تحل له إلا بعد أن تنكح زوجاً غيره."], ["فلا جناح عليهما", "لا إثم ولا حرج عليهما في الزواج من جديد."], ["أن يتراجعا", "أن يرجع كل منهما لصاحبه بعقد جديد، بشرط أن يظنا إقامة حدود الله فيهما، وإلا فلا يجوز نكاحهما."]], "m": "يقول الله مبيّناً حكم من طلّق امرأته الطلقة الثالثة: فإن طلقها فلا تحل له من بعد حتى تنكح زوجاً غيره، ويكون النكاح صحيحاً ويبني بها الزوج الثاني، لحديث: «حتى تذوقي عسيلته ويذوق عسيلتك». فإن طلقها الثاني بعد البناء والخلوة والوطء أو مات عنها جاز لها أن تعود إلى الأول إن رغب هو في ذلك وعلما من أنفسهما أنهما يقيمان حدود الله، بإعطاء كل واحد حقوق صاحبه مع حسن العشرة، وإلا فلا مراجعة تحل لهما. ولذا قال: إن ظنّا أن يقيما حدود الله. ثم نوّه الله بشأن تلك الحدود فقال: وتلك حدود الله، وهي شرائعه.", "h": ["المطلقة ثلاثاً لا تحل لمطلقها إلا بشرطين: أن تنكح زوجاً غيره نكاحاً صحيحاً ويبني بها ويطأها، وأن يغلب على ظن كل منهما أن العشرة بينهما ستطيب وألا يتكرر الاعتداء الذي أدى إلى الطلاق ثلاث مرات.", "موت الزوج الثاني كطلاقه، تصح معه الرجعة إلى الزوج الأول بشرطه.", "إن تزوجت المطلقة ثلاثاً بنية التمرّد على الزوج حتى يطلقها لتعود إلى الأول، فلا يحلّها هذا النكاح، لأن الرسول ﷺ أبطله وقال: «لعن الله المحلِّل والمحلَّل له»."], "k": "هل أتأنّى قبل نطق ما لا رجعة فيه من كلام؟"}, {"lbl": "الآية ٢٣١", "q": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٢٣١﴾", "w": [["بلغن أجلهن", "قاربن انتهاء أيام عدتهن."], ["أو سرحوهن", "تسريح المطلقة تركها بلا مراجعة لها حتى تنقضي عدتها وتبين من زوجها."], ["ضراراً", "مضارة لها وإضراراً بها."], ["لتعتدوا", "لتتجاوزوا حد الإحسان إلى الإساءة."], ["هزواً", "لعباً بها بعدم التزامكم بتطبيق أحكامها."], ["نعمة الله", "هنا هي الإسلام."], ["الحكمة", "السنة النبوية."], ["يعظكم به", "بالذي أنزله من أحكام الحلال والحرام، لتشكروه بطاعته."]], "m": "ما زال السياق في بيان أحكام الطلاق والخلع والرجعة. ففي هذه الآية يأمر الله عباده المؤمنين إذا طلّق أحدهم امرأته وقاربت نهاية عدتها أن يراجعها فيمسكها بمعروف، والمعروف حسن عشرتها، أو يتركها حتى تنقضي عدتها ويسرّحها بمعروف، فيعطيها كامل حقوقها ولا يذكرها إلا بخير ويتركها تذهب حيث شاءت. وحرّم على أحدهم أن يراجع امرأته من أجل أن يضر بها، فلا هو يحسن إليها ولا يطلقها فتستريح منه، فقال: ولا تمسكوهن ضراراً لتعتدوا، حتى تضطر المرأة المظلومة إلى المخالعة فتفدي نفسها منه بمال. وأخبر أن من يفعل هذا الإضرار فقد عرّض نفسه للعذاب. كما نهى عن التلاعب بالأحكام الشرعية بإهمالها وعدم تنفيذها: ولا تتخذوا آيات الله هزواً. وأمرهم أن يذكروا نعمة الله عليهم، حيث منّ عليهم بالإسلام دين الرحمة والعدالة والإحسان، وأن يذكروا نعمة إنزال الكتاب والحكمة ليعظهم بذلك، فيأمرهم بما فيه سعادتهم وكمالهم وينهاهم عما فيه شقاؤهم وخسرانهم. ثم أمرهم بتقواه، وأعلمهم أنه بكل شيء عليم لا يخفى عليه من أمرهم شيء، فليحذروا أن يراهم على معصيته.", "h": ["لا يحل للمطلِّق أن يراجع امرأته من أجل أن يضر بها ويظلمها حتى تخالعه بمال.", "حرمة التلاعب بالأحكام الشرعية بعدم مراعاتها وتنفيذها.", "وجوب ذكر نعمة الله على العبد، بذكرها باللسان والاعتراف بها في الجنان.", "مراقبة الله في سائر شؤون الحياة لأنه بكل شيء عليم."], "k": "هل أستعمل حقوقي أحياناً وسيلةً لإيذاء من أخالفه؟"}, {"lbl": "الآية ٢٣٢", "q": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٢٣٢﴾", "w": [["بلغن أجلهن", "انتهت عدتهن."], ["فلا تعضلوهن", "لا تمنعوهن من التزوج مرة أخرى بالعودة إلى الرجل الذي طلقها ولم يراجعها حتى انقضت عدتها."], ["إذا تراضوا بينهم بالمعروف", "إذا رضي الزوج المطلق أن يردّها إليه ورضيت هي بذلك."], ["ذلك يوعظ به", "النهي عن العضل يكلّف به أهل الإيمان إذ هم القادرون على الطاعة."], ["أزكى لكم", "ترك العضل خير لكم وأطهر لقلوبكم، إذ العضل قد يسبب ارتكاب الفاحشة."]], "m": "ينهى الله أولياء أمور النساء أن يمنعوا المطلقة طلقة أو طلقتين فقط من أن تعود إلى زوجها الذي طلقها وبانت منه بانقضاء عدتها، إذا رضيت هي بالزواج منه مرة أخرى ورضي هو به وعزما على المعاشرة الحسنة بالمعروف. وكانت هذه الآية استجابة لأخت معقل بن يسار رضي الله عنه، حيث أرادت أن ترجع إلى زوجها الذي طلقها وبانت منه، فمنعها أخوها معقل. وقوله: ذلكم يوعظ به من كان يؤمن بالله واليوم الآخر، أي هذا النهي عن العضل موجّه إلى أهل الإيمان، فهم الأحياء الذين يستجيبون لله ورسوله. وأخيراً أخبرهم أن عدم منع المطلقة من العودة إلى زوجها خير لهم حالاً ومآلاً وأطهر لقلوبهم ومجتمعهم، وأنه يعلم عواقب الأمور وهم لا يعلمون، فيجب التسليم لشرعه.", "h": ["حرمة العضل، أي منع المطلقة أن ترجع إلى من طلقها.", "وجوب الولاية على المرأة، لأن الخطاب في الآية كان للأولياء: «فلا تعضلوهن».", "المواعظ تنفع أهل الإيمان لحياة قلوبهم."], "k": "هل أقف في طريق خير لغيري بدافع الكبرياء أو العادات؟"}]$j$::jsonb) with ordinality x(e, i);

-- 34. سورة البقرة ٢٣٣ – ٢٤٢ · الرضاع وعدة الوفاة والمتعة
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (34, 2, 233, 242, 'سورة البقرة ٢٣٣ – ٢٤٢', 'الرضاع وعدة الوفاة والمتعة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 34) = $j$[{"lbl": "الآية ٢٣٣", "q": "۞وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٢٣٣﴾", "w": [["حولين", "عامين."], ["المولود له", "الأب."], ["بالمعروف", "بحسب حاله يسراً وعسراً."], ["وسعها", "طاقتها وما تقدر عليه."], ["لا تضارّ والدة بولدها", "لا يحل أن تؤذى أم الولد بمنعها من إرضاع ولدها، أو بمنعها الأجرة على إرضاعه، وهذا في حال طلاقها أو موت زوجها."], ["ولا مولود له", "ولا يُضارّ الوالد كذلك بأن يجبر على إرضاع الولد من أمه المطلقة أو يطالب بأجرة لا يطيقها."], ["وعلى الوارث", "الوارث هو الرضيع نفسه إن كان له مال، وإلا فعلى من يكفله من عصبته."], ["فصالاً", "فطاماً للولد قبل نهاية العامين."]], "m": "بمناسبة أحكام الطلاق وقد تطلق المرأة وهي حامل، ذكر الله أحكام الرضاع: والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة، وعلى المولود له، أي الأب، رزقهن وكسوتهن بالمعروف بحسب حاله، إذ لا يكلف الله نفساً إلا وسعها. ولا يجوز أن تؤذى الأم بسبب ولدها بمنعها من إرضاعه أو إكراهها عليه أو تضييق النفقة عليها، ولا أن يؤذى الأب بنفقة باهظة لا يقدر عليها. وعلى الوارث، وهو الرضيع نفسه إن كان له مال، وإلا فعلى عصبته الأقرب فالأقرب، وإن لم يكن له مال ولا عصبة وجب على الأم أن ترضعه مجاناً. ثم ذكر رخصتين: فطام الولد قبل عامين عن تراض وتشاور، واسترضاع مرضعة غير الأم إن طابت نفس الأم وسُلّمت الأجرة بالمعروف. وختم بتقواه: واعلموا أن الله بما تعملون بصير.", "h": ["وجوب إرضاع الأم ولدها الرضعة الأولى (اللبأ) إن كانت مطلقة، وسائر الرضاع إن كانت غير مطلقة.", "بيان الحد الأعلى للرضاع وهو عامان تامان، ولذا فالزيادة عليهما غير معتبرة شرعاً.", "جواز إرضاع الوالد ولده من مرضعة غير والدته."], "k": "هل أراعي حق الضعيف الذي لا يستطيع أن يدافع عن نفسه، ولو كان طفلاً رضيعاً؟"}, {"lbl": "الآيتان ٢٣٤ – ٢٣٥", "q": "وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٣٤﴾ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ ﴿٢٣٥﴾", "w": [["يذرون أزواجاً", "يتركون زوجات."], ["يتربصن بأنفسهن", "ينتظرن حتى انقضاء عدتهن، وهي أربعة أشهر وعشر ليال."], ["بلغن أجلهن", "بلغن انتهاء العدة."], ["لا جناح عليكم", "لا حرج عليكم أيها الأولياء فيما فعلن في أنفسهن من مسّ الطيب والتجمل والتعرض للخطاب؛ ولا إثم عليكم في التعريض دون التصريح بالخطبة، كما لا إثم في إضمار الرغبة في النفس."], ["حتى يبلغ الكتاب أجله", "حتى تنتهي العدة."]], "m": "على من مات عنها زوجها أن تنتظر أربعة أشهر وعشر ليال إن كانت حرة، أو نصف المدة إن كانت أمة، فلا تتجمل ولا تمسّ طيباً ولا تتعرض للخطاب حتى تنقضي عدتها، إلا الحامل فعدتها بوضع حملها. فإذا انقضت فلا جناح على أوليائها ولا عليها فيما تفعل بنفسها بالمعروف. وفي الآية الثانية تحريم خطبة المعتدة من طلاق أو وفاة لما فيه من ضرر، ورفع الحرج في التعريض بالخطبة دون التصريح، نحو: إني راغب في الزواج، لأن الله علم أنكم ستذكرونهن، ولكن لا تواعدوهن سراً. أما المطلقة طلاقاً رجعياً فلا تصح خطبتها تعريضاً ولا تصريحاً لأنها في حكم الزوجة. وحرّم عقد النكاح على المعتدة حتى يبلغ الكتاب أجله، أي تنتهي العدة. وختم بوعظ المؤمنين أن يعلموا أن الله يعلم ما في أنفسهم فيحذروه، وأنه غفور حليم.", "h": ["بيان عدة الوفاة، وهي أربعة أشهر وعشر ليال، وبيّنت السنة أن عدة الأمة على النصف.", "وجوب الإحداد على المتوفى عنها زوجها، وهو عدم التزين ومسّ الطيب وعدم التعرض للخطاب وملازمة المنزل الذي توفي عنها زوجها وهي فيه فلا تخرج منه إلا لضرورة قصوى.", "حرمة خطبة المعتدة، وجواز التعريض لها بلفظ غير صريح.", "حرمة عقد النكاح على معتدّة قبل انقضاء عدتها، وهذا من باب أولى من حرمة الخطبة؛ ومن عقد على امرأة قبل انقضاء عدتها يُفرَّق بينهما ولا تحل له بعد ذلك عقوبة له.", "وجوب مراقبة الله في السر والعلن واتقاء الأسباب المفضية بالعبد إلى فعل ما حرم الله."], "k": "هل أراقب الله فيما أُضمره، لا فيما أُظهره فقط؟"}, {"lbl": "الآيات ٢٣٦ – ٢٣٩", "q": "لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ ﴿٢٣٦﴾ وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢٣٧﴾ حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ ﴿٢٣٨﴾ فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ ﴿٢٣٩﴾", "w": [["لا جناح", "لا إثم مترتب على المعصية."], ["ما لم تمسوهن", "ما لم تجامعوهن."], ["أو تفرضوا لهن فريضة", "أو تقدّروا لهن مهراً."], ["الموسع قدره", "قدر الغني ما يقدر عليه ويستطيع، وعلى المُقتِر قدر الفقير."], ["الذي بيده عقدة النكاح", "هو الزوج."], ["ولا تنسوا الفضل بينكم", "أي المودة والإحسان."], ["حافظوا على الصلوات", "بأدائها في أوقاتها وفي جماعة مع استيفاء شروطها وأركانها وسننها."], ["الصلاة الوسطى", "صلاة العصر، وقيل الصبح؛ فتجب المحافظة على كل الصلوات وخاصة العصر والصبح، لقول الرسول ﷺ: «من صلى البردين دخل الجنة»."], ["قانتين", "خاشعين ساكتين."], ["رجالاً", "مشاة على أرجلكم، أو ركباناً على الدواب وغيرها مما يُركب."]], "m": "ينفي الله الإثم عمن طلّق امرأته قبل البناء بها وقبل تسمية المهر، وعليه أن يمتّعها بمال بحسب غناه وفقره. ومن طلّق قبل البناء وقد سمّى مهراً فعليه نصفه، إلا أن تعفو هي أو يعفو الزوج فيعطيها كاملاً، والعفو أقرب للتقوى، ولا يُنسى الفضل والمودة بينهما. ثم دعا إلى ما يعين على هذه الآداب، وهو المحافظة على الصلوات الخمس عامة والصلاة الوسطى خاصة، وكانوا يتكلمون في الصلاة فمنعهم بقوله: وقوموا لله قانتين، أي ساكتين خاشعين. فإن حصل خوف لا يتمكنون معه من الأداء بالسكون والخشوع فليصلوا مشاة أو ركباناً، فإذا أمنوا فليصلوا على هيئتهم المعتادة، فاذكروا الله كما علمكم ما لم تكونوا تعلمون. والمراد بالذكر هنا إقامة الصلاة أولاً ثم الذكر العام شكراً لنعمة العلم.", "h": ["بيان حكم المطلقة قبل البناء وقبل تسمية المهر، وأن لها المتعة فقط بحسب حال المطلق من غنى وفقر.", "بيان حكم المطلقة قبل البناء وقد سمّي لها صداق، فإن لها نصفه وجوباً، إلا أن تتنازل عنه برضاها، كما أن للزوج المطلق إذا تنازل عن النصف أن يعطيها المسمى كاملاً.", "الدعوة إلى إبقاء المودة والفضل والإحسان بين الأسرتين: أسرة المرأة المطلقة وأسرة الزوج المطلق، حتى لا يكون الطلاق سبباً في العداوات والتقاطع.", "وجوب المحافظة على الصلوات الخمس وبخاصة صلاة العصر وصلاة الصبح.", "منع الكلام في الصلاة لغير إصلاحها.", "وجوب الخشوع في الصلاة."], "k": "أي صلاة من صلواتي أضيّعها أكثر من غيرها؟ وكيف أحافظ عليها من اليوم؟"}, {"lbl": "الآيات ٢٤٠ – ٢٤٢", "q": "وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٢٤٠﴾ وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ ﴿٢٤١﴾ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿٢٤٢﴾", "w": [["الحول", "العام."], ["فإن خرجن", "من بيت الزوج المتوفى قبل نهاية السنة."], ["متاع", "ما يتمتع به؛ والمراد نفقة وسكن إلى تمام السنة."]], "m": "يخبر الله أن الذين يتوفون من المؤمنين ويتركون أزواجاً، فلهن وصية على ورثتهم أن ينفقوا عليهن ويسكنوهن إلى نهاية السنة بما فيها مدة العدة، إلا إذا رغبت في الخروج بعد انقضاء العدة فلها ذلك، فلا جناح على الورثة فيما فعلن في أنفسهن من معروف، والله عزيز حكيم. وفي الآية الثانية: وللمطلقات متاع بالمعروف حقاً على المتقين، فالمطلقة المبنيّ بها يمتّعها مطلّقها بشيء من المال كثياب أو دابة أو خادمة، والمطلقة قبل البناء وقبل تسمية المهر لها المتعة، والتي سُمّي لها المهر لها نصفه. وقوله: كذلك يبين الله لكم آياته لعلكم تعقلون، أي كهذا البيان لأحكام الطلاق والخلع والرضاع والعدد والمتع يبين لنا آياته لنعقلها ونعمل بها.", "h": ["الإبقاء على المعتدة عدة وفاة في بيت الهالك سنة إن طابت نفسها بذلك، وذلك بعد انقضاء العدة الواجبة، فالزائد وهو سبعة أشهر وعشرون يوماً جاء في هذه الوصية.", "حق المطلقة المدخول بها في المتعة بالمعروف.", "منّة الله على هذه الأمة ببيان الأحكام لها لتسعد بها وتكمل عليها، فلله الحمد والشكر."], "k": "هل أحمد الله أن شرعه لي ما يحفظ الحقوق، وأعمل بما أعلم منه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 34;
insert into public.tdb_cards(topic, i, body) select 34, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ٢٣٣", "q": "۞وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٢٣٣﴾", "w": [["حولين", "عامين."], ["المولود له", "الأب."], ["بالمعروف", "بحسب حاله يسراً وعسراً."], ["وسعها", "طاقتها وما تقدر عليه."], ["لا تضارّ والدة بولدها", "لا يحل أن تؤذى أم الولد بمنعها من إرضاع ولدها، أو بمنعها الأجرة على إرضاعه، وهذا في حال طلاقها أو موت زوجها."], ["ولا مولود له", "ولا يُضارّ الوالد كذلك بأن يجبر على إرضاع الولد من أمه المطلقة أو يطالب بأجرة لا يطيقها."], ["وعلى الوارث", "الوارث هو الرضيع نفسه إن كان له مال، وإلا فعلى من يكفله من عصبته."], ["فصالاً", "فطاماً للولد قبل نهاية العامين."]], "m": "بمناسبة أحكام الطلاق وقد تطلق المرأة وهي حامل، ذكر الله أحكام الرضاع: والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة، وعلى المولود له، أي الأب، رزقهن وكسوتهن بالمعروف بحسب حاله، إذ لا يكلف الله نفساً إلا وسعها. ولا يجوز أن تؤذى الأم بسبب ولدها بمنعها من إرضاعه أو إكراهها عليه أو تضييق النفقة عليها، ولا أن يؤذى الأب بنفقة باهظة لا يقدر عليها. وعلى الوارث، وهو الرضيع نفسه إن كان له مال، وإلا فعلى عصبته الأقرب فالأقرب، وإن لم يكن له مال ولا عصبة وجب على الأم أن ترضعه مجاناً. ثم ذكر رخصتين: فطام الولد قبل عامين عن تراض وتشاور، واسترضاع مرضعة غير الأم إن طابت نفس الأم وسُلّمت الأجرة بالمعروف. وختم بتقواه: واعلموا أن الله بما تعملون بصير.", "h": ["وجوب إرضاع الأم ولدها الرضعة الأولى (اللبأ) إن كانت مطلقة، وسائر الرضاع إن كانت غير مطلقة.", "بيان الحد الأعلى للرضاع وهو عامان تامان، ولذا فالزيادة عليهما غير معتبرة شرعاً.", "جواز إرضاع الوالد ولده من مرضعة غير والدته."], "k": "هل أراعي حق الضعيف الذي لا يستطيع أن يدافع عن نفسه، ولو كان طفلاً رضيعاً؟"}, {"lbl": "الآيتان ٢٣٤ – ٢٣٥", "q": "وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٣٤﴾ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ ﴿٢٣٥﴾", "w": [["يذرون أزواجاً", "يتركون زوجات."], ["يتربصن بأنفسهن", "ينتظرن حتى انقضاء عدتهن، وهي أربعة أشهر وعشر ليال."], ["بلغن أجلهن", "بلغن انتهاء العدة."], ["لا جناح عليكم", "لا حرج عليكم أيها الأولياء فيما فعلن في أنفسهن من مسّ الطيب والتجمل والتعرض للخطاب؛ ولا إثم عليكم في التعريض دون التصريح بالخطبة، كما لا إثم في إضمار الرغبة في النفس."], ["حتى يبلغ الكتاب أجله", "حتى تنتهي العدة."]], "m": "على من مات عنها زوجها أن تنتظر أربعة أشهر وعشر ليال إن كانت حرة، أو نصف المدة إن كانت أمة، فلا تتجمل ولا تمسّ طيباً ولا تتعرض للخطاب حتى تنقضي عدتها، إلا الحامل فعدتها بوضع حملها. فإذا انقضت فلا جناح على أوليائها ولا عليها فيما تفعل بنفسها بالمعروف. وفي الآية الثانية تحريم خطبة المعتدة من طلاق أو وفاة لما فيه من ضرر، ورفع الحرج في التعريض بالخطبة دون التصريح، نحو: إني راغب في الزواج، لأن الله علم أنكم ستذكرونهن، ولكن لا تواعدوهن سراً. أما المطلقة طلاقاً رجعياً فلا تصح خطبتها تعريضاً ولا تصريحاً لأنها في حكم الزوجة. وحرّم عقد النكاح على المعتدة حتى يبلغ الكتاب أجله، أي تنتهي العدة. وختم بوعظ المؤمنين أن يعلموا أن الله يعلم ما في أنفسهم فيحذروه، وأنه غفور حليم.", "h": ["بيان عدة الوفاة، وهي أربعة أشهر وعشر ليال، وبيّنت السنة أن عدة الأمة على النصف.", "وجوب الإحداد على المتوفى عنها زوجها، وهو عدم التزين ومسّ الطيب وعدم التعرض للخطاب وملازمة المنزل الذي توفي عنها زوجها وهي فيه فلا تخرج منه إلا لضرورة قصوى.", "حرمة خطبة المعتدة، وجواز التعريض لها بلفظ غير صريح.", "حرمة عقد النكاح على معتدّة قبل انقضاء عدتها، وهذا من باب أولى من حرمة الخطبة؛ ومن عقد على امرأة قبل انقضاء عدتها يُفرَّق بينهما ولا تحل له بعد ذلك عقوبة له.", "وجوب مراقبة الله في السر والعلن واتقاء الأسباب المفضية بالعبد إلى فعل ما حرم الله."], "k": "هل أراقب الله فيما أُضمره، لا فيما أُظهره فقط؟"}, {"lbl": "الآيات ٢٣٦ – ٢٣٩", "q": "لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ ﴿٢٣٦﴾ وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢٣٧﴾ حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ ﴿٢٣٨﴾ فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ ﴿٢٣٩﴾", "w": [["لا جناح", "لا إثم مترتب على المعصية."], ["ما لم تمسوهن", "ما لم تجامعوهن."], ["أو تفرضوا لهن فريضة", "أو تقدّروا لهن مهراً."], ["الموسع قدره", "قدر الغني ما يقدر عليه ويستطيع، وعلى المُقتِر قدر الفقير."], ["الذي بيده عقدة النكاح", "هو الزوج."], ["ولا تنسوا الفضل بينكم", "أي المودة والإحسان."], ["حافظوا على الصلوات", "بأدائها في أوقاتها وفي جماعة مع استيفاء شروطها وأركانها وسننها."], ["الصلاة الوسطى", "صلاة العصر، وقيل الصبح؛ فتجب المحافظة على كل الصلوات وخاصة العصر والصبح، لقول الرسول ﷺ: «من صلى البردين دخل الجنة»."], ["قانتين", "خاشعين ساكتين."], ["رجالاً", "مشاة على أرجلكم، أو ركباناً على الدواب وغيرها مما يُركب."]], "m": "ينفي الله الإثم عمن طلّق امرأته قبل البناء بها وقبل تسمية المهر، وعليه أن يمتّعها بمال بحسب غناه وفقره. ومن طلّق قبل البناء وقد سمّى مهراً فعليه نصفه، إلا أن تعفو هي أو يعفو الزوج فيعطيها كاملاً، والعفو أقرب للتقوى، ولا يُنسى الفضل والمودة بينهما. ثم دعا إلى ما يعين على هذه الآداب، وهو المحافظة على الصلوات الخمس عامة والصلاة الوسطى خاصة، وكانوا يتكلمون في الصلاة فمنعهم بقوله: وقوموا لله قانتين، أي ساكتين خاشعين. فإن حصل خوف لا يتمكنون معه من الأداء بالسكون والخشوع فليصلوا مشاة أو ركباناً، فإذا أمنوا فليصلوا على هيئتهم المعتادة، فاذكروا الله كما علمكم ما لم تكونوا تعلمون. والمراد بالذكر هنا إقامة الصلاة أولاً ثم الذكر العام شكراً لنعمة العلم.", "h": ["بيان حكم المطلقة قبل البناء وقبل تسمية المهر، وأن لها المتعة فقط بحسب حال المطلق من غنى وفقر.", "بيان حكم المطلقة قبل البناء وقد سمّي لها صداق، فإن لها نصفه وجوباً، إلا أن تتنازل عنه برضاها، كما أن للزوج المطلق إذا تنازل عن النصف أن يعطيها المسمى كاملاً.", "الدعوة إلى إبقاء المودة والفضل والإحسان بين الأسرتين: أسرة المرأة المطلقة وأسرة الزوج المطلق، حتى لا يكون الطلاق سبباً في العداوات والتقاطع.", "وجوب المحافظة على الصلوات الخمس وبخاصة صلاة العصر وصلاة الصبح.", "منع الكلام في الصلاة لغير إصلاحها.", "وجوب الخشوع في الصلاة."], "k": "أي صلاة من صلواتي أضيّعها أكثر من غيرها؟ وكيف أحافظ عليها من اليوم؟"}, {"lbl": "الآيات ٢٤٠ – ٢٤٢", "q": "وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٢٤٠﴾ وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ ﴿٢٤١﴾ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ﴿٢٤٢﴾", "w": [["الحول", "العام."], ["فإن خرجن", "من بيت الزوج المتوفى قبل نهاية السنة."], ["متاع", "ما يتمتع به؛ والمراد نفقة وسكن إلى تمام السنة."]], "m": "يخبر الله أن الذين يتوفون من المؤمنين ويتركون أزواجاً، فلهن وصية على ورثتهم أن ينفقوا عليهن ويسكنوهن إلى نهاية السنة بما فيها مدة العدة، إلا إذا رغبت في الخروج بعد انقضاء العدة فلها ذلك، فلا جناح على الورثة فيما فعلن في أنفسهن من معروف، والله عزيز حكيم. وفي الآية الثانية: وللمطلقات متاع بالمعروف حقاً على المتقين، فالمطلقة المبنيّ بها يمتّعها مطلّقها بشيء من المال كثياب أو دابة أو خادمة، والمطلقة قبل البناء وقبل تسمية المهر لها المتعة، والتي سُمّي لها المهر لها نصفه. وقوله: كذلك يبين الله لكم آياته لعلكم تعقلون، أي كهذا البيان لأحكام الطلاق والخلع والرضاع والعدد والمتع يبين لنا آياته لنعقلها ونعمل بها.", "h": ["الإبقاء على المعتدة عدة وفاة في بيت الهالك سنة إن طابت نفسها بذلك، وذلك بعد انقضاء العدة الواجبة، فالزائد وهو سبعة أشهر وعشرون يوماً جاء في هذه الوصية.", "حق المطلقة المدخول بها في المتعة بالمعروف.", "منّة الله على هذه الأمة ببيان الأحكام لها لتسعد بها وتكمل عليها، فلله الحمد والشكر."], "k": "هل أحمد الله أن شرعه لي ما يحفظ الحقوق، وأعمل بما أعلم منه؟"}]$j$::jsonb) with ordinality x(e, i);

-- 35. سورة البقرة ٢٤٣ – ٢٥٢ · الجهاد وبنو إسرائيل: الألوف وطالوت
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (35, 2, 243, 252, 'سورة البقرة ٢٤٣ – ٢٥٢', 'الجهاد وبنو إسرائيل: الألوف وطالوت', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 35) = $j$[{"lbl": "الآيات ٢٤٣ – ٢٤٥", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٢٤٣﴾ وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٢٤٤﴾ مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢٤٥﴾", "w": [["ألم تر", "ألم ينته إلى علمك؛ فالرؤية قلبية والاستفهام للتعجيب."], ["ألوف", "جمع ألف، وهي صيغة كثرة، فهم إذن عشرات الألوف."], ["في سبيل الله", "الطريق الموصل إلى مرضاته، وهو طاعته بامتثال أمره واجتناب نهيه، ومن ذلك جهاد الكفار والظالمين حتى لا تكون فتنة."], ["يقرض الله", "يقتطع شيئاً من ماله وينفقه في الجهاد لشراء السلاح وتسيير المجاهدين."], ["يقبض ويبسط", "يضيّق ويوسّع؛ يقبض ابتلاءً ويبسط امتحاناً."]], "m": "يخاطب الله رسوله ﷺ فيقول: ألم ينته إلى علمك قصة الذين خرجوا من ديارهم فراراً من الموت وهم ألوف؟ وهم أهل مدينة من مدن بني إسرائيل أصابهم الله بمرض الطاعون، ففروا هاربين من الموت، فأماتهم الله عن آخرهم ثم أحياهم بدعوة نبيهم حزقيل عليه السلام. فهل أنجاهم فرارهم من الموت؟ وكذلك من يفرّ من القتال هل ينجيه فراره من الموت؟ والجواب: لا، وإذن فلم الفرار من الجهاد إذا تعيّن؟ وفي تأديب تلك الجماعة بإماتتها ثم إحيائها فضل من الله عظيم، ولكن أكثر الناس لا يشكرون. وإذن فقاتلوا أيها المسلمون في سبيل الله ولا تتأخروا متى دُعيتم إلى الجهاد بالنفس والمال، واعلموا أن الله سميع لأقوالكم عليم بنياتكم وأعمالكم فاحذروه. ثم فتح باب الاكتتاب المالي لجهاد الأعداء: من ذا الذي يقرض الله قرضاً حسناً، أي بإخلاص وطيب نفس، فإن الله يضاعفه له أضعافاً كثيرة، الدرهم بسبعمائة درهم، فأنفقوا أيها المؤمنون في سبيل إعلاء كلمة الله ولا تخافوا الفقر، فإن ربكم يقبض ويبسط: يضيّق على العبد ابتلاء ويوسّع امتحاناً، فمنعكم الإنفاق في سبيل الله لا يغيّر من تدبير الله شيئاً.", "h": ["إذا نزل الوباء ببلد لا يجوز الخروج فراراً منه، وبهذا ثبتت السنة.", "وجوب ذكر النعم وشكرها.", "وجوب القتال في سبيل الله إذا تعيّن.", "فضل الإنفاق في سبيل الله.", "بيان الحكمة في تضييق الله على العبد رزقه وتوسيعه، وهو الابتلاء لأجل الصبر والامتحان لأجل الشكر؛ فيا خيبة من لم يصبر عند التضييق عليه ولم يشكر عند التوسعة له."], "k": "عند ضيق الرزق وعند سعته: هل أصبر في الأولى وأشكر في الثانية؟"}, {"lbl": "الآيتان ٢٤٦ – ٢٤٧", "q": "أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٢٤٦﴾ وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٢٤٧﴾", "w": [["الملأ", "أشراف الناس من أهل الحل والعقد بينهم، إذا نظر المرء إليهم ملؤوا عينه روعة وقلبه هيبة."], ["عسى", "كلمة توقّع وترجٍّ."], ["كُتب", "فُرض ولزم."], ["ملكاً", "يسوسهم في السلم والحرب."], ["أنى يكون", "الاستفهام للإنكار بمعنى: كيف يكون له الملك؟"], ["اصطفاه", "فضّله عليكم واختاره لكم."], ["بسطة في الجسم", "طولاً زائداً يعلو به من عداه."]], "m": "لما فرض الله القتال ودارت المعارك من بدر، اقتضى الموقف شحذ الهمم، فذكر قصة الملأ من بني إسرائيل بعد موسى إذ قالوا لنبي لهم: ابعث لنا ملكاً نقاتل في سبيل الله. فخاف النبي ألا يصدقوا فقال: هل عسيتم إن كُتب عليكم القتال ألا تقاتلوا؟ فقالوا: وما لنا ألا نقاتل في سبيل الله وقد أُخرجنا من ديارنا وأبنائنا؟ وكان العدو قد غزا فلسطين بعد أن فسق بنو إسرائيل واستباحوا المحرمات وعطلوا الكتاب. فبعث شمويل طالوت، فلما دنوا من المعركة جبنوا وتولى أكثرهم. وفي الآية الثانية اعترض الملأ على تعيين طالوت لأنه فقير من أسرة غير شريفة، فرد نبيهم: إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء. والقيادة القتالية تعتمد على غزارة العلم وقوة البدن وشجاعة العقل والقلب.", "h": ["الجهاد الشرعي يُشترط له الإمام المبايَع بيعة شرعية.", "يُشترط للولاية الكفاءة، وأهم خصائصها العلم وسلامة العقل والبدن."], "k": "هل أحكم على الناس بمالهم ونسبهم، أم بعلمهم وأمانتهم وقدرتهم؟"}, {"lbl": "الآية ٢٤٨", "q": "وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَـٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٤٨﴾", "w": [["نبيهم", "شمويل."], ["آية ملكه", "علامة أن الله ملّكه عليكم."], ["التابوت", "صندوق خشبي فيه بقية من آثار آل موسى وآل هارون."], ["سكينة", "طمأنينة القلب وهدوء النفس."], ["بقية", "ما تبقى من الشيء بعد ذهاب أكثره، وهي هنا رُضاض من الألواح التي تكسّرت، وعصا موسى، وشيء من آثار أنبيائهم."], ["تحمله الملائكة", "من أرض العمالقة فتضعه بين يدي بني إسرائيل في مخيماتهم."], ["إن في ذلك لآية لكم", "أي: في إتيان التابوت الذي أخذه العدو بالقوة منكم ثم ردّه إليكم علامة قوية على اختيار الله لطالوت ملكاً عليكم."]], "m": "قد أصبح بشرح الكلمات معنى الآية واضحاً، وخلاصته أن النبي شمويل أعلمهم أن آية تمليك الله لطالوت عليهم أن يأتيهم التابوت المغصوب منهم، وهو رمز تجمّعهم واتحادهم ومصدر استمداد قوة معنوياتهم لما حواه من آثار آل موسى وآل هارون، كرُضاض الألواح وعصا موسى ونعله وعمامة هارون وشيء من المنّ الذي كان ينزل عليهم في التيه. فكان هذا التابوت بمثابة الراية يقاتلون تحتها، فإنهم إذا خرجوا للقتال حملوه معهم إلى داخل المعركة ولا يزالون يقاتلون ما بقي التابوت بأيديهم لم يغلبهم عليه عدوهم. ومن هنا جعل الله إتيان التابوت آية على تمليك طالوت عليهم، وفي الوقت نفسه يحملونه معهم في قتالهم فتسكن به قلوبهم وتهدأ نفوسهم فيقاتلون وينتصرون بإذن الله. وأما كيفية حمل الملائكة للتابوت فإن الأخبار تقول إن العمالقة تشاءموا بالتابوت عندهم إذ ابتلوا بالأمراض والآفات، ففكروا أن يردّوه لبني إسرائيل، وساق الله أقداراً لأقدار، فجعلوه في عربة تجرها بقرتان ووجّهوها إلى جهة منازل بني إسرائيل، فمشت العربة فساقتها الملائكة حتى وصلت بها إلى منازل بني إسرائيل، فكانت آية وأعظم آية، وقبل بنو إسرائيل بقيادة طالوت.", "h": [], "k": "ما الذي يمنح قلبي السكينة في الشدائد؟ وهل أجده في ذكر الله وطاعته؟"}, {"lbl": "الآيتان ٢٤٩ – ٢٥٠", "q": "فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ ﴿٢٤٩﴾ وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٢٥٠﴾", "w": [["الجنود", "العسكر، وتعدادهم كما قيل سبعون ألف مقاتل."], ["مبتليكم بنهر", "مختبركم بنهر جارٍ."], ["غرفة", "الغَرفة بالفتح المرة، وبالضم الاسم من الاغتراف."], ["الذين آمنوا معه", "هم الذين لم يشربوا من النهر."], ["يظنون أنهم ملاقو الله", "يوقنون أنهم ملاقوه يوم القيامة، فهم يؤمنون بالبعث الآخر."], ["كم من فئة", "كم للتكثير، والفئة الجماعة يفيء بعضها إلى بعض."], ["والله مع الصابرين", "يسددهم ويعينهم وينصرهم."], ["برزوا لجالوت", "ظهروا في ميدان المعركة، وجالوت قائد قوات العمالقة."], ["أفرغ علينا صبراً", "اصبُبْ الصبر في قلوبنا صباً حتى تمتلئ فلا يبقى للخوف والجزع موضع."], ["وثبّت أقدامنا", "في أرض المعركة حتى لا ننهزم، بتقوية قلوبنا والشد من عزائمنا."]], "m": "لما خرج طالوت بالجيش أخبرهم أن الله مختبرهم في سيرهم هذا إلى قتال عدوهم بنهر ينتهون إليه وهم في حر شديد وعطش شديد، ولم يأذن لهم في الشرب منه إلا ما كان من غرفة واحدة، فمن أطاع ولم يشرب فهو المؤمن ومن عصى وشرب غير المأذون به فليس من جنده. ولما وصلوا إلى النهر شربوا منه إلا قليلاً منهم. وواصل طالوت السير فجاوز النهر هو ومن معه، ولما كانوا على مقربة من جيش العدو وكان قرابة مائة ألف، قال من تخلّف: لا طاقة لنا اليوم بجالوت وجنوده، وانصرفوا، وقال المؤمنون الصادقون الذين يوقنون بلقاء الله: كم من فئة قليلة غلبت فئة كثيرة بإذن الله والله مع الصابرين. ولما برزوا لجالوت وجنوده قالوا: ربنا أفرغ علينا صبراً وثبت أقدامنا وانصرنا على القوم الكافرين، دعاءً يملأ القلب بالصبر والثبات.", "h": ["جواز اختبار أفراد الجيش لمعرفة مدى استعدادهم للقتال والصبر عليه.", "فضيلة الإيمان بلقاء الله وفضيلة الصبر على طاعة الله، خاصة في معارك الجهاد في سبيل الله."], "k": "ما «النهر» الذي ابتُليتُ به: أمرٌ أُمرت بترك شيء منه ومالت نفسي إليه؟"}, {"lbl": "الآيتان ٢٥١ – ٢٥٢", "q": "فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ ﴿٢٥١﴾ تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿٢٥٢﴾", "w": [["فهزموهم بإذن الله", "نصر الله جيش طالوت وكان عدد أفراده ثلاثمائة وأربعة عشر مقاتلاً لا غير، لقول الرسول ﷺ لأهل بدر: «إنكم على عدة أصحاب طالوت»؛ فهزم الله جيش الباطل على كثرته ونصر جيش الحق على قلته."], ["وآتاه الله الملك والحكمة", "كان ذلك بعد موت شمويل النبي وموت طالوت الملك."], ["وعلّمه مما يشاء", "فعلّمه صنعة الدروع، وفهم منطق الطير هو وولده سليمان عليهما السلام."], ["لفسدت الأرض", "وذلك بغلبة أهل الشرك على أهل التوحيد، وأهل الكفر على أهل الإيمان."]], "m": "لما التقى الجيشان، جيش الإيمان وجيش الكفر، طالب جالوت بالمبارزة فخرج له داود من جيش طالوت فقتله، والتحم الجيشان فنصر الله جيش طالوت. وهنا ظهر كوكب داود في الأفق بقتله رأس الشر جالوت، فمنّ الله عليه بالنبوة والملك بعد موت كل من النبي شمويل والملك طالوت: وقتل داود جالوت وآتاه الله الملك والحكمة وعلمه مما يشاء. وختم الله القصة ذات العبر والعظات بقوله: ولولا دفع الله الناس بعضهم ببعض، بالجهاد والقتال، لاستولى أهل الكفر وأفسدوا الأرض بالظلم والشرك والمعاصي، ولكن الله بتدبيره الحكيم يسلّط بعضاً على بعض ويدفع بعضاً ببعض منّةً منه وفضلاً، ولذا قال: ولكن الله ذو فضل على العالمين. ثم التفت إلى رسوله محمد ﷺ وقال له تقريراً لنبوته وعلوّ مكانته: تلك آيات الله نتلوها عليك بالحق وإنك لمن المرسلين.", "h": ["بيان الحكمة في مشروعية الجهاد، وهي دفع أهل الكفر والظلم بأهل الإيمان والعدل لتنتظم الحياة ويعمر الكون."], "k": "هل أرى أن النصر والفضل من الله وحده، وأن ما عندي ليس إلا سببٌ مبذول؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 35;
insert into public.tdb_cards(topic, i, body) select 35, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٤٣ – ٢٤٥", "q": "۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٢٤٣﴾ وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٢٤٤﴾ مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢٤٥﴾", "w": [["ألم تر", "ألم ينته إلى علمك؛ فالرؤية قلبية والاستفهام للتعجيب."], ["ألوف", "جمع ألف، وهي صيغة كثرة، فهم إذن عشرات الألوف."], ["في سبيل الله", "الطريق الموصل إلى مرضاته، وهو طاعته بامتثال أمره واجتناب نهيه، ومن ذلك جهاد الكفار والظالمين حتى لا تكون فتنة."], ["يقرض الله", "يقتطع شيئاً من ماله وينفقه في الجهاد لشراء السلاح وتسيير المجاهدين."], ["يقبض ويبسط", "يضيّق ويوسّع؛ يقبض ابتلاءً ويبسط امتحاناً."]], "m": "يخاطب الله رسوله ﷺ فيقول: ألم ينته إلى علمك قصة الذين خرجوا من ديارهم فراراً من الموت وهم ألوف؟ وهم أهل مدينة من مدن بني إسرائيل أصابهم الله بمرض الطاعون، ففروا هاربين من الموت، فأماتهم الله عن آخرهم ثم أحياهم بدعوة نبيهم حزقيل عليه السلام. فهل أنجاهم فرارهم من الموت؟ وكذلك من يفرّ من القتال هل ينجيه فراره من الموت؟ والجواب: لا، وإذن فلم الفرار من الجهاد إذا تعيّن؟ وفي تأديب تلك الجماعة بإماتتها ثم إحيائها فضل من الله عظيم، ولكن أكثر الناس لا يشكرون. وإذن فقاتلوا أيها المسلمون في سبيل الله ولا تتأخروا متى دُعيتم إلى الجهاد بالنفس والمال، واعلموا أن الله سميع لأقوالكم عليم بنياتكم وأعمالكم فاحذروه. ثم فتح باب الاكتتاب المالي لجهاد الأعداء: من ذا الذي يقرض الله قرضاً حسناً، أي بإخلاص وطيب نفس، فإن الله يضاعفه له أضعافاً كثيرة، الدرهم بسبعمائة درهم، فأنفقوا أيها المؤمنون في سبيل إعلاء كلمة الله ولا تخافوا الفقر، فإن ربكم يقبض ويبسط: يضيّق على العبد ابتلاء ويوسّع امتحاناً، فمنعكم الإنفاق في سبيل الله لا يغيّر من تدبير الله شيئاً.", "h": ["إذا نزل الوباء ببلد لا يجوز الخروج فراراً منه، وبهذا ثبتت السنة.", "وجوب ذكر النعم وشكرها.", "وجوب القتال في سبيل الله إذا تعيّن.", "فضل الإنفاق في سبيل الله.", "بيان الحكمة في تضييق الله على العبد رزقه وتوسيعه، وهو الابتلاء لأجل الصبر والامتحان لأجل الشكر؛ فيا خيبة من لم يصبر عند التضييق عليه ولم يشكر عند التوسعة له."], "k": "عند ضيق الرزق وعند سعته: هل أصبر في الأولى وأشكر في الثانية؟"}, {"lbl": "الآيتان ٢٤٦ – ٢٤٧", "q": "أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٢٤٦﴾ وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٢٤٧﴾", "w": [["الملأ", "أشراف الناس من أهل الحل والعقد بينهم، إذا نظر المرء إليهم ملؤوا عينه روعة وقلبه هيبة."], ["عسى", "كلمة توقّع وترجٍّ."], ["كُتب", "فُرض ولزم."], ["ملكاً", "يسوسهم في السلم والحرب."], ["أنى يكون", "الاستفهام للإنكار بمعنى: كيف يكون له الملك؟"], ["اصطفاه", "فضّله عليكم واختاره لكم."], ["بسطة في الجسم", "طولاً زائداً يعلو به من عداه."]], "m": "لما فرض الله القتال ودارت المعارك من بدر، اقتضى الموقف شحذ الهمم، فذكر قصة الملأ من بني إسرائيل بعد موسى إذ قالوا لنبي لهم: ابعث لنا ملكاً نقاتل في سبيل الله. فخاف النبي ألا يصدقوا فقال: هل عسيتم إن كُتب عليكم القتال ألا تقاتلوا؟ فقالوا: وما لنا ألا نقاتل في سبيل الله وقد أُخرجنا من ديارنا وأبنائنا؟ وكان العدو قد غزا فلسطين بعد أن فسق بنو إسرائيل واستباحوا المحرمات وعطلوا الكتاب. فبعث شمويل طالوت، فلما دنوا من المعركة جبنوا وتولى أكثرهم. وفي الآية الثانية اعترض الملأ على تعيين طالوت لأنه فقير من أسرة غير شريفة، فرد نبيهم: إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء. والقيادة القتالية تعتمد على غزارة العلم وقوة البدن وشجاعة العقل والقلب.", "h": ["الجهاد الشرعي يُشترط له الإمام المبايَع بيعة شرعية.", "يُشترط للولاية الكفاءة، وأهم خصائصها العلم وسلامة العقل والبدن."], "k": "هل أحكم على الناس بمالهم ونسبهم، أم بعلمهم وأمانتهم وقدرتهم؟"}, {"lbl": "الآية ٢٤٨", "q": "وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَـٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٤٨﴾", "w": [["نبيهم", "شمويل."], ["آية ملكه", "علامة أن الله ملّكه عليكم."], ["التابوت", "صندوق خشبي فيه بقية من آثار آل موسى وآل هارون."], ["سكينة", "طمأنينة القلب وهدوء النفس."], ["بقية", "ما تبقى من الشيء بعد ذهاب أكثره، وهي هنا رُضاض من الألواح التي تكسّرت، وعصا موسى، وشيء من آثار أنبيائهم."], ["تحمله الملائكة", "من أرض العمالقة فتضعه بين يدي بني إسرائيل في مخيماتهم."], ["إن في ذلك لآية لكم", "أي: في إتيان التابوت الذي أخذه العدو بالقوة منكم ثم ردّه إليكم علامة قوية على اختيار الله لطالوت ملكاً عليكم."]], "m": "قد أصبح بشرح الكلمات معنى الآية واضحاً، وخلاصته أن النبي شمويل أعلمهم أن آية تمليك الله لطالوت عليهم أن يأتيهم التابوت المغصوب منهم، وهو رمز تجمّعهم واتحادهم ومصدر استمداد قوة معنوياتهم لما حواه من آثار آل موسى وآل هارون، كرُضاض الألواح وعصا موسى ونعله وعمامة هارون وشيء من المنّ الذي كان ينزل عليهم في التيه. فكان هذا التابوت بمثابة الراية يقاتلون تحتها، فإنهم إذا خرجوا للقتال حملوه معهم إلى داخل المعركة ولا يزالون يقاتلون ما بقي التابوت بأيديهم لم يغلبهم عليه عدوهم. ومن هنا جعل الله إتيان التابوت آية على تمليك طالوت عليهم، وفي الوقت نفسه يحملونه معهم في قتالهم فتسكن به قلوبهم وتهدأ نفوسهم فيقاتلون وينتصرون بإذن الله. وأما كيفية حمل الملائكة للتابوت فإن الأخبار تقول إن العمالقة تشاءموا بالتابوت عندهم إذ ابتلوا بالأمراض والآفات، ففكروا أن يردّوه لبني إسرائيل، وساق الله أقداراً لأقدار، فجعلوه في عربة تجرها بقرتان ووجّهوها إلى جهة منازل بني إسرائيل، فمشت العربة فساقتها الملائكة حتى وصلت بها إلى منازل بني إسرائيل، فكانت آية وأعظم آية، وقبل بنو إسرائيل بقيادة طالوت.", "h": [], "k": "ما الذي يمنح قلبي السكينة في الشدائد؟ وهل أجده في ذكر الله وطاعته؟"}, {"lbl": "الآيتان ٢٤٩ – ٢٥٠", "q": "فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ ﴿٢٤٩﴾ وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٢٥٠﴾", "w": [["الجنود", "العسكر، وتعدادهم كما قيل سبعون ألف مقاتل."], ["مبتليكم بنهر", "مختبركم بنهر جارٍ."], ["غرفة", "الغَرفة بالفتح المرة، وبالضم الاسم من الاغتراف."], ["الذين آمنوا معه", "هم الذين لم يشربوا من النهر."], ["يظنون أنهم ملاقو الله", "يوقنون أنهم ملاقوه يوم القيامة، فهم يؤمنون بالبعث الآخر."], ["كم من فئة", "كم للتكثير، والفئة الجماعة يفيء بعضها إلى بعض."], ["والله مع الصابرين", "يسددهم ويعينهم وينصرهم."], ["برزوا لجالوت", "ظهروا في ميدان المعركة، وجالوت قائد قوات العمالقة."], ["أفرغ علينا صبراً", "اصبُبْ الصبر في قلوبنا صباً حتى تمتلئ فلا يبقى للخوف والجزع موضع."], ["وثبّت أقدامنا", "في أرض المعركة حتى لا ننهزم، بتقوية قلوبنا والشد من عزائمنا."]], "m": "لما خرج طالوت بالجيش أخبرهم أن الله مختبرهم في سيرهم هذا إلى قتال عدوهم بنهر ينتهون إليه وهم في حر شديد وعطش شديد، ولم يأذن لهم في الشرب منه إلا ما كان من غرفة واحدة، فمن أطاع ولم يشرب فهو المؤمن ومن عصى وشرب غير المأذون به فليس من جنده. ولما وصلوا إلى النهر شربوا منه إلا قليلاً منهم. وواصل طالوت السير فجاوز النهر هو ومن معه، ولما كانوا على مقربة من جيش العدو وكان قرابة مائة ألف، قال من تخلّف: لا طاقة لنا اليوم بجالوت وجنوده، وانصرفوا، وقال المؤمنون الصادقون الذين يوقنون بلقاء الله: كم من فئة قليلة غلبت فئة كثيرة بإذن الله والله مع الصابرين. ولما برزوا لجالوت وجنوده قالوا: ربنا أفرغ علينا صبراً وثبت أقدامنا وانصرنا على القوم الكافرين، دعاءً يملأ القلب بالصبر والثبات.", "h": ["جواز اختبار أفراد الجيش لمعرفة مدى استعدادهم للقتال والصبر عليه.", "فضيلة الإيمان بلقاء الله وفضيلة الصبر على طاعة الله، خاصة في معارك الجهاد في سبيل الله."], "k": "ما «النهر» الذي ابتُليتُ به: أمرٌ أُمرت بترك شيء منه ومالت نفسي إليه؟"}, {"lbl": "الآيتان ٢٥١ – ٢٥٢", "q": "فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ ﴿٢٥١﴾ تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ﴿٢٥٢﴾", "w": [["فهزموهم بإذن الله", "نصر الله جيش طالوت وكان عدد أفراده ثلاثمائة وأربعة عشر مقاتلاً لا غير، لقول الرسول ﷺ لأهل بدر: «إنكم على عدة أصحاب طالوت»؛ فهزم الله جيش الباطل على كثرته ونصر جيش الحق على قلته."], ["وآتاه الله الملك والحكمة", "كان ذلك بعد موت شمويل النبي وموت طالوت الملك."], ["وعلّمه مما يشاء", "فعلّمه صنعة الدروع، وفهم منطق الطير هو وولده سليمان عليهما السلام."], ["لفسدت الأرض", "وذلك بغلبة أهل الشرك على أهل التوحيد، وأهل الكفر على أهل الإيمان."]], "m": "لما التقى الجيشان، جيش الإيمان وجيش الكفر، طالب جالوت بالمبارزة فخرج له داود من جيش طالوت فقتله، والتحم الجيشان فنصر الله جيش طالوت. وهنا ظهر كوكب داود في الأفق بقتله رأس الشر جالوت، فمنّ الله عليه بالنبوة والملك بعد موت كل من النبي شمويل والملك طالوت: وقتل داود جالوت وآتاه الله الملك والحكمة وعلمه مما يشاء. وختم الله القصة ذات العبر والعظات بقوله: ولولا دفع الله الناس بعضهم ببعض، بالجهاد والقتال، لاستولى أهل الكفر وأفسدوا الأرض بالظلم والشرك والمعاصي، ولكن الله بتدبيره الحكيم يسلّط بعضاً على بعض ويدفع بعضاً ببعض منّةً منه وفضلاً، ولذا قال: ولكن الله ذو فضل على العالمين. ثم التفت إلى رسوله محمد ﷺ وقال له تقريراً لنبوته وعلوّ مكانته: تلك آيات الله نتلوها عليك بالحق وإنك لمن المرسلين.", "h": ["بيان الحكمة في مشروعية الجهاد، وهي دفع أهل الكفر والظلم بأهل الإيمان والعدل لتنتظم الحياة ويعمر الكون."], "k": "هل أرى أن النصر والفضل من الله وحده، وأن ما عندي ليس إلا سببٌ مبذول؟"}]$j$::jsonb) with ordinality x(e, i);

select 'تم إضافة الجزء الثاني' as "النتيجة", (select count(*) from public.tdb_topics) as "المواضيع", (select count(*) from public.tdb_cards) as "البطاقات";
